-- Vendrith Supabase production schema baseline (reconstructed from PostgreSQL catalogs)
-- Generated: 2026-10-03
-- Source project: ojtmfokjcirvjvhnbnos
-- Schema only; no production data.
-- Recovery baseline, not a verbatim pg_dump. Authenticate and run Supabase CLI db pull for final byte-for-byte validation before history repair.
SET lock_timeout='10s';
SET statement_timeout=0;
SET search_path=public,extensions;

CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";
-- Identity column on public.map_editor_commands creates the production backing sequence map_editor_commands_sequence_no_seq.

CREATE TABLE IF NOT EXISTS "public"."activities" (id uuid DEFAULT gen_random_uuid() NOT NULL, actor_life_id uuid NOT NULL, activity_definition_id uuid NOT NULL, location_id uuid, start_time timestamp with time zone NOT NULL, end_time timestamp with time zone, state text DEFAULT 'scheduled'::text NOT NULL, metadata jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, cancellation_reason text, cancelled_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS "public"."activity_attribute_affinities" (activity_definition_id uuid NOT NULL, attribute_type text NOT NULL, weight numeric DEFAULT 1 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_completion_transitions" (id uuid DEFAULT gen_random_uuid() NOT NULL, activity_id uuid NOT NULL, schedule_id uuid NOT NULL, next_activity_id uuid, transition_time timestamp with time zone DEFAULT now() NOT NULL, status text DEFAULT 'created'::text NOT NULL, reason text, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_definitions" (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, activity_type text NOT NULL, default_duration numeric, energy_cost numeric, metadata jsonb, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_food_consumptions" (id uuid DEFAULT gen_random_uuid() NOT NULL, activity_id uuid NOT NULL, item_id uuid NOT NULL, quantity numeric DEFAULT 1 NOT NULL, energy_recovery numeric DEFAULT 0 NOT NULL, fatigue_delta numeric DEFAULT 0 NOT NULL, consumed_at timestamp with time zone DEFAULT now() NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, simulation_time timestamp with time zone);
CREATE TABLE IF NOT EXISTS "public"."activity_interruptions" (id uuid DEFAULT gen_random_uuid() NOT NULL, activity_id uuid NOT NULL, cause text NOT NULL, interrupted_at timestamp with time zone NOT NULL, resolved_at timestamp with time zone, resolution text, status text DEFAULT 'active'::text NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_inventory_requirements" (activity_definition_id uuid NOT NULL, item_type text NOT NULL, quantity numeric DEFAULT 1 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_skill_affinities" (activity_definition_id uuid NOT NULL, skill_type text NOT NULL, weight numeric DEFAULT 1 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_skill_xp_awards" (activity_id uuid NOT NULL, skill_type text NOT NULL, experience numeric NOT NULL, awarded_at timestamp with time zone DEFAULT now() NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."activity_xp_policies" (activity_definition_id uuid NOT NULL, base_xp numeric DEFAULT 0 NOT NULL, duration_factor numeric DEFAULT 1 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."ai_activity_need_rules" (activity_definition_id uuid NOT NULL, need_type text NOT NULL, weight numeric DEFAULT 1 NOT NULL, priority_floor numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."ai_archetype_activity_policies" (archetype text NOT NULL, activity_definition_id uuid NOT NULL, score_bonus numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."ai_goal_activity_rules" (id uuid DEFAULT gen_random_uuid() NOT NULL, goal_type text NOT NULL, activity_definition_id uuid NOT NULL, score_bonus numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."ai_improvement_evaluations" (id text NOT NULL, owner_id uuid DEFAULT auth.uid() NOT NULL, task_id text NOT NULL, strategy_id text NOT NULL, validity text NOT NULL, verification_passed boolean NOT NULL, novelty text NOT NULL, difficulty_signal text NOT NULL, evidence jsonb DEFAULT '[]'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."ai_improvement_evaluations" IS 'Vendrith Project AI improvement memory: verification/evaluation evidence only; never treated as project source of truth.';
CREATE TABLE IF NOT EXISTS "public"."ai_improvement_proposals" (id text NOT NULL, owner_id uuid DEFAULT auth.uid() NOT NULL, task_id text NOT NULL, strategy_id text NOT NULL, rationale text NOT NULL, evaluation_id text NOT NULL, requires_approval boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, strategy_description text, strategy_steps jsonb DEFAULT '[]'::jsonb NOT NULL);
COMMENT ON TABLE "public"."ai_improvement_proposals" IS 'Vendrith Project AI improvement proposals. Every proposal requires explicit approval before mutation.';
CREATE TABLE IF NOT EXISTS "public"."asset_binary_verifications" (id uuid DEFAULT gen_random_uuid() NOT NULL, asset_id uuid NOT NULL, verification_status text DEFAULT 'pending'::text NOT NULL, sha256 text, byte_size bigint, verification_method text, repository_path text, lfs_oid text, verified_at timestamp with time zone, notes text, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."asset_binary_verifications" IS 'Binary-level identity and repository verification for canonical asset_registry records. A source match alone never implies binary verification.';
