CREATE TABLE IF NOT EXISTS "public"."container_access" (id uuid DEFAULT gen_random_uuid() NOT NULL, container_id uuid NOT NULL, life_id uuid NOT NULL, access_level text DEFAULT 'use'::text NOT NULL, granted_at timestamp with time zone DEFAULT now() NOT NULL, expires_at timestamp with time zone);
