CREATE TABLE IF NOT EXISTS "public"."containers" (id uuid DEFAULT gen_random_uuid() NOT NULL, owner_type text NOT NULL, owner_id uuid NOT NULL, container_type text NOT NULL, capacity numeric, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, location_id uuid, access_mode text DEFAULT 'owner'::text NOT NULL, is_locked boolean DEFAULT false NOT NULL, owner_life_id uuid);
COMMENT ON TABLE "public"."containers" IS 'Inventory Engine v1.0 checkpoint: ownership containers for inventory storage.';
CREATE TABLE IF NOT EXISTS "public"."continents" (id uuid DEFAULT gen_random_uuid() NOT NULL, world_id uuid NOT NULL, name text NOT NULL, description text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
