CREATE TABLE IF NOT EXISTS "public"."day_records" (id uuid DEFAULT gen_random_uuid() NOT NULL, world_id uuid NOT NULL, simulation_date timestamp with time zone NOT NULL, summary jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL);
