COMMENT ON TABLE "public"."dialogue_choices" IS 'Dialogue Engine v1.0 foundation: player choices and same-conversation navigation.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_conditions" (id uuid DEFAULT gen_random_uuid() NOT NULL, target_type text NOT NULL, target_id uuid NOT NULL, condition_type text NOT NULL, operator text NOT NULL, value jsonb DEFAULT 'null'::jsonb NOT NULL, priority integer DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_conditions" IS 'Dialogue Engine v1.0 foundation: condition records consumed by the runtime evaluator.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_conversations" (id uuid DEFAULT gen_random_uuid() NOT NULL, conversation_key text NOT NULL, title text NOT NULL, description text, conversation_type text DEFAULT 'standard'::text NOT NULL, status text DEFAULT 'active'::text NOT NULL, priority integer DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_conversations" IS 'Dialogue Engine v1.0 foundation: reusable conversation definitions and metadata.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_history" (id uuid DEFAULT gen_random_uuid() NOT NULL, session_id uuid NOT NULL, conversation_id uuid NOT NULL, node_id uuid, choice_id uuid, actor_entity_id uuid, event_type text NOT NULL, "timestamp" timestamp with time zone DEFAULT now() NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL);
