CREATE TABLE IF NOT EXISTS "public"."dialogue_lines" (id uuid DEFAULT gen_random_uuid() NOT NULL, node_id uuid NOT NULL, speaker_entity_id uuid, text text NOT NULL, sequence_order integer DEFAULT 0 NOT NULL, emotion text, voice_key text, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_lines" IS 'Dialogue Engine v1.0 foundation: displayable dialogue lines.';
