COMMENT ON TABLE "public"."dialogue_memories" IS 'Dialogue Engine v1.0 foundation: dialogue-relevant persistent memories.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_nodes" (id uuid DEFAULT gen_random_uuid() NOT NULL, conversation_id uuid NOT NULL, node_key text NOT NULL, node_type text DEFAULT 'line'::text NOT NULL, speaker_entity_id uuid, sequence_order integer DEFAULT 0 NOT NULL, is_entry boolean DEFAULT false NOT NULL, is_terminal boolean DEFAULT false NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_nodes" IS 'Dialogue Engine v1.0 foundation: deterministic conversation tree nodes.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_relationships" (id uuid DEFAULT gen_random_uuid() NOT NULL, source_entity_id uuid NOT NULL, target_entity_id uuid NOT NULL, relationship_type text NOT NULL, value numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_relationships" IS 'Dialogue Engine v1.0 foundation: relationship state used by dialogue conditions.';
