COMMENT ON TABLE "public"."dialogue_sessions" IS 'Dialogue Engine v1.0 foundation: active dialogue runtime sessions.';
CREATE TABLE IF NOT EXISTS "public"."dialogue_states" (id uuid DEFAULT gen_random_uuid() NOT NULL, entity_id uuid NOT NULL, state_key text NOT NULL, state_value jsonb DEFAULT 'null'::jsonb NOT NULL, scope text DEFAULT 'global'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."dialogue_states" IS 'Dialogue Engine v1.0 foundation: persisted dialogue state values.';
CREATE TABLE IF NOT EXISTS "public"."dungeon_connections" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, from_room_id uuid NOT NULL, to_room_id uuid NOT NULL, from_side text NOT NULL, to_side text NOT NULL, from_x integer NOT NULL, from_y integer NOT NULL, to_x integer NOT NULL, to_y integer NOT NULL, opening_width integer DEFAULT 1 NOT NULL, corridor_id uuid, status text DEFAULT 'planned'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_corridors" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, from_room_id uuid NOT NULL, to_room_id uuid NOT NULL, width integer DEFAULT 1 NOT NULL, path jsonb DEFAULT '[]'::jsonb NOT NULL, openings jsonb DEFAULT '[]'::jsonb NOT NULL, status text DEFAULT 'generated'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_openings" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, room_id uuid, corridor_id uuid, x integer NOT NULL, y integer NOT NULL, opening_type text DEFAULT 'door'::text NOT NULL, direction text NOT NULL, width integer DEFAULT 1 NOT NULL, is_walkable boolean DEFAULT true NOT NULL, blocks_when_closed boolean DEFAULT true NOT NULL, state text DEFAULT 'open'::text NOT NULL, asset_id uuid, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_pathfinding_runs" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, connection_id uuid, algorithm text DEFAULT 'astar_v1'::text NOT NULL, status text DEFAULT 'planned'::text NOT NULL, start_x integer NOT NULL, start_y integer NOT NULL, goal_x integer NOT NULL, goal_y integer NOT NULL, path jsonb, cost numeric, nodes_expanded integer, blocked_cells integer, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_rooms" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, origin_x integer NOT NULL, origin_y integer NOT NULL, width integer NOT NULL, height integer NOT NULL, floor_type text DEFAULT 'dungeon'::text NOT NULL, wall_type text DEFAULT 'dungeon'::text NOT NULL, openings jsonb DEFAULT '[]'::jsonb NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_structural_asset_bindings" (id uuid DEFAULT gen_random_uuid() NOT NULL, role_id uuid NOT NULL, asset_id uuid, source_path text, sprite_x integer, sprite_y integer, sprite_width smallint DEFAULT 32, sprite_height smallint DEFAULT 32, binding_status text DEFAULT 'pending'::text NOT NULL, audit_note text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_structural_asset_roles" (id uuid DEFAULT gen_random_uuid() NOT NULL, role_key text NOT NULL, name text NOT NULL, category text NOT NULL, required boolean DEFAULT true NOT NULL, autotile_mode text DEFAULT 'structural'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, enabled boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_structural_profiles" (id uuid DEFAULT gen_random_uuid() NOT NULL, profile_key text NOT NULL, name text NOT NULL, topology text DEFAULT 'structural_8'::text NOT NULL, neighborhood text DEFAULT '8_way'::text NOT NULL, tile_size integer DEFAULT 32 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, enabled boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."dungeon_structural_rules" (id uuid DEFAULT gen_random_uuid() NOT NULL, profile_id uuid NOT NULL, neighbor_mask integer NOT NULL, structural_role text NOT NULL, variant_key text NOT NULL, asset_id uuid, confidence text DEFAULT 'unverified'::text NOT NULL, evidence jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."editor_map_identity" (editor_map_id uuid DEFAULT gen_random_uuid() NOT NULL, legacy_map_id uuid, world_id uuid NOT NULL, map_type text NOT NULL, parent_editor_map_id uuid, created_by uuid DEFAULT auth.uid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."editor_map_identity" IS 'Map Editor stable identity/hierarchy layer; does not redefine public.maps semantics.';
CREATE TABLE IF NOT EXISTS "public"."editor_map_interior" (editor_map_id uuid NOT NULL, playable_editor_map_id uuid NOT NULL, legacy_map_id uuid, building_id uuid, created_by uuid DEFAULT auth.uid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."editor_map_interior" IS 'Explicit Map Editor Interior relation; preserves three-value MapDocument map_type contract.';
CREATE TABLE IF NOT EXISTS "public"."editor_map_versions" (id uuid DEFAULT gen_random_uuid() NOT NULL, editor_map_id uuid NOT NULL, version_number integer NOT NULL, label text DEFAULT 'save'::text NOT NULL, snapshot jsonb NOT NULL, created_by uuid DEFAULT auth.uid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."emotion_definitions" (id uuid DEFAULT gen_random_uuid() NOT NULL, code text NOT NULL, name text NOT NULL, description text, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."emotion_definitions" IS 'Canonical registry for Emotion State types. v1.0 defines structure only; canonical emotion entries are not seeded here.';
CREATE TABLE IF NOT EXISTS "public"."employment" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, organization_id uuid, occupation_id uuid NOT NULL, start_time timestamp with time zone NOT NULL, end_time timestamp with time zone, status text DEFAULT 'active'::text NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."energy_history" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, "timestamp" timestamp with time zone NOT NULL, old_state text, new_state text NOT NULL, cause text, created_at timestamp with time zone DEFAULT now() NOT NULL, simulation_time timestamp with time zone);
CREATE TABLE IF NOT EXISTS "public"."energy_recovery_rules" (id uuid DEFAULT gen_random_uuid() NOT NULL, activity_type text NOT NULL, recovery_amount numeric NOT NULL, fatigue_delta numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."equipment_loadouts" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, slot_type text NOT NULL, item_instance_id uuid NOT NULL, equipped_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."equipment_loadouts" IS 'Inventory Engine equipment state; one item instance per life and slot.';
CREATE TABLE IF NOT EXISTS "public"."event_definitions" (event_type text NOT NULL, condition_type text NOT NULL, consequence_type text NOT NULL, condition_config jsonb DEFAULT '{}'::jsonb NOT NULL, consequence_config jsonb DEFAULT '{}'::jsonb NOT NULL, enabled boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."event_executions" (id uuid DEFAULT gen_random_uuid() NOT NULL, time_event_id uuid NOT NULL, status text DEFAULT 'running'::text NOT NULL, claimed_at timestamp with time zone DEFAULT now() NOT NULL, completed_at timestamp with time zone, error_message text, metadata jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."family_groups" (id uuid DEFAULT gen_random_uuid() NOT NULL, name text, family_type text, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."family_memberships" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, family_id uuid NOT NULL, relation_type text NOT NULL, start_time timestamp with time zone, end_time timestamp with time zone, status text DEFAULT 'active'::text NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."food_effects" (id uuid DEFAULT gen_random_uuid() NOT NULL, item_id uuid NOT NULL, energy_recovery numeric DEFAULT 0 NOT NULL, fatigue_delta numeric DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."food_effects" IS 'Per-item food effects. Values are data-driven so canon values can be locked without changing engine code.';
CREATE TABLE IF NOT EXISTS "public"."history_causes" (id uuid DEFAULT gen_random_uuid() NOT NULL, event_id uuid NOT NULL, cause_type text NOT NULL, cause_reference text, metadata jsonb);
CREATE TABLE IF NOT EXISTS "public"."history_consequences" (id uuid DEFAULT gen_random_uuid() NOT NULL, event_id uuid NOT NULL, consequence_type text NOT NULL, consequence_reference text, metadata jsonb);
CREATE TABLE IF NOT EXISTS "public"."history_events" (id uuid DEFAULT gen_random_uuid() NOT NULL, event_type text NOT NULL, scope_type text NOT NULL, scope_id uuid NOT NULL, "timestamp" timestamp with time zone NOT NULL, summary text, metadata jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."history_locations" (id uuid DEFAULT gen_random_uuid() NOT NULL, event_id uuid NOT NULL, location_id uuid NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."history_participants" (id uuid DEFAULT gen_random_uuid() NOT NULL, event_id uuid NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, role text);
CREATE TABLE IF NOT EXISTS "public"."households" (id uuid DEFAULT gen_random_uuid() NOT NULL, settlement_id uuid, residence_location_id uuid, household_type text NOT NULL, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."inventory_aggregates" (life_id uuid NOT NULL, total_weight numeric DEFAULT 0 NOT NULL, used_capacity numeric DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."inventory_aggregates" IS 'Persisted inventory aggregates; engine-authoritative and recomputable.';
CREATE TABLE IF NOT EXISTS "public"."inventory_consumptions" (id uuid DEFAULT gen_random_uuid() NOT NULL, container_id uuid NOT NULL, item_id uuid NOT NULL, item_instance_id uuid, quantity numeric NOT NULL, actor_life_id uuid, consumption_type text DEFAULT 'consume'::text NOT NULL, status text DEFAULT 'completed'::text NOT NULL, reason text, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, simulation_time timestamp with time zone);
COMMENT ON TABLE "public"."inventory_consumptions" IS 'Inventory Engine v1.0 checkpoint: immutable consumption audit ledger.';
CREATE TABLE IF NOT EXISTS "public"."inventory_entries" (id uuid DEFAULT gen_random_uuid() NOT NULL, container_id uuid NOT NULL, item_id uuid NOT NULL, item_instance_id uuid, quantity numeric DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."inventory_entries" IS 'Inventory Engine v1.0 checkpoint: current item placement and quantity state.';
CREATE TABLE IF NOT EXISTS "public"."inventory_transfers" (id uuid DEFAULT gen_random_uuid() NOT NULL, source_container_id uuid NOT NULL, destination_container_id uuid NOT NULL, item_id uuid NOT NULL, item_instance_id uuid, quantity numeric NOT NULL, actor_life_id uuid, transfer_type text DEFAULT 'move'::text NOT NULL, status text DEFAULT 'completed'::text NOT NULL, reason text, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."inventory_transfers" IS 'Inventory Engine v1.0 checkpoint: immutable transfer audit ledger.';
CREATE TABLE IF NOT EXISTS "public"."item_durability_history" (id uuid DEFAULT gen_random_uuid() NOT NULL, item_instance_id uuid NOT NULL, old_condition numeric NOT NULL, new_condition numeric NOT NULL, delta numeric NOT NULL, old_is_broken boolean NOT NULL, new_is_broken boolean NOT NULL, cause text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."item_durability_history" IS 'Inventory Engine v1.0 checkpoint: immutable durability transition history.';
CREATE TABLE IF NOT EXISTS "public"."item_instances" (id uuid DEFAULT gen_random_uuid() NOT NULL, item_id uuid NOT NULL, quantity numeric DEFAULT 1 NOT NULL, condition numeric, metadata jsonb, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, max_durability numeric, is_broken boolean DEFAULT false NOT NULL, quest_bound boolean DEFAULT false NOT NULL, lifecycle_status text DEFAULT 'active'::text NOT NULL);
COMMENT ON TABLE "public"."item_instances" IS 'Inventory Engine v1.0 checkpoint: unique item instances with lifecycle and durability state.';
CREATE TABLE IF NOT EXISTS "public"."items" (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, item_type text NOT NULL, stackable boolean DEFAULT true NOT NULL, metadata jsonb, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, max_stack_size numeric DEFAULT 1 NOT NULL, base_weight numeric DEFAULT 0 NOT NULL, base_durability numeric DEFAULT 0 NOT NULL, base_value numeric DEFAULT 0 NOT NULL, quest_bound_default boolean DEFAULT false NOT NULL);
COMMENT ON TABLE "public"."items" IS 'Inventory Engine v1.0 checkpoint: item definitions and static item metadata.';
CREATE TABLE IF NOT EXISTS "public"."languages" (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, description text, status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."legacies" (id uuid DEFAULT gen_random_uuid() NOT NULL, identity text NOT NULL, origin text, creator_entity_type text, creator_entity_id uuid, purpose text, creation_time timestamp with time zone, current_status text DEFAULT 'active'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."legacy_links" (id uuid DEFAULT gen_random_uuid() NOT NULL, legacy_id uuid NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, relationship_type text, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."legacy_modifications" (id uuid DEFAULT gen_random_uuid() NOT NULL, legacy_id uuid NOT NULL, old_version integer NOT NULL, new_version integer NOT NULL, modifier_entity_type text, modifier_entity_id uuid, reason text, history_event_id uuid, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."legacy_versions" (id uuid DEFAULT gen_random_uuid() NOT NULL, legacy_id uuid NOT NULL, version_number integer NOT NULL, state jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, reason text);
CREATE TABLE IF NOT EXISTS "public"."life_ai_decisions" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, goal_id uuid, activity_definition_id uuid, decision_type text DEFAULT 'activity_selection'::text NOT NULL, score numeric(12,4), reason jsonb DEFAULT '{}'::jsonb NOT NULL, context jsonb DEFAULT '{}'::jsonb NOT NULL, selected boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, simulation_time timestamp with time zone, activity_id uuid);
CREATE TABLE IF NOT EXISTS "public"."life_ai_goals" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, goal_type text NOT NULL, title text NOT NULL, status text DEFAULT 'active'::text NOT NULL, priority numeric(10,3) DEFAULT 0 NOT NULL, progress numeric(10,3) DEFAULT 0 NOT NULL, target_value numeric(10,3), current_value numeric(10,3) DEFAULT 0 NOT NULL, source text DEFAULT 'ai'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, started_at timestamp with time zone DEFAULT now() NOT NULL, completed_at timestamp with time zone, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."life_ai_profiles" (life_id uuid NOT NULL, archetype text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."life_attributes" (life_id uuid NOT NULL, attribute_type text NOT NULL, value numeric NOT NULL, source text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."life_currency" (life_id uuid NOT NULL, currency_type text DEFAULT 'gold'::text NOT NULL, balance numeric DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."life_currency" IS 'Inventory Engine currency balances, separated from item stacks.';
CREATE TABLE IF NOT EXISTS "public"."life_emotion_history" (id uuid DEFAULT gen_random_uuid() NOT NULL, life_id uuid NOT NULL, emotion_definition_id uuid NOT NULL, previous_intensity numeric DEFAULT 0 NOT NULL, new_intensity numeric NOT NULL, delta numeric NOT NULL, cause_type text NOT NULL, cause_id uuid, cause_metadata jsonb DEFAULT '{}'::jsonb NOT NULL, changed_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."life_emotion_history" IS 'Append-only audit trail for Emotion State changes, recording previous/new intensity and the cause of change.';
CREATE TABLE IF NOT EXISTS "public"."life_emotions" (life_id uuid NOT NULL, emotion_definition_id uuid NOT NULL, intensity numeric DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."life_emotions" IS 'Current Emotion State for each Life. Changes are expected to be driven by causes/events and later recorded through History.';
CREATE TABLE IF NOT EXISTS "public"."life_energy" (life_id uuid NOT NULL, current_energy numeric NOT NULL, max_energy numeric NOT NULL, fatigue numeric DEFAULT 0 NOT NULL, state text DEFAULT 'normal'::text NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."life_identity" (life_id uuid NOT NULL, species text, form_type text, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."life_needs" (life_id uuid NOT NULL, need_type text NOT NULL, current_value numeric NOT NULL, target_value numeric NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, simulation_time timestamp with time zone);
CREATE TABLE IF NOT EXISTS "public"."life_skills" (life_id uuid NOT NULL, skill_type text NOT NULL, skill_id uuid, level numeric DEFAULT 0 NOT NULL, experience numeric DEFAULT 0 NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."lives" (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, sex text, birth_date timestamp with time zone, death_date timestamp with time zone, status text DEFAULT 'alive'::text NOT NULL, location_id uuid, household_id uuid, fate_grade text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."location_routes" (id uuid DEFAULT gen_random_uuid() NOT NULL, origin_location_id uuid NOT NULL, destination_location_id uuid NOT NULL, distance_km numeric(12,3) NOT NULL, travel_speed_kmh numeric(10,3) DEFAULT 5 NOT NULL, travel_cost numeric(12,3) DEFAULT 0 NOT NULL, route_type text DEFAULT 'road'::text NOT NULL, is_enabled boolean DEFAULT true NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."locations" (id uuid DEFAULT gen_random_uuid() NOT NULL, region_id uuid NOT NULL, name text NOT NULL, location_type text NOT NULL, description text, parent_location_id uuid, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_annotations" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, annotation_type text NOT NULL, text_value text, geometry jsonb NOT NULL, properties jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_building_placements" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, layer_id uuid NOT NULL, building_id uuid NOT NULL, z_index integer DEFAULT 0 NOT NULL, locked boolean DEFAULT false NOT NULL, visible boolean DEFAULT true NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_cells" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, grid_x integer NOT NULL, grid_y integer NOT NULL, elevation integer DEFAULT 0 NOT NULL, biome text, terrain_asset_id uuid, structural_asset_id uuid, decoration_asset_id uuid, terrain_variant text, season_variant text, collision boolean DEFAULT false NOT NULL, walkable boolean DEFAULT true NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_connections" (id uuid DEFAULT gen_random_uuid() NOT NULL, source_map_id uuid NOT NULL, target_map_id uuid NOT NULL, connection_type text NOT NULL, source_position jsonb NOT NULL, target_position jsonb NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_coordinate_profiles" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_type text NOT NULL, coordinate_mode text NOT NULL, grid_unit integer NOT NULL, origin_mode text DEFAULT 'top_left'::text NOT NULL, snap_mode text DEFAULT 'grid'::text NOT NULL, min_zoom numeric(8,3) DEFAULT 0.25 NOT NULL, max_zoom numeric(8,3) DEFAULT 8 NOT NULL, default_zoom numeric(8,3) DEFAULT 1 NOT NULL, camera_mode text DEFAULT 'pan_zoom'::text NOT NULL, allow_rotation boolean DEFAULT false NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, enabled boolean DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_clipboards" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, user_id uuid, clipboard_key text DEFAULT 'default'::text NOT NULL, payload jsonb DEFAULT '[]'::jsonb NOT NULL, object_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_command_groups" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, user_id uuid, group_key text DEFAULT 'default'::text NOT NULL, label text DEFAULT 'Edit'::text NOT NULL, status text DEFAULT 'open'::text NOT NULL, command_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, closed_at timestamp with time zone, metadata jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_commands" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, sequence_no bigint GENERATED ALWAYS AS IDENTITY NOT NULL, command_type text NOT NULL, entity_type text NOT NULL, entity_id uuid, forward_payload jsonb DEFAULT '{}'::jsonb NOT NULL, inverse_payload jsonb DEFAULT '{}'::jsonb NOT NULL, status text DEFAULT 'applied'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_gizmo_sessions" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, user_id uuid, selection_key text DEFAULT 'default'::text NOT NULL, operation text NOT NULL, axis text DEFAULT 'xy'::text NOT NULL, start_x numeric DEFAULT 0 NOT NULL, start_y numeric DEFAULT 0 NOT NULL, current_x numeric DEFAULT 0 NOT NULL, current_y numeric DEFAULT 0 NOT NULL, snap_mode text DEFAULT 'all'::text NOT NULL, status text DEFAULT 'active'::text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, closed_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS "public"."map_editor_layer_rules" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, layer_id uuid NOT NULL, selectable boolean DEFAULT true NOT NULL, editable boolean DEFAULT true NOT NULL, snap_enabled boolean DEFAULT true NOT NULL, collision_enabled boolean DEFAULT true NOT NULL, visible boolean DEFAULT true NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_runtime_snapshots" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, version_id uuid, snapshot jsonb NOT NULL, created_by uuid DEFAULT auth.uid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."map_editor_runtime_snapshots" IS 'Owner-scoped runtime snapshot bridge for MapDocument/editor state; authoritative map_versions remains the durable version record.';
CREATE TABLE IF NOT EXISTS "public"."map_editor_save_slots" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, slot_number smallint NOT NULL, label text DEFAULT ''::text NOT NULL, version_id uuid, version_number integer NOT NULL, snapshot jsonb NOT NULL, created_by uuid DEFAULT auth.uid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."map_editor_save_slots" IS 'Game-like manual save slots for the Vandrith map editor. Each slot points at an immutable map version snapshot.';
CREATE TABLE IF NOT EXISTS "public"."map_editor_selections" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, user_id uuid, selection_key text DEFAULT 'default'::text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, selected_at timestamp with time zone DEFAULT now() NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_editor_snap_settings" (map_id uuid NOT NULL, grid_size numeric DEFAULT 1 NOT NULL, grid_enabled boolean DEFAULT true NOT NULL, object_snap_enabled boolean DEFAULT true NOT NULL, edge_snap_enabled boolean DEFAULT true NOT NULL, center_snap_enabled boolean DEFAULT true NOT NULL, snap_tolerance numeric DEFAULT 0.35 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_environment_policies" (map_id uuid NOT NULL, receives_world_weather boolean DEFAULT true NOT NULL, precipitation_allowed boolean DEFAULT true NOT NULL, temperature_passthrough boolean DEFAULT true NOT NULL, visibility_passthrough boolean DEFAULT true NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
COMMENT ON TABLE "public"."map_environment_policies" IS 'Simulation-owned environment policy. Client read/write disabled by security_table_boundaries; access through engine-controlled paths.';
CREATE TABLE IF NOT EXISTS "public"."map_layers" (id uuid DEFAULT gen_random_uuid() NOT NULL, map_id uuid NOT NULL, name text NOT NULL, layer_type text NOT NULL, z_index integer DEFAULT 0 NOT NULL, visible boolean DEFAULT true NOT NULL, locked boolean DEFAULT false NOT NULL, opacity numeric(5,4) DEFAULT 1.0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "public"."map_navigation_cells" (map_id uuid NOT NULL, x integer NOT NULL, y integer NOT NULL, cell_type text DEFAULT 'empty'::text NOT NULL, walkable boolean DEFAULT false NOT NULL, collision boolean DEFAULT true NOT NULL, room_id uuid, corridor_id uuid, opening_id uuid, layer integer DEFAULT 0 NOT NULL, metadata jsonb DEFAULT '{}'::jsonb NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL);
