CREATE OR REPLACE FUNCTION public.editor_duplicate_object_leaf_v2(p_object_id uuid, p_dx numeric DEFAULT 1, p_dy numeric DEFAULT 0, p_snap_mode text DEFAULT 'all'::text, p_snap_tolerance numeric DEFAULT 0.35)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare o public.map_objects%rowtype; r jsonb; v jsonb; nx numeric; ny numeric; nid uuid; begin
 select * into o from public.map_objects where id=p_object_id; if not found then return jsonb_build_object('ok',false,'code','OBJECT_NOT_FOUND'); end if;
 r:=public.resolve_map_object_snap_v2(o.map_id,o.x+p_dx,o.y+p_dy,p_snap_mode,p_snap_tolerance,o.id); if not coalesce((r->>'ok')::boolean,false) then return r; end if;
 nx:=(r->>'x')::numeric; ny:=(r->>'y')::numeric;
 v:=public.validate_duplicate_geometry_pipeline_v1(o.map_id,o.id,nx,ny,o.rotation,o.scale_x,o.scale_y); if not coalesce((v->>'ok')::boolean,false) then return v; end if;
 insert into public.map_objects(map_id,layer_id,asset_id,entity_type,entity_id,x,y,rotation,scale_x,scale_y,z_index,collision_enabled,interactable,footprint,properties,object_type,width,height,blocks_los) values(o.map_id,o.layer_id,o.asset_id,o.entity_type,o.entity_id,nx,ny,o.rotation,o.scale_x,o.scale_y,o.z_index,o.collision_enabled,o.interactable,o.footprint,o.properties,o.object_type,o.width,o.height,o.blocks_los) returning id into nid;
 perform public.sync_map_object_obb_v1(nid); perform public.sync_map_object_footprint(nid);
 return jsonb_build_object('ok',true,'source_object_id',o.id,'object_id',nid,'x',nx,'y',ny,'rotation',o.rotation,'scale_x',o.scale_x,'scale_y',o.scale_y,'geometry_engine','OBB_SAT_V1'); end; $function$;


CREATE OR REPLACE FUNCTION public.editor_place_object_leaf_v2(p_map_id uuid, p_asset_id uuid, p_object_type text, p_x numeric, p_y numeric, p_rotation numeric DEFAULT 0, p_layer_id uuid DEFAULT NULL::uuid, p_width integer DEFAULT 1, p_height integer DEFAULT 1, p_blocks_movement boolean DEFAULT false, p_blocks_los boolean DEFAULT false, p_footprint jsonb DEFAULT NULL::jsonb, p_properties jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare r jsonb; oid uuid; fp jsonb; begin if p_asset_id is not null and not exists(select 1 from public.asset_registry where id=p_asset_id and status='approved') then return jsonb_build_object('ok',false,'code','ASSET_NOT_APPROVED'); end if; fp:=coalesce(p_footprint,'[{"x":0,"y":0}]'::jsonb); r:=public.resolve_map_object_snap_v2(p_map_id,p_x,p_y,'all',0.35,null); if not coalesce((r->>'ok')::boolean,false) then return r; end if; if p_rotation not in (0,90,180,270) then return jsonb_build_object('ok',false,'code','INVALID_ROTATION'); end if; if exists(select 1 from public.map_objects o where o.map_id=p_map_id and o.layer_id is not distinct from p_layer_id and o.collision_enabled=true and public.obb_sat_overlap_v1(public.get_map_object_obb_v1(o.id),jsonb_build_object('center_x',(r->>'x')::numeric,'center_y',(r->>'y')::numeric,'half_width',greatest(0.5,p_width/2.0),'half_height',greatest(0.5,p_height/2.0),'rotation',p_rotation))) then return jsonb_build_object('ok',false,'code','SAT_COLLISION'); end if; insert into public.map_objects(map_id,layer_id,asset_id,entity_type,x,y,rotation,scale_x,scale_y,z_index,collision_enabled,interactable,footprint,properties,object_type,width,height,blocks_los) values(p_map_id,p_layer_id,p_asset_id,p_object_type,(r->>'x')::numeric,(r->>'y')::numeric,p_rotation,1,1,0,p_blocks_movement,false,fp,coalesce(p_properties,'{}'::jsonb),p_object_type,p_width,p_height,p_blocks_los) returning id into oid; perform public.sync_map_object_obb_v1(oid); perform public.sync_map_object_footprint(oid); return jsonb_build_object('ok',true,'object_id',oid,'geometry_engine','OBB_SAT_V1'); end; $function$;


CREATE OR REPLACE FUNCTION public.editor_batch_selection_duplicate_leaf_v2(p_map_id uuid, p_selection_key text DEFAULT 'default'::text, p_dx numeric DEFAULT 0, p_dy numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare s record; o public.map_objects%rowtype; v jsonb; created integer:=0; begin for s in select entity_id from public.map_editor_selections where map_id=p_map_id and selection_key=p_selection_key and entity_type='map_object' order by selected_at loop select * into o from public.map_objects where id=s.entity_id and map_id=p_map_id; if not found then continue; end if; v:=public.editor_duplicate_legacy_bridge_v1(p_map_id,o.id,o.x+p_dx,o.y+p_dy,o.rotation,o.scale_x,o.scale_y); if not coalesce((v->>'ok')::boolean,false) then return v||jsonb_build_object('created_before_failure',created); end if; created:=created+1; end loop; return jsonb_build_object('ok',true,'operation','duplicate_selection','objects_created',created,'selection_key',p_selection_key); end; $function$;


CREATE OR REPLACE FUNCTION public.editor_batch_selection_transform_leaf_v2(p_map_id uuid, p_selection_key text DEFAULT 'default'::text, p_dx numeric DEFAULT 0, p_dy numeric DEFAULT 0, p_rotation_delta numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare s record; o public.map_objects%rowtype; v jsonb; nr numeric; gid uuid; cmd jsonb; r jsonb; changed int:=0; uid uuid:=auth.uid(); begin if uid is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if; if not exists(select 1 from public.maps where id=p_map_id and created_by=uid) then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if; perform pg_advisory_xact_lock(hashtextextended('map-editor:'||p_map_id::text||':'||coalesce(p_selection_key,'default'),0)); if p_rotation_delta not in (-270,-180,-90,0,90,180,270) then return jsonb_build_object('ok',false,'code','INVALID_ROTATION_DELTA'); end if; for s in select entity_id from public.map_editor_selections where map_id=p_map_id and selection_key=p_selection_key and entity_type='map_object' order by selected_at loop select * into o from public.map_objects where id=s.entity_id and map_id=p_map_id; if not found then continue; end if; nr:=mod(o.rotation+p_rotation_delta+360,360); v:=public.validate_map_object_geometry_pipeline_v1(o.id,o.x+p_dx,o.y+p_dy,nr,o.scale_x,o.scale_y,o.layer_id); if not coalesce((v->>'ok')::boolean,false) then return v||jsonb_build_object('atomic_rejected',true,'objects_changed',0); end if; end loop; select (public.begin_map_editor_command_group(p_map_id,case when p_rotation_delta<>0 and (p_dx<>0 or p_dy<>0) then 'Gizmo move+rotate' when p_rotation_delta<>0 then 'Gizmo rotate' else 'Gizmo move' end,p_selection_key)::jsonb->>'group_id')::uuid into gid; for s in select entity_id from public.map_editor_selections where map_id=p_map_id and selection_key=p_selection_key and entity_type='map_object' order by selected_at loop select * into o from public.map_objects where id=s.entity_id and map_id=p_map_id for update; if not found then continue; end if; nr:=mod(o.rotation+p_rotation_delta+360,360); v:=public.editor_batch_transform_leaf_v1(o.id,o.x+p_dx,o.y+p_dy,nr,o.scale_x,o.scale_y,o.layer_id); if not coalesce((v->>'ok')::boolean,false) then raise exception 'ATOMIC_TRANSFORM_FAILED:%',v; end if; cmd:=jsonb_build_object('before',jsonb_build_object('x',o.x,'y',o.y,'rotation',o.rotation,'scale_x',o.scale_x,'scale_y',o.scale_y,'layer_id',o.layer_id),'after',jsonb_build_object('x',o.x+p_dx,'y',o.y+p_dy,'rotation',nr,'scale_x',o.scale_x,'scale_y',o.scale_y,'layer_id',o.layer_id)); r:=public.record_map_editor_command(p_map_id,'transform_object','map_object',o.id,cmd->'after',cmd->'before'); if not coalesce((r->>'ok')::boolean,false) then raise exception 'COMMAND_RECORD_FAILED:%',r; end if; update public.map_editor_commands set metadata=coalesce(metadata,'{}')||jsonb_build_object('group_id',gid) where id=(r->>'command_id')::uuid; changed:=changed+1; end loop; update public.map_editor_command_groups set command_count=changed,metadata=coalesce(metadata,'{}')||jsonb_build_object('commands',jsonb_build_object('dx',p_dx,'dy',p_dy,'rotation_delta',p_rotation_delta),'atomic',true) where id=gid; perform public.close_map_editor_command_group(gid); return jsonb_build_object('ok',true,'operation','transform_selection','objects_transformed',changed,'selection_key',p_selection_key,'group_id',gid,'atomic',true); exception when others then return jsonb_build_object('ok',false,'code','SELECTION_TRANSFORM_FAILED','error',sqlerrm,'atomic_rejected',true,'objects_changed',0); end; $function$;


CREATE OR REPLACE FUNCTION public.create_dungeon_opening(p_map_id uuid, p_x integer, p_y integer, p_direction text, p_opening_type text, p_room_id uuid, p_corridor_id uuid, p_width integer, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare o public.dungeon_openings%rowtype;
begin
 if not exists(select 1 from public.maps where id=p_map_id and created_by=auth.uid()) then return jsonb_build_object('ok',false,'code','MAP_NOT_OWNED'); end if;
 if p_room_id is not null and not exists(select 1 from public.dungeon_rooms where id=p_room_id and map_id=p_map_id) then return jsonb_build_object('ok',false,'code','ROOM_NOT_IN_MAP'); end if;
 if p_corridor_id is not null and not exists(select 1 from public.dungeon_corridors where id=p_corridor_id and map_id=p_map_id) then return jsonb_build_object('ok',false,'code','CORRIDOR_NOT_IN_MAP'); end if;
 if p_direction not in ('north','south','east','west') then return jsonb_build_object('ok',false,'code','INVALID_DIRECTION'); end if;
 if p_opening_type not in ('door','archway','corridor','secret','portal','passage') then return jsonb_build_object('ok',false,'code','INVALID_OPENING_TYPE'); end if;
 if p_width < 1 or p_width > 16 then return jsonb_build_object('ok',false,'code','INVALID_WIDTH'); end if;
 if p_room_id is null and p_corridor_id is null then return jsonb_build_object('ok',false,'code','OWNER_REQUIRED'); end if;
 insert into public.dungeon_openings(map_id,room_id,corridor_id,x,y,opening_type,direction,width,asset_id,metadata)
 values(p_map_id,p_room_id,p_corridor_id,p_x,p_y,p_opening_type,p_direction,p_width,p_asset_id,jsonb_build_object('created_by','dungeon_opening_engine_v1')) returning * into o;
 return jsonb_build_object('ok',true,'opening_id',o.id,'x',o.x,'y',o.y,'direction',o.direction,'type',o.opening_type,'state',o.state);
end; $function$;


CREATE OR REPLACE FUNCTION public.generate_dungeon_room(p_map_id uuid, p_origin_x integer, p_origin_y integer, p_width integer, p_height integer, p_openings jsonb, p_replace boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare room_id uuid; x integer; y integer; is_boundary boolean; opening boolean; floor_asset uuid; wall_asset uuid; inserted_count integer:=0; opening_item jsonb;
begin
 if not exists(select 1 from public.maps where id=p_map_id and created_by=auth.uid()) then return jsonb_build_object('ok',false,'code','MAP_NOT_OWNED'); end if;
 if p_width < 3 or p_height < 3 then return jsonb_build_object('ok',false,'code','ROOM_TOO_SMALL'); end if;
 if p_replace then delete from public.map_cells where map_id=p_map_id and grid_x between p_origin_x and p_origin_x+p_width-1 and grid_y between p_origin_y and p_origin_y+p_height-1; end if;
 select asset_id into floor_asset from public.dungeon_structural_rules where structural_role='floor' and confidence='verified' and neighbor_mask=255 limit 1;
 select asset_id into wall_asset from public.dungeon_structural_rules where structural_role='wall' and confidence='verified' and neighbor_mask=255 limit 1;
 if floor_asset is null or wall_asset is null then return jsonb_build_object('ok',false,'code','MISSING_VERIFIED_CORE_ASSETS'); end if;
 insert into public.dungeon_rooms(map_id,origin_x,origin_y,width,height,openings) values(p_map_id,p_origin_x,p_origin_y,p_width,p_height,p_openings) returning id into room_id;
 for y in p_origin_y..p_origin_y+p_height-1 loop
   for x in p_origin_x..p_origin_x+p_width-1 loop
     is_boundary := x=p_origin_x or x=p_origin_x+p_width-1 or y=p_origin_y or y=p_origin_y+p_height-1;
     opening := false;
     for opening_item in select * from jsonb_array_elements(case when jsonb_typeof(p_openings)='array' then p_openings else '[]'::jsonb end) loop
       if (opening_item->>'x')::int=x and (opening_item->>'y')::int=y then opening:=true; exit; end if;
     end loop;
     insert into public.map_cells(map_id,grid_x,grid_y,structural_asset_id,collision,walkable,metadata)
     values(p_map_id,x,y,case when is_boundary and not opening then wall_asset else floor_asset end,case when is_boundary and not opening then true else false end,case when is_boundary and not opening then false else true end,jsonb_build_object('generator','dungeon_room_v1','room_id',room_id,'role',case when is_boundary and not opening then 'wall' else 'floor' end,'opening',opening))
     on conflict (map_id,grid_x,grid_y) do update set structural_asset_id=excluded.structural_asset_id,collision=excluded.collision,walkable=excluded.walkable,metadata=excluded.metadata,updated_at=now();
     inserted_count:=inserted_count+1;
   end loop;
 end loop;
 return jsonb_build_object('ok',true,'room_id',room_id,'cells_written',inserted_count,'origin',jsonb_build_array(p_origin_x,p_origin_y),'size',jsonb_build_array(p_width,p_height));
end; $function$;


CREATE OR REPLACE FUNCTION public.plan_dungeon_room_connection(p_from_room_id uuid, p_to_room_id uuid, p_opening_width integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare a public.dungeon_rooms%rowtype; b public.dungeon_rooms%rowtype; fs text; ts text; fx integer; fy integer; tx integer; ty integer; c_id uuid;
begin
 if p_opening_width<1 or p_opening_width>8 then return jsonb_build_object('ok',false,'code','INVALID_OPENING_WIDTH'); end if;
 select * into a from public.dungeon_rooms where id=p_from_room_id; if not found then return jsonb_build_object('ok',false,'code','FROM_ROOM_NOT_FOUND'); end if;
 select * into b from public.dungeon_rooms where id=p_to_room_id; if not found then return jsonb_build_object('ok',false,'code','TO_ROOM_NOT_FOUND'); end if;
 if a.map_id<>b.map_id then return jsonb_build_object('ok',false,'code','ROOMS_DIFFERENT_MAPS'); end if;
 if not exists(select 1 from public.maps where id=a.map_id and created_by=auth.uid()) then return jsonb_build_object('ok',false,'code','MAP_NOT_OWNED'); end if;
 if (a.origin_x+a.width/2) < (b.origin_x+b.width/2) then fs:='east'; ts:='west'; fx:=a.origin_x+a.width-1; tx:=b.origin_x; fy:=great(a.origin_y,least(b.origin_y+b.height-1,a.origin_y+a.height/2)); ty:=great(b.origin_y,least(a.origin_y+a.height-1,b.origin_y+b.height/2));
 else fs:='west'; ts:='east'; fx:=a.origin_x; tx:=b.origin_x+b.width-1; fy:=great(a.origin_y,least(b.origin_y+b.height-1,a.origin_y+a.height/2)); ty:=great(b.origin_y,least(a.origin_y+a.height-1,b.origin_y+b.height/2)); end if;
 insert into public.dungeon_connections(map_id,from_room_id,to_room_id,from_side,to_side,from_x,from_y,to_x,to_y,opening_width,status,metadata) values(a.map_id,a.id,b.id,fs,ts,fx,fy,tx,ty,p_opening_width,'planned',jsonb_build_object('algorithm','relative-center-v1')) returning id into c_id;
 return jsonb_build_object('ok',true,'connection_id',c_id,'from_side',fs,'to_side',ts,'from_x',fx,'from_y',fy,'to_x',tx,'to_y',ty);
end; $function$;


CREATE OR REPLACE FUNCTION public.set_dungeon_opening_state(p_opening_id uuid, p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare o public.dungeon_openings%rowtype;
begin
 if p_state not in ('open','closed','locked','hidden') then return jsonb_build_object('ok',false,'code','INVALID_STATE'); end if;
 select * into o from public.dungeon_openings where id=p_opening_id;
 if not found then return jsonb_build_object('ok',false,'code','OPENING_NOT_FOUND'); end if;
 if not exists(select 1 from public.maps where id=o.map_id and created_by=auth.uid()) then return jsonb_build_object('ok',false,'code','MAP_NOT_OWNED'); end if;
 update public.dungeon_openings set state=p_state,is_walkable=(p_state='open'),updated_at=now() where id=p_opening_id;
 return jsonb_build_object('ok',true,'opening_id',p_opening_id,'state',p_state,'is_walkable',(p_state='open'));
end; $function$;


CREATE OR REPLACE FUNCTION public.set_map_cell(p_map_id uuid, p_grid_x integer, p_grid_y integer, p_terrain_asset_id uuid DEFAULT NULL::uuid, p_structural_asset_id uuid DEFAULT NULL::uuid, p_decoration_asset_id uuid DEFAULT NULL::uuid, p_elevation integer DEFAULT 0, p_biome text DEFAULT NULL::text, p_season_variant text DEFAULT NULL::text, p_collision boolean DEFAULT false, p_walkable boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare v_id uuid; begin if not exists(select 1 from public.maps where id=p_map_id and created_by=auth.uid()) then raise exception 'MAP_NOT_OWNED'; end if; insert into public.map_cells(map_id,grid_x,grid_y,terrain_asset_id,structural_asset_id,decoration_asset_id,elevation,biome,season_variant,collision,walkable,metadata) values(p_map_id,p_grid_x,p_grid_y,p_terrain_asset_id,p_structural_asset_id,p_decoration_asset_id,p_elevation,p_biome,p_season_variant,p_collision,p_walkable,coalesce(p_metadata,'{}'::jsonb)) on conflict(map_id,grid_x,grid_y) do update set terrain_asset_id=excluded.terrain_asset_id,structural_asset_id=excluded.structural_asset_id,decoration_asset_id=excluded.decoration_asset_id,elevation=excluded.elevation,biome=excluded.biome,season_variant=excluded.season_variant,collision=excluded.collision,walkable=excluded.walkable,metadata=excluded.metadata,updated_at=now() returning id into v_id; return v_id; end; $function$;


CREATE OR REPLACE FUNCTION public.editor_paste_leaf_v2(p_map_id uuid, p_clipboard_key text, p_x numeric, p_y numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare cb public.map_editor_clipboards%rowtype; item jsonb; sx numeric; sy numeric; dx numeric; dy numeric; nx numeric; ny numeric; rot numeric; sw numeric; sh numeric; oid uuid; ids uuid[]:='{}'; created integer:=0; group_id uuid; begin select * into cb from public.map_editor_clipboards where map_id=p_map_id and clipboard_key=p_clipboard_key order by updated_at desc limit 1; if not found or cb.object_count=0 then return jsonb_build_object('ok',false,'code','CLIPBOARD_EMPTY'); end if; for item in select value from jsonb_array_elements(cb.payload) loop if (item->>'asset_id') is not null and not exists(select 1 from public.asset_registry where id=(item->>'asset_id')::uuid and status='approved') then return jsonb_build_object('ok',false,'code','ASSET_NOT_APPROVED'); end if; end loop; sx:=coalesce((cb.payload->0->>'x')::numeric,0); sy:=coalesce((cb.payload->0->>'y')::numeric,0); dx:=p_x-sx; dy:=p_y-sy; for item in select value from jsonb_array_elements(cb.payload) loop nx:=round(coalesce((item->>'x')::numeric,0)+dx); ny:=round(coalesce((item->>'y')::numeric,0)+dy); rot:=coalesce((item->>'rotation')::numeric,0); sw:=greatest(0.5,coalesce((item->>'width')::numeric,1)*coalesce((item->>'scale_x')::numeric,1)/2.0); sh:=greatest(0.5,coalesce((item->>'height')::numeric,1)*coalesce((item->>'scale_y')::numeric,1)/2.0); if exists(select 1 from public.map_objects o where o.map_id=p_map_id and o.layer_id is not distinct from (item->>'layer_id')::uuid and o.collision_enabled=true and public.obb_sat_overlap_v1(public.get_map_object_obb_v1(o.id),jsonb_build_object('center_x',nx,'center_y',ny,'half_width',sw,'half_height',sh,'rotation',rot))) then return jsonb_build_object('ok',false,'code','SAT_COLLISION','x',nx,'y',ny); end if; end loop; select (public.begin_map_editor_command_group(p_map_id,'Paste clipboard','default')::jsonb->>'group_id')::uuid into group_id; for item in select value from jsonb_array_elements(cb.payload) loop nx:=round(coalesce((item->>'x')::numeric,0)+dx); ny:=round(coalesce((item->>'y')::numeric,0)+dy); insert into public.map_objects(map_id,layer_id,asset_id,entity_type,entity_id,x,y,rotation,scale_x,scale_y,z_index,collision_enabled,interactable,footprint,properties,object_type,width,height,blocks_los) values(p_map_id,(item->>'layer_id')::uuid,(item->>'asset_id')::uuid,item->>'entity_type',(item->>'entity_id')::uuid,nx,ny,coalesce((item->>'rotation')::numeric,0),coalesce((item->>'scale_x')::numeric,1),coalesce((item->>'scale_y')::numeric,1),coalesce((item->>'z_index')::integer,0),coalesce((item->>'collision_enabled')::boolean,false),coalesce((item->>'interactable')::boolean,false),item->'footprint',coalesce(item->'properties','{}'::jsonb),item->>'object_type',coalesce((item->>'width')::integer,1),coalesce((item->>'height')::integer,1),coalesce((item->>'blocks_los')::boolean,false)) returning id into oid; ids:=ids||oid; perform public.sync_map_object_obb_v1(oid); perform public.sync_map_object_footprint(oid); created:=created+1; end loop; update public.map_editor_command_groups set command_count=created,metadata=metadata||jsonb_build_object('new_object_ids',to_jsonb(ids),'geometry_engine','OBB_SAT_V1') where id=group_id; perform public.close_map_editor_command_group(group_id); return jsonb_build_object('ok',true,'group_id',group_id,'objects_created',created,'object_ids',to_jsonb(ids),'geometry_engine','OBB_SAT_V1'); end; $function$;


CREATE OR REPLACE FUNCTION public.transform_selected_gizmo_atomic(p_map_id uuid, p_selection_key text, p_operation text, p_rotation_delta numeric, p_scale_x_multiplier numeric, p_scale_y_multiplier numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare s record; o public.map_objects%rowtype; v jsonb; nr numeric; nsx numeric; nsy numeric; group_id uuid; commands jsonb:='[]'::jsonb; affected integer:=0; rec jsonb; r jsonb; uid uuid:=auth.uid(); begin if uid is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if; if not exists(select 1 from public.maps where id=p_map_id and created_by=uid) then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if; perform pg_advisory_xact_lock(hashtextextended('map-editor:'||p_map_id::text||':'||coalesce(p_selection_key,'default'),0)); if p_operation not in ('rotate','scale') then return jsonb_build_object('ok',false,'code','INVALID_GIZMO_OPERATION'); end if; if p_rotation_delta not in (-270,-180,-90,0,90,180,270) then return jsonb_build_object('ok',false,'code','INVALID_ROTATION_DELTA'); end if; if p_scale_x_multiplier<=0 or p_scale_y_multiplier<=0 or p_scale_x_multiplier>64 or p_scale_y_multiplier>64 then return jsonb_build_object('ok',false,'code','INVALID_SCALE_MULTIPLIER'); end if; for s in select entity_id from public.map_editor_selections where map_id=p_map_id and selection_key=p_selection_key and entity_type='map_object' order by selected_at loop select * into o from public.map_objects where id=s.entity_id and map_id=p_map_id; if not found then continue; end if; nr:=case when p_operation='rotate' then mod(o.rotation+p_rotation_delta+360,360) else o.rotation end; nsx:=case when p_operation='scale' then o.scale_x*p_scale_x_multiplier else o.scale_x end; nsy:=case when p_operation='scale' then o.scale_y*p_scale_y_multiplier else o.scale_y end; v:=public.validate_map_object_geometry_pipeline_v1(o.id,o.x,o.y,nr,nsx,nsy,o.layer_id); if not coalesce((v->>'ok')::boolean,false) then return v||jsonb_build_object('atomic_rejected',true,'objects_changed',0); end if; end loop; select (public.begin_map_editor_command_group(p_map_id,case when p_operation='rotate' then 'Gizmo rotate' else 'Gizmo scale' end,p_selection_key)::jsonb->>'group_id')::uuid into group_id; for s in select entity_id from public.map_editor_selections where map_id=p_map_id and selection_key=p_selection_key and entity_type='map_object' order by selected_at loop select * into o from public.map_objects where id=s.entity_id and map_id=p_map_id for update; if not found then continue; end if; nr:=case when p_operation='rotate' then mod(o.rotation+p_rotation_delta+360,360) else o.rotation end; nsx:=case when p_operation='scale' then o.scale_x*p_scale_x_multiplier else o.scale_x end; nsy:=case when p_operation='scale' then o.scale_y*p_scale_y_multiplier else o.scale_y end; perform public.remove_map_object_footprint(o.id); update public.map_objects set rotation=nr,scale_x=nsx,scale_y=nsy,updated_at=now() where id=o.id; perform public.sync_map_object_obb_v1(o.id); perform public.sync_map_object_footprint(o.id); rec:=jsonb_build_object('object_id',o.id,'before',jsonb_build_object('x',o.x,'y',o.y,'rotation',o.rotation,'scale_x',o.scale_x,'scale_y',o.scale_y,'layer_id',o.layer_id),'after',jsonb_build_object('x',o.x,'y',o.y,'rotation',nr,'scale_x',nsx,'scale_y',nsy,'layer_id',o.layer_id)); commands:=commands||jsonb_build_array(rec); r:=public.record_map_editor_command(p_map_id,'transform_object','map_object',o.id,rec->'after',rec->'before'); if not coalesce((r->>'ok')::boolean,false) then raise exception 'COMMAND_RECORD_FAILED %',r; end if; update public.map_editor_commands set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('group_id',group_id) where id=(r->>'command_id')::uuid; affected:=affected+1; end loop; update public.map_editor_command_groups set command_count=affected,metadata=coalesce(metadata,'{}')||jsonb_build_object('commands',commands,'atomic',true) where id=group_id; perform public.close_map_editor_command_group(group_id); return jsonb_build_object('ok',true,'group_id',group_id,'objects_transformed',affected,'operation',p_operation,'atomic',true); exception when others then return jsonb_build_object('ok',false,'code','GIZMO_ATOMIC_FAILED','error',sqlerrm,'atomic_rejected',true,'objects_changed',0); end; $function$;


CREATE OR REPLACE FUNCTION public.execute_map_editor_command(p_command_id uuid, p_direction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c public.map_editor_commands%rowtype;
  p jsonb;
  uid uuid := auth.uid();
  object_id uuid;
BEGIN
  IF uid IS NULL THEN RETURN jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); END IF;
  IF p_direction NOT IN ('forward','inverse') THEN RETURN jsonb_build_object('ok',false,'code','INVALID_DIRECTION'); END IF;
  SELECT * INTO c FROM public.map_editor_commands WHERE id=p_command_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','COMMAND_NOT_FOUND'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.maps WHERE id=c.map_id AND created_by=uid) THEN RETURN jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); END IF;
  IF p_direction='forward' THEN
    IF c.status <> 'undone' THEN RETURN jsonb_build_object('ok',false,'code','REDO_NOT_AVAILABLE','status',c.status); END IF;
  ELSE
    IF c.status NOT IN ('applied','redone') THEN RETURN jsonb_build_object('ok',false,'code','UNDO_NOT_AVAILABLE','status',c.status); END IF;
  END IF;
  p := CASE WHEN p_direction='forward' THEN c.forward_payload ELSE c.inverse_payload END;

  IF c.entity_type='map_object' AND c.command_type='create_object' THEN
    object_id := c.entity_id;
    IF p_direction='inverse' THEN
      IF NOT EXISTS (SELECT 1 FROM public.map_objects WHERE id=object_id AND map_id=c.map_id) THEN
        RETURN jsonb_build_object('ok',false,'code','OBJECT_NOT_FOUND','object_id',object_id);
      END IF;
      PERFORM public.remove_map_object_footprint(object_id);
      DELETE FROM public.map_objects WHERE id=object_id AND map_id=c.map_id;
      UPDATE public.map_editor_commands SET status='undone' WHERE id=c.id;
      RETURN jsonb_build_object('ok',true,'command_id',c.id,'direction','inverse','status','undone');
    ELSE
      IF EXISTS (SELECT 1 FROM public.map_objects WHERE id=object_id) THEN
        RETURN jsonb_build_object('ok',false,'code','OBJECT_ALREADY_EXISTS','object_id',object_id);
      END IF;
      INSERT INTO public.map_objects(id,map_id,layer_id,asset_id,entity_type,entity_id,x,y,rotation,scale_x,scale_y,z_index,collision_enabled,interactable,footprint,properties,object_type,width,height,blocks_los)
      VALUES(object_id,c.map_id,(p->>'layer_id')::uuid,(p->>'asset_id')::uuid,p->>'entity_type',NULLIF(p->>'entity_id','')::uuid,(p->>'x')::numeric,(p->>'y')::numeric,(p->>'rotation')::numeric,COALESCE((p->>'scale_x')::numeric,1),COALESCE((p->>'scale_y')::numeric,1),COALESCE((p->>'z_index')::int,0),COALESCE((p->>'collision_enabled')::boolean,false),COALESCE((p->>'interactable')::boolean,false),COALESCE(p->'footprint','[{"x":0,"y":0}]'::jsonb),COALESCE(p->'properties','{}'::jsonb),COALESCE(p->>'object_type','prop'),COALESCE((p->>'width')::int,1),COALESCE((p->>'height')::int,1),COALESCE((p->>'blocks_los')::boolean,false));
      PERFORM public.sync_map_object_obb_v1(object_id);
      PERFORM public.sync_map_object_footprint(object_id);
      UPDATE public.map_editor_commands SET status='redone' WHERE id=c.id;
      RETURN jsonb_build_object('ok',true,'command_id',c.id,'direction','forward','status','redone');
    END IF;
  END IF;

  IF c.entity_type='map_object' AND c.command_type='delete_object' THEN
    IF p_direction='forward' THEN
      PERFORM public.editor_delete_object_leaf_v1(c.entity_id);
    ELSE
      INSERT INTO public.map_objects(id,map_id,layer_id,asset_id,entity_type,entity_id,x,y,rotation,scale_x,scale_y,z_index,collision_enabled,interactable,footprint,properties,object_type,width,height,blocks_los)
      VALUES((p->>'id')::uuid,c.map_id,(p->>'layer_id')::uuid,(p->>'asset_id')::uuid,p->>'entity_type',NULLIF(p->>'entity_id','')::uuid,(p->>'x')::numeric,(p->>'y')::numeric,(p->>'rotation')::numeric,COALESCE((p->>'scale_x')::numeric,1),COALESCE((p->>'scale_y')::numeric,1),COALESCE((p->>'z_index')::int,0),COALESCE((p->>'collision_enabled')::boolean,false),COALESCE((p->>'interactable')::boolean,false),COALESCE(p->'footprint','[{"x":0,"y":0}]'::jsonb),COALESCE(p->'properties','{}'::jsonb),COALESCE(p->>'object_type','prop'),COALESCE((p->>'width')::int,1),COALESCE((p->>'height')::int,1),COALESCE((p->>'blocks_los')::boolean,false));
      PERFORM public.sync_map_object_obb_v1((p->>'id')::uuid);
      PERFORM public.sync_map_object_footprint((p->>'id')::uuid);
    END IF;
  ELSIF c.entity_type='map_object' AND c.command_type IN ('transform_object','rotate_object') THEN
    PERFORM public.remove_map_object_footprint(c.entity_id);
    UPDATE public.map_objects SET x=COALESCE((p->>'x')::numeric,x),y=COALESCE((p->>'y')::numeric,y),rotation=COALESCE((p->>'rotation')::numeric,rotation),scale_x=COALESCE((p->>'scale_x')::numeric,scale_x),scale_y=COALESCE((p->>'scale_y')::numeric,scale_y),layer_id=COALESCE((p->>'layer_id')::uuid,layer_id),updated_at=now() WHERE id=c.entity_id AND map_id=c.map_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'code','OBJECT_NOT_FOUND','object_id',c.entity_id); END IF;
    PERFORM public.sync_map_object_obb_v1(c.entity_id);
    PERFORM public.sync_map_object_footprint(c.entity_id);
  ELSE
    IF c.entity_type<>'map_object' THEN RETURN jsonb_build_object('ok',false,'code','UNSUPPORTED_COMMAND_ENTITY'); END IF;
    RETURN jsonb_build_object('ok',false,'code','UNSUPPORTED_COMMAND');
  END IF;

  UPDATE public.map_editor_commands SET status=CASE WHEN p_direction='forward' THEN 'redone' ELSE 'undone' END WHERE id=c.id;
  RETURN jsonb_build_object('ok',true,'command_id',c.id,'direction',p_direction,'status',CASE WHEN p_direction='forward' THEN 'redone' ELSE 'undone' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok',false,'code','COMMAND_EXECUTION_FAILED','error',SQLERRM);
END;
$function$;


CREATE OR REPLACE FUNCTION public.validate_layer_aware_object_transform(p_object_id uuid, p_x numeric, p_y numeric, p_rotation numeric, p_target_layer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare o public.map_objects%rowtype; ctx jsonb; lid uuid; nav_layer integer; nx integer; ny integer; nr numeric; f jsonb; begin select * into o from public.map_objects where id=p_object_id; if not found then return jsonb_build_object('ok',false,'code','OBJECT_NOT_FOUND'); end if; ctx:=public.get_editor_object_layer_context(o.id,p_target_layer_id); if not (ctx->>'editable')::boolean then return jsonb_build_object('ok',false,'code','LAYER_NOT_EDITABLE','layer_id',ctx->>'layer_id'); end if; if not (ctx->>'visible')::boolean then return jsonb_build_object('ok',false,'code','LAYER_HIDDEN','layer_id',ctx->>'layer_id'); end if; if p_rotation is not null and p_rotation not in (0,90,180,270) then return jsonb_build_object('ok',false,'code','INVALID_ROTATION'); end if; lid:=(ctx->>'layer_id')::uuid; select ml.z_index into nav_layer from public.map_layers ml where ml.id=lid and ml.map_id=o.map_id; if nav_layer is null then return jsonb_build_object('ok',false,'code','LAYER_NOT_FOUND','layer_id',lid); end if; nx:=round(p_x)::integer; ny:=round(p_y)::integer; nr:=coalesce(p_rotation,o.rotation); for f in select value from jsonb_array_elements(coalesce(o.footprint,'[{"x":0,"y":0}]'::jsonb)) loop if (ctx->>'collision_enabled')::boolean and exists(select 1 from public.map_navigation_cells n where n.map_id=o.map_id and n.x=nx+coalesce((f->>'x')::integer,0) and n.y=ny+coalesce((f->>'y')::integer,0) and n.layer=nav_layer and n.collision=true and coalesce(n.metadata->>'object_id','')<>o.id::text) then return jsonb_build_object('ok',false,'code','LAYER_COLLISION','x',nx,'y',ny,'layer_id',lid,'navigation_layer',nav_layer); end if; end loop; return jsonb_build_object('ok',true,'layer_id',lid,'navigation_layer',nav_layer,'x',nx,'y',ny,'rotation',nr,'snap_enabled',(ctx->>'snap_enabled')::boolean,'collision_enabled',(ctx->>'collision_enabled')::boolean); end; $function$;


CREATE OR REPLACE FUNCTION public.rebuild_map_navigation_projection_v1(p_map_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare c record; o record; n record; rebuilt integer:=0; begin if not exists(select 1 from public.maps where id=p_map_id) then return jsonb_build_object('ok',false,'code','MAP_NOT_FOUND'); end if; delete from public.map_navigation_cells where map_id=p_map_id; for c in select mc.map_id,mc.grid_x x,mc.grid_y y,mc.collision,mc.walkable,mc.metadata from public.map_cells mc where mc.map_id=p_map_id loop insert into public.map_navigation_cells(map_id,x,y,cell_type,walkable,collision,layer,metadata) values(c.map_id,c.x,c.y,case when c.collision then 'wall' when c.walkable then 'floor' else 'empty' end,c.walkable,c.collision,0,jsonb_build_object('sync_source','navigation_projection_cell_v1')||coalesce(c.metadata,'{}'::jsonb)) on conflict(map_id,x,y) do update set cell_type=excluded.cell_type,walkable=excluded.walkable,collision=excluded.collision,layer=excluded.layer,metadata=excluded.metadata,updated_at=now(); end loop; for n in select mno.* from public.map_navigation_obstacles mno where mno.map_id=p_map_id loop insert into public.map_navigation_cells(map_id,x,y,cell_type,walkable,collision,layer,metadata) values(n.map_id,n.x,n.y,'obstacle',not n.blocks_movement,n.blocks_movement,n.layer,jsonb_build_object('obstacle_id',n.id,'sync_source','navigation_projection_cell_v1')) on conflict(map_id,x,y) do update set collision=(public.map_navigation_cells.collision or excluded.collision),walkable=(public.map_navigation_cells.walkable and excluded.walkable),cell_type=case when excluded.collision then 'obstacle' else public.map_navigation_cells.cell_type end,layer=excluded.layer,metadata=public.map_navigation_cells.metadata||jsonb_build_object('obstacle_id',n.id,'sync_source','navigation_projection_cell_v1'),updated_at=now(); end loop; for o in select mo.*,ml.z_index nav_layer from public.map_objects mo join public.map_layers ml on ml.id=mo.layer_id and ml.map_id=mo.map_id where mo.map_id=p_map_id and mo.collision_enabled=true loop for c in select value from jsonb_array_elements(coalesce(o.footprint,'[{"x":0,"y":0}]'::jsonb)) loop insert into public.map_navigation_cells(map_id,x,y,cell_type,walkable,collision,layer,metadata) values(o.map_id,round(o.x)::integer+coalesce((c.value->>'x')::integer,0),round(o.y)::integer+coalesce((c.value->>'y')::integer,0),'obstacle',false,true,o.nav_layer,jsonb_build_object('object_id',o.id,'sync_source','navigation_projection_cell_v1')) on conflict(map_id,x,y) do update set collision=true,walkable=false,cell_type='obstacle',layer=coalesce(o.nav_layer,public.map_navigation_cells.layer),metadata=public.map_navigation_cells.metadata||jsonb_build_object('object_id',o.id,'sync_source','navigation_projection_cell_v1'),updated_at=now(); rebuilt:=rebuilt+1; end loop; end loop; return jsonb_build_object('ok',true,'map_id',p_map_id,'object_cells_projected',rebuilt,'source','map_cells+map_navigation_obstacles+map_objects'); end; $function$;


CREATE OR REPLACE FUNCTION public.refresh_map_navigation_cell_v1(p_map_id uuid, p_x integer, p_y integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare base_collision boolean:=false; base_walkable boolean:=true; base_exists boolean:=false; final_collision boolean:=false; final_walkable boolean:=true; obstacle_id uuid; obstacle_layer integer; object_id uuid; object_layer integer; meta jsonb:='{}'::jsonb; begin select coalesce(mc.collision,false),coalesce(mc.walkable,true),true into base_collision,base_walkable,base_exists from public.map_cells mc where mc.map_id=p_map_id and mc.grid_x=p_x and mc.grid_y=p_y limit 1; if not found then base_collision:=false;base_walkable:=true;base_exists:=false; end if; select o.id,o.layer into obstacle_id,obstacle_layer from public.map_navigation_obstacles o where o.map_id=p_map_id and o.x=p_x and o.y=p_y and o.blocks_movement=true order by o.updated_at desc limit 1; if not found then obstacle_id:=null;obstacle_layer:=null;end if; select mo.id,ml.z_index into object_id,object_layer from public.map_objects mo join public.map_layers ml on ml.id=mo.layer_id and ml.map_id=mo.map_id join lateral jsonb_array_elements(coalesce(mo.footprint,'[{"x":0,"y":0}]'::jsonb)) fp on true where mo.map_id=p_map_id and mo.collision_enabled=true and round(mo.x)::integer+coalesce((fp->>'x')::integer,0)=p_x and round(mo.y)::integer+coalesce((fp->>'y')::integer,0)=p_y order by mo.updated_at desc limit 1; if not found then object_id:=null;object_layer:=null;end if; final_collision:=base_collision or obstacle_id is not null or object_id is not null; final_walkable:=base_walkable and obstacle_id is null and object_id is null; if obstacle_id is not null then meta:=meta||jsonb_build_object('obstacle_id',obstacle_id); end if; if object_id is not null then meta:=meta||jsonb_build_object('object_id',object_id); end if; meta:=meta||jsonb_build_object('sync_source','navigation_projection_cell_v1'); if not base_exists and obstacle_id is null and object_id is null then delete from public.map_navigation_cells where map_id=p_map_id and x=p_x and y=p_y; return jsonb_build_object('ok',true,'action','deleted','x',p_x,'y',p_y); end if; insert into public.map_navigation_cells(map_id,x,y,cell_type,walkable,collision,layer,metadata) values(p_map_id,p_x,p_y,case when final_collision then 'obstacle' when base_walkable then 'floor' else 'empty' end,final_walkable,final_collision,coalesce(object_layer,obstacle_layer,0),meta) on conflict(map_id,x,y) do update set cell_type=excluded.cell_type,walkable=excluded.walkable,collision=excluded.collision,layer=excluded.layer,metadata=excluded.metadata,updated_at=now(); return jsonb_build_object('ok',true,'action','upserted','x',p_x,'y',p_y,'collision',final_collision,'walkable',final_walkable); end; $function$;


CREATE OR REPLACE FUNCTION public.refresh_map_navigation_cell_v1(p_map_id uuid, p_x integer, p_y integer, p_exclude_object_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$ declare base_collision boolean:=false; base_walkable boolean:=true; base_exists boolean:=false; final_collision boolean:=false; final_walkable boolean:=true; obstacle_id uuid; obstacle_layer integer; object_id uuid; object_layer integer; meta jsonb:='{}'::jsonb; begin select coalesce(mc.collision,false),coalesce(mc.walkable,true),true into base_collision,base_walkable,base_exists from public.map_cells mc where mc.map_id=p_map_id and mc.grid_x=p_x and mc.grid_y=p_y limit 1; if not found then base_collision:=false;base_walkable:=true;base_exists:=false; end if; select o.id,o.layer into obstacle_id,obstacle_layer from public.map_navigation_obstacles o where o.map_id=p_map_id and o.x=p_x and o.y=p_y and o.blocks_movement=true order by o.updated_at desc limit 1; if not found then obstacle_id:=null;obstacle_layer:=null;end if; select mo.id,ml.z_index into object_id,object_layer from public.map_objects mo join public.map_layers ml on ml.id=mo.layer_id and ml.map_id=mo.map_id join lateral jsonb_array_elements(coalesce(mo.footprint,'[{"x":0,"y":0}]'::jsonb)) fp on true where mo.map_id=p_map_id and mo.collision_enabled=true and mo.id is distinct from p_exclude_object_id and round(mo.x)::integer+coalesce((fp->>'x')::integer,0)=p_x and round(mo.y)::integer+coalesce((fp->>'y')::integer,0)=p_y order by mo.updated_at desc limit 1; if not found then object_id:=null;object_layer:=null;end if; final_collision:=base_collision or obstacle_id is not null or object_id is not null; final_walkable:=base_walkable and obstacle_id is null and object_id is null; if obstacle_id is not null then meta:=meta||jsonb_build_object('obstacle_id',obstacle_id); end if; if object_id is not null then meta:=meta||jsonb_build_object('object_id',object_id); end if; meta:=meta||jsonb_build_object('sync_source','navigation_projection_cell_v1'); if not base_exists and obstacle_id is null and object_id is null then delete from public.map_navigation_cells where map_id=p_map_id and x=p_x and y=p_y; return jsonb_build_object('ok',true,'action','deleted','x',p_x,'y',p_y); end if; insert into public.map_navigation_cells(map_id,x,y,cell_type,walkable,collision,layer,metadata) values(p_map_id,p_x,p_y,case when final_collision then 'obstacle' when base_walkable then 'floor' else 'empty' end,final_walkable,final_collision,coalesce(object_layer,obstacle_layer,0),meta) on conflict(map_id,x,y) do update set cell_type=excluded.cell_type,walkable=excluded.walkable,collision=excluded.collision,layer=excluded.layer,metadata=excluded.metadata,updated_at=now(); return jsonb_build_object('ok',true,'action','upserted','x',p_x,'y',p_y,'collision',final_collision,'walkable',final_walkable); end; $function$;


CREATE OR REPLACE FUNCTION public.find_map_object_obb_collisions_v1(p_map_id uuid, p_object_id uuid, p_rotation numeric, p_scale_x numeric, p_scale_y numeric, p_x numeric, p_y numeric)
 RETURNS TABLE(object_id uuid, collision boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ select o.id, public.obb_sat_overlap_v1(p_x,p_y,greatest(0,coalesce(src.width,1)*p_scale_x/2),greatest(0,coalesce(src.height,1)*p_scale_y/2),mod(p_rotation+360,360),(b->>'center_x')::numeric,(b->>'center_y')::numeric,(b->>'half_width')::numeric,(b->>'half_height')::numeric,(b->>'rotation')::numeric) from public.map_objects src join public.map_objects o on o.id<>p_object_id and o.map_id=p_map_id and o.layer_id=src.layer_id cross join lateral public.get_map_object_obb_v1(o.id) b where src.id=p_object_id and o.collision_enabled=true; $function$;


CREATE OR REPLACE FUNCTION public.undo_map_editor_command_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare r jsonb; c record; n int:=0; gid uuid; uid uuid:=auth.uid(); begin if uid is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if; select map_id into gid from public.map_editor_command_groups where id=p_group_id and user_id=uid; if gid is null then return jsonb_build_object('ok',false,'code','GROUP_ACCESS_DENIED'); end if; for c in select id from public.map_editor_commands where metadata->>'group_id'=p_group_id::text and status in ('applied','redone') order by created_at desc,id desc loop r:=public.undo_map_editor_command(c.id); if not coalesce((r->>'ok')::boolean,false) then raise exception 'GROUP_UNDO_FAILED:%',r; end if; n:=n+1; end loop; update public.map_editor_command_groups set status='undone',metadata=coalesce(metadata,'{}')||jsonb_build_object('last_action','undo') where id=p_group_id; return jsonb_build_object('ok',true,'group_id',p_group_id,'action','undo','commands_undone',n); exception when others then return jsonb_build_object('ok',false,'code','GROUP_UNDO_FAILED','error',sqlerrm,'group_id',p_group_id); end; $function$;


CREATE OR REPLACE FUNCTION public.redo_map_editor_command_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare r jsonb; c record; n int:=0; g public.map_editor_command_groups%rowtype; uid uuid:=auth.uid(); begin if uid is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if; select * into g from public.map_editor_command_groups where id=p_group_id for update; if not found then return jsonb_build_object('ok',false,'code','GROUP_NOT_FOUND'); end if; if g.user_id<>uid or not exists(select 1 from public.maps where id=g.map_id and created_by=uid) then return jsonb_build_object('ok',false,'code','GROUP_ACCESS_DENIED'); end if; if coalesce(g.metadata->>'branch_abandoned','false')='true' then return jsonb_build_object('ok',false,'code','REDO_BRANCH_ABANDONED','group_id',p_group_id); end if; for c in select id from public.map_editor_commands where metadata->>'group_id'=p_group_id::text and status='undone' order by created_at,id loop r:=public.redo_map_editor_command(c.id); if not coalesce((r->>'ok')::boolean,false) then raise exception 'GROUP_REDO_FAILED:%',r; end if; n:=n+1; end loop; if n=0 then return jsonb_build_object('ok',false,'code','REDO_NOT_AVAILABLE','group_id',p_group_id); end if; update public.map_editor_command_groups set status='closed',metadata=coalesce(metadata,'{}')||jsonb_build_object('last_action','redo') where id=p_group_id; return jsonb_build_object('ok',true,'group_id',p_group_id,'action','redo','commands_redone',n); exception when others then return jsonb_build_object('ok',false,'code','GROUP_REDO_FAILED','error',sqlerrm,'group_id',p_group_id); end; $function$;


CREATE OR REPLACE FUNCTION public.consume_inventory_item_authorized(p_container_id uuid, p_item_id uuid, p_quantity numeric DEFAULT 1, p_item_instance_id uuid DEFAULT NULL::uuid, p_actor_life_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ begin if auth.uid() is null then raise exception 'inventory_consume_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_consume_actor_required'; end if; if not exists(select 1 from public.user_lives ul where ul.user_id=auth.uid() and ul.life_id=p_actor_life_id) then raise exception 'inventory_consume_actor_not_owned'; end if; if not public.can_mutate_container(p_container_id,p_actor_life_id,'use') then raise exception 'inventory_consume_not_authorized'; end if; return public.consume_inventory_item(p_container_id,p_item_id,p_quantity,p_item_instance_id,p_actor_life_id,p_reason,p_metadata); end;$function$;


CREATE OR REPLACE FUNCTION public.transfer_inventory_instance_authorized(p_source_container_id uuid, p_destination_container_id uuid, p_item_instance_id uuid, p_actor_life_id uuid DEFAULT NULL::uuid, p_transfer_type text DEFAULT 'move'::text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ begin if auth.uid() is null then raise exception 'inventory_instance_transfer_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_instance_transfer_actor_required'; end if; if not exists(select 1 from public.user_lives ul where ul.user_id=auth.uid() and ul.life_id=p_actor_life_id) then raise exception 'inventory_instance_transfer_actor_not_owned'; end if; if not public.can_mutate_container(p_source_container_id,p_actor_life_id,'use') then raise exception 'inventory_instance_transfer_source_not_authorized'; end if; if not public.can_mutate_container(p_destination_container_id,p_actor_life_id,'use') then raise exception 'inventory_instance_transfer_destination_not_authorized'; end if; return public.transfer_inventory_instance(p_source_container_id,p_destination_container_id,p_item_instance_id,p_actor_life_id,p_transfer_type,p_reason,p_metadata); end;$function$;


CREATE OR REPLACE FUNCTION public.transfer_inventory_authorized(p_source_container_id uuid, p_destination_container_id uuid, p_item_id uuid, p_quantity numeric, p_actor_life_id uuid DEFAULT NULL::uuid, p_transfer_type text DEFAULT 'move'::text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ declare uid uuid:=auth.uid(); v_item public.items%rowtype; v_src public.containers%rowtype; v_dst public.containers%rowtype; v_src_qty numeric; v_dst_qty numeric; begin if uid is null then raise exception 'inventory_transfer_auth_required'; end if; if p_actor_life_id is null then raise exception 'inventory_transfer_actor_required'; end if; if not exists(select 1 from public.user_lives where user_id=uid and life_id=p_actor_life_id) then raise exception 'inventory_transfer_actor_not_owned'; end if; if p_source_container_id=p_destination_container_id then raise exception 'inventory_transfer_same_container'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'inventory_transfer_invalid_quantity'; end if; if not public.can_mutate_container(p_source_container_id,p_actor_life_id,'use') then raise exception 'inventory_transfer_source_not_authorized'; end if; if not public.can_mutate_container(p_destination_container_id,p_actor_life_id,'use') then raise exception 'inventory_transfer_destination_not_authorized'; end if; select * into v_item from public.items where id=p_item_id for share; if not found or v_item.status<>'active' then raise exception 'inventory_transfer_item_invalid'; end if; if not v_item.stackable then raise exception 'inventory_transfer_use_instance_path'; end if; select * into v_src from public.containers where id=least(p_source_container_id,p_destination_container_id) for update; select * into v_dst from public.containers where id=greatest(p_source_container_id,p_destination_container_id) for update; if v_src.id is null or v_dst.id is null then raise exception 'inventory_transfer_container_missing'; end if; select quantity into v_src_qty from public.inventory_entries where container_id=p_source_container_id and item_id=p_item_id and item_instance_id is null for update; if v_src_qty is null then raise exception 'inventory_transfer_source_item_missing'; end if; if v_src_qty<p_quantity then raise exception 'inventory_transfer_insufficient_quantity'; end if; select coalesce(quantity,0) into v_dst_qty from public.inventory_entries where container_id=p_destination_container_id and item_id=p_item_id and item_instance_id is null for update; if v_dst_qty+p_quantity>v_item.max_stack_size then raise exception 'inventory_transfer_stack_limit_exceeded'; end if; if v_dst.capacity is not null then if (select coalesce(sum(quantity),0) from public.inventory_entries where container_id=p_destination_container_id)+p_quantity>v_dst.capacity then raise exception 'inventory_transfer_capacity_exceeded'; end if; end if; return public.transfer_inventory(p_source_container_id,p_destination_container_id,p_item_id,p_quantity,p_actor_life_id,p_transfer_type,p_reason,p_metadata); end;$function$;


CREATE OR REPLACE FUNCTION public.resolve_weather_candidate_v1(p_season_id uuid, p_roll numeric DEFAULT NULL::numeric)
 RETURNS TABLE(weather_id uuid, weather_key text, display_name text, intensity smallint, selection_weight numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_roll numeric := coalesce(p_roll, random()::numeric);
  v_total numeric;
begin
  if p_season_id is null then
    raise exception 'p_season_id is required';
  end if;

  if v_roll < 0 or v_roll >= 1 then
    raise exception 'p_roll must be >= 0 and < 1';
  end if;

  select coalesce(sum(greatest(base_weight, 0)), 0)
    into v_total
  from public.season_weather_rules
  where season_id = p_season_id;

  if v_total <= 0 then
    raise exception 'No positive weather weights configured for season %', p_season_id;
  end if;

  return query
  with ordered as (
    select
      swr.weather_id,
      wd.weather_key,
      wd.display_name,
      wd.intensity,
      swr.base_weight,
      sum(swr.base_weight) over (
        order by swr.base_weight desc, wd.weather_key
        rows between unbounded preceding and current row
      ) as cumulative_weight
    from public.season_weather_rules swr
    join public.weather_definitions wd on wd.id = swr.weather_id
    where swr.season_id = p_season_id
      and greatest(swr.base_weight, 0) > 0
  )
  select
    o.weather_id,
    o.weather_key,
    o.display_name,
    o.intensity,
    o.base_weight
  from ordered o
  where o.cumulative_weight / v_total > v_roll
  order by o.cumulative_weight
  limit 1;
end;
$function$;


CREATE OR REPLACE FUNCTION public.start_world_weather_state_v1(p_world_id uuid, p_season_id uuid, p_weather_id uuid, p_intensity smallint DEFAULT NULL::smallint, p_duration_minutes integer DEFAULT 60, p_seed bigint DEFAULT NULL::bigint, p_conditions jsonb DEFAULT '{}'::jsonb)
 RETURNS world_weather_states
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_state public.world_weather_states;
  v_intensity smallint;
begin
  if p_world_id is null or p_season_id is null or p_weather_id is null then
    raise exception 'world_id, season_id and weather_id are required';
  end if;
  if p_duration_minutes is null or p_duration_minutes <= 0 then
    raise exception 'p_duration_minutes must be greater than 0';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_world_id::text, 0));

  select coalesce(p_intensity, wd.intensity)::smallint
    into v_intensity
  from public.weather_definitions wd
  where wd.id = p_weather_id;

  if v_intensity is null then
    raise exception 'weather_id % not found', p_weather_id;
  end if;

  if v_intensity < 0 then v_intensity := 0; end if;
  if v_intensity > 5 then v_intensity := 5; end if;

  update public.world_weather_states
     set ends_at = now(),
         updated_at = now()
   where world_id = p_world_id
     and ends_at is null;

  insert into public.world_weather_states (
    world_id, weather_id, season_id, started_at, ends_at,
    intensity, seed, conditions, updated_at
  )
  values (
    p_world_id, p_weather_id, p_season_id, now(),
    now() + make_interval(mins => p_duration_minutes),
    v_intensity, p_seed, coalesce(p_conditions, '{}'::jsonb), now()
  )
  returning * into v_state;

  return v_state;
end;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_effective_map_weather_v1(p_map_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(map_id uuid, source_type text, source_id uuid, weather_id uuid, weather_key text, display_name text, intensity smallint, conditions jsonb, priority smallint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with map_info as (
    select id, world_id
    from public.maps
    where id = p_map_id
  ),
  override_choice as (
    select
      o.map_id,
      o.id as source_id,
      o.weather_id,
      o.intensity,
      o.conditions,
      o.priority
    from public.map_weather_overrides o
    join map_info m on m.id = o.map_id
    where o.enabled
      and (o.valid_from is null or o.valid_from <= p_at)
      and (o.valid_until is null or o.valid_until >= p_at)
      and o.weather_id is not null
    order by o.priority desc, o.updated_at desc, o.id desc
    limit 1
  ),
  world_choice as (
    select
      wws.id as source_id,
      wws.weather_id,
      wws.intensity,
      wws.conditions
    from public.world_weather_states wws
    join map_info m on m.world_id = wws.world_id
    where wws.started_at <= p_at
      and (wws.ends_at is null or wws.ends_at > p_at)
    order by wws.started_at desc, wws.updated_at desc, wws.id desc
    limit 1
  )
  select
    p_map_id,
    case when oc.source_id is not null then 'map_override' else 'world_state' end,
    coalesce(oc.source_id, wc.source_id),
    coalesce(oc.weather_id, wc.weather_id),
    wd.weather_key,
    wd.display_name,
    coalesce(oc.intensity, wc.intensity, wd.intensity),
    coalesce(oc.conditions, wc.conditions, '{}'::jsonb),
    coalesce(oc.priority, 0)::smallint
  from map_info mi
  left join override_choice oc on true
  left join world_choice wc on oc.source_id is null
  left join public.weather_definitions wd
    on wd.id = coalesce(oc.weather_id, wc.weather_id);
$function$;


CREATE OR REPLACE FUNCTION public.resolve_effective_map_weather_v2(p_map_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(map_id uuid, source_type text, source_id uuid, weather_id uuid, weather_key text, display_name text, intensity smallint, conditions jsonb, precipitation_allowed boolean, temperature_passthrough boolean, visibility_passthrough boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with map_info as (
    select id, world_id
    from public.maps
    where id = p_map_id
  ),
  policy as (
    select
      coalesce(mep.receives_world_weather, true) as receives_world_weather,
      coalesce(mep.precipitation_allowed, true) as precipitation_allowed,
      coalesce(mep.temperature_passthrough, true) as temperature_passthrough,
      coalesce(mep.visibility_passthrough, true) as visibility_passthrough
    from map_info mi
    left join public.map_environment_policies mep on mep.map_id = mi.id
  ),
  override_choice as (
    select o.id source_id,o.weather_id,o.intensity,o.conditions,o.priority
    from public.map_weather_overrides o
    where o.map_id=p_map_id
      and o.enabled
      and (o.valid_from is null or o.valid_from <= p_at)
      and (o.valid_until is null or o.valid_until >= p_at)
      and o.weather_id is not null
    order by o.priority desc,o.updated_at desc,o.id desc
    limit 1
  ),
  world_choice as (
    select w.id source_id,w.weather_id,w.intensity,w.conditions
    from public.world_weather_states w
    join map_info mi on mi.world_id=w.world_id
    where w.started_at <= p_at
      and (w.ends_at is null or w.ends_at > p_at)
    order by w.started_at desc,w.updated_at desc,w.id desc
    limit 1
  )
  select
    p_map_id,
    case when oc.source_id is not null then 'map_override'
         when wc.source_id is not null then 'world_state'
         else 'none' end,
    coalesce(oc.source_id,wc.source_id),
    coalesce(oc.weather_id,wc.weather_id),
    wd.weather_key,
    wd.display_name,
    case when oc.source_id is not null and not p.precipitation_allowed
         then 0
         else coalesce(oc.intensity,wc.intensity,wd.intensity) end,
    case when oc.source_id is not null then oc.conditions
         when wc.source_id is not null then wc.conditions
         else '{}'::jsonb end,
    p.precipitation_allowed,
    p.temperature_passthrough,
    p.visibility_passthrough
  from map_info mi
  cross join policy p
  left join override_choice oc on true
  left join world_choice wc on oc.source_id is null and p.receives_world_weather
  left join public.weather_definitions wd
    on wd.id=coalesce(oc.weather_id,wc.weather_id);
$function$;


CREATE OR REPLACE FUNCTION public.resolve_region_weather_weights_v1(p_season_id uuid, p_region_id uuid)
 RETURNS TABLE(weather_id uuid, weather_key text, display_name text, base_weight numeric, climate_modifier numeric, effective_weight numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 with profile as (
   select climate_key, weather_modifiers
   from public.region_weather_profiles
   where region_id=p_region_id
 ),
 rules as (
   select swr.weather_id,wd.weather_key,wd.display_name,swr.base_weight
   from public.season_weather_rules swr
   join public.weather_definitions wd on wd.id=swr.weather_id
   where swr.season_id=p_season_id
 ),
 weighted as (
   select
     r.weather_id,r.weather_key,r.display_name,r.base_weight,
     coalesce((p.weather_modifiers ->> r.weather_key)::numeric,1) as climate_modifier
   from rules r
   left join profile p on true
 )
 select
   w.weather_id,w.weather_key,w.display_name,w.base_weight,w.climate_modifier,
   greatest(0,w.base_weight*w.climate_modifier) as effective_weight
 from weighted w
 order by greatest(0,w.base_weight*w.climate_modifier) desc,w.weather_key;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weather_pipeline_v1(p_season_id uuid, p_region_id uuid, p_roll numeric DEFAULT 0.5)
 RETURNS TABLE(weather_id uuid, weather_key text, display_name text, base_weight numeric, climate_modifier numeric, effective_weight numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with weights as (
    select *
    from public.resolve_region_weather_weights_v1(p_season_id,p_region_id)
  ),
  weighted as (
    select
      w.*,
      sum(w.effective_weight) over (
        order by w.effective_weight desc,w.weather_key
        rows between unbounded preceding and current row
      ) as cumulative_weight,
      sum(w.effective_weight) over () as total_weight
    from weights w
  )
  select weather_id,weather_key,display_name,base_weight,climate_modifier,effective_weight
  from weighted
  where total_weight > 0
    and cumulative_weight / total_weight > p_roll
  order by cumulative_weight
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weather_environment_effects_v1(p_weather_id uuid, p_intensity smallint DEFAULT NULL::smallint, p_precipitation_allowed boolean DEFAULT true, p_temperature_passthrough boolean DEFAULT true, p_visibility_passthrough boolean DEFAULT true)
 RETURNS TABLE(weather_id uuid, weather_key text, temperature_modifier numeric, visibility_modifier numeric, movement_modifier numeric, precipitation_type text, gameplay_tags jsonb, visual_effects jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    wd.id,
    wd.weather_key,
    case when p_temperature_passthrough then wd.temperature_modifier * greatest(0,coalesce(p_intensity,wd.intensity)) / greatest(1,wd.intensity)
         else 0 end,
    case when p_visibility_passthrough then wd.visibility_modifier * greatest(0,coalesce(p_intensity,wd.intensity)) / greatest(1,wd.intensity)
         else 0 end,
    wd.movement_modifier * greatest(0,coalesce(p_intensity,wd.intensity)) / greatest(1,wd.intensity),
    case when p_precipitation_allowed then wd.precipitation_type else 'none' end,
    wd.gameplay_tags,
    wd.visual_effects
  from public.weather_definitions wd
  where wd.id=p_weather_id;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_effective_map_weather_v3(p_map_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(map_id uuid, source_type text, source_id uuid, weather_id uuid, weather_key text, display_name text, intensity smallint, temperature_modifier numeric, visibility_modifier numeric, movement_modifier numeric, precipitation_type text, gameplay_tags jsonb, visual_effects jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with base as (
    select * from public.resolve_effective_map_weather_v2(p_map_id,p_at)
  )
  select
    b.map_id,b.source_type,b.source_id,b.weather_id,b.weather_key,b.display_name,
    b.intensity,
    e.temperature_modifier,e.visibility_modifier,e.movement_modifier,
    e.precipitation_type,e.gameplay_tags,e.visual_effects
  from base b
  left join lateral public.resolve_weather_environment_effects_v1(
    b.weather_id,b.intensity,b.precipitation_allowed,
    b.temperature_passthrough,b.visibility_passthrough
  ) e on true;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_seasonal_environment_effects_v1(p_season_id uuid, p_weather_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(season_id uuid, season_key text, vegetation_state text, snow_state text, precipitation_bias text, weather_key text, snow_cover boolean, wet_ground boolean, seasonal_tags jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with season as (
    select sd.id,sd.season_key,
           sr.rule_value as environment_rule
    from public.season_definitions sd
    left join public.season_rules sr
      on sr.season_id=sd.id and sr.rule_key='environment'
    where sd.id=p_season_id
  ),
  weather as (
    select wd.weather_key,wd.precipitation_type,wd.gameplay_tags
    from public.weather_definitions wd
    where wd.id=p_weather_id
  )
  select
    s.id,
    s.season_key,
    coalesce(s.environment_rule->>'vegetation','unknown'),
    coalesce(s.environment_rule->>'snow','unknown'),
    coalesce(s.environment_rule->>'precipitation_bias','unknown'),
    w.weather_key,
    case
      when coalesce(s.environment_rule->>'snow','') in ('possible','melt')
           and coalesce(w.precipitation_type,'')='snow' then true
      when w.gameplay_tags ? 'snow_cover' then true
      else false
    end,
    case
      when w.gameplay_tags ? 'wet_ground' then true
      else false
    end,
    jsonb_build_object(
      'season_environment',coalesce(s.environment_rule,'{}'::jsonb),
      'weather_tags',coalesce(w.gameplay_tags,'[]'::jsonb)
    )
  from season s
  left join weather w on true;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_seasonal_asset_variant_v1(p_asset_license_id uuid, p_season_id uuid)
 RETURNS TABLE(variant_id uuid, variant_external_key text, verified boolean, metadata jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    av.id,
    av.variant_external_key,
    av.verified,
    av.metadata
  from public.asset_seasonal_variants av
  join public.asset_license_registry al
    on al.id = av.asset_license_id
  where av.asset_license_id = p_asset_license_id
    and av.season_id = p_season_id
    and av.verified = true
    and al.verification_status = 'verified'
  order by av.id
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_terrain_seasonal_state_v1(p_terrain_type_id uuid, p_season_id uuid)
 RETURNS TABLE(terrain_type_id uuid, terrain_key text, season_id uuid, season_key text, season_capable boolean, seasonal_variant_id uuid, variant_external_key text, variant_verified boolean, state text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    tt.id,
    tt.terrain_key,
    sd.id,
    sd.season_key,
    tt.season_capable,
    av.id,
    av.variant_external_key,
    av.verified,
    case
      when not tt.enabled then 'disabled'
      when not tt.season_capable then 'base'
      when av.id is not null then 'seasonal_variant'
      else 'base_fallback'
    end
  from public.terrain_types tt
  join public.season_definitions sd on sd.id=p_season_id
  left join lateral (
    select av.id,av.variant_external_key,av.verified
    from public.asset_seasonal_variants av
    where av.season_id=sd.id
      and av.verified=true
      and (
        av.asset_license_id in (
          select av2.asset_license_id
          from public.asset_seasonal_variants av2
          where av2.verified=true
        )
      )
    order by av.id
    limit 1
  ) av on tt.season_capable
  where tt.id=p_terrain_type_id;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_terrain_seasonal_state_v2(p_terrain_type_id uuid, p_season_id uuid)
 RETURNS TABLE(terrain_type_id uuid, terrain_key text, season_id uuid, season_key text, season_capable boolean, seasonal_variant_id uuid, variant_external_key text, variant_verified boolean, state text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    tt.id,tt.terrain_key,sd.id,sd.season_key,tt.season_capable,
    b.seasonal_variant_id,av.variant_external_key,av.verified,
    case
      when not tt.enabled then 'disabled'
      when not tt.season_capable then 'base'
      when b.id is not null and av.verified then 'seasonal_variant'
      else 'base_fallback'
    end
  from public.terrain_types tt
  join public.season_definitions sd on sd.id=p_season_id
  left join public.terrain_seasonal_bindings b
    on b.terrain_type_id=tt.id
   and b.season_id=sd.id
   and b.enabled=true
  left join public.asset_seasonal_variants av
    on av.id=b.seasonal_variant_id
  where tt.id=p_terrain_type_id;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_map_environment_snapshot_v1(p_map_id uuid, p_season_id uuid, p_terrain_type_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(map_id uuid, season_id uuid, season_key text, weather_source text, weather_id uuid, weather_key text, weather_intensity smallint, temperature_modifier numeric, visibility_modifier numeric, movement_modifier numeric, precipitation_type text, snow_cover boolean, wet_ground boolean, vegetation_state text, snow_state text, precipitation_bias text, terrain_state text, seasonal_variant_id uuid, seasonal_variant_key text, environment_policy jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with w as (
    select * from public.resolve_effective_map_weather_v3(p_map_id,p_at)
  ),
  s as (
    select *
    from w
    cross join lateral public.resolve_seasonal_environment_effects_v1(p_season_id,w.weather_id)
  ),
  t as (
    select * from public.resolve_terrain_seasonal_state_v2(p_terrain_type_id,p_season_id)
    where p_terrain_type_id is not null
  ),
  p as (
    select jsonb_build_object(
      'receives_world_weather',mep.receives_world_weather,
      'precipitation_allowed',mep.precipitation_allowed,
      'temperature_passthrough',mep.temperature_passthrough,
      'visibility_passthrough',mep.visibility_passthrough
    ) as policy
    from public.map_environment_policies mep
    where mep.map_id=p_map_id
  )
  select
    p_map_id,p_season_id,s.season_key,w.source_type,w.weather_id,w.weather_key,w.intensity,
    w.temperature_modifier,w.visibility_modifier,w.movement_modifier,w.precipitation_type,
    coalesce(s.snow_cover,false),coalesce(s.wet_ground,false),
    s.vegetation_state,s.snow_state,s.precipitation_bias,
    coalesce(t.state,'base'),t.seasonal_variant_id,t.variant_external_key,
    coalesce(p.policy,'{}'::jsonb)
  from s
  left join w on true
  left join t on true
  left join p on true;
$function$;


CREATE OR REPLACE FUNCTION public.get_world_environment_state_v1(p_world_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(world_id uuid, season_id uuid, weather_state_id uuid, weather_id uuid, intensity smallint, state_started_at timestamp with time zone, state_ends_at timestamp with time zone, conditions jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    wes.world_id,
    wes.season_id,
    wes.weather_state_id,
    wws.weather_id,
    wws.intensity,
    coalesce(wws.started_at,wes.state_started_at),
    coalesce(wws.ends_at,wes.state_ends_at),
    wes.conditions || coalesce(wws.conditions,'{}'::jsonb)
  from public.world_environment_states wes
  left join public.world_weather_states wws
    on wws.id=wes.weather_state_id
  where wes.world_id=p_world_id
    and (wws.id is null or (wws.started_at <= p_at and (wws.ends_at is null or wws.ends_at > p_at)));
$function$;


CREATE OR REPLACE FUNCTION public.advance_world_environment_clock_v1(p_world_id uuid, p_to timestamp with time zone)
 RETURNS TABLE(world_id uuid, simulation_at timestamp with time zone, season_id uuid, season_key text, season_started_at timestamp with time zone, season_ends_at timestamp with time zone, transitioned boolean)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_clock public.world_environment_clocks%rowtype;
  v_season_id uuid;
begin
  select * into v_clock
  from public.world_environment_clocks
  where world_id=p_world_id
  for update;

  if not found then
    raise exception 'environment clock not initialized for world %',p_world_id;
  end if;

  if p_to < v_clock.simulation_at then
    raise exception 'simulation time cannot move backwards';
  end if;

  update public.world_environment_clocks
  set simulation_at=p_to, updated_at=now()
  where world_id=p_world_id;

  if v_clock.season_ends_at is not null and p_to >= v_clock.season_ends_at then
    select sd.id into v_season_id
    from public.season_definitions sd
    where sd.id <> v_clock.current_season_id
    order by case sd.season_key
      when 'spring' then 1 when 'summer' then 2 when 'autumn' then 3 when 'winter' then 4 else 99 end
    limit 1;

    -- Do not invent a transition schedule. A season transition requires
    -- an explicitly configured next season in metadata.
    v_season_id := null;
  end if;

  return query
  select c.world_id,c.simulation_at,c.current_season_id,sd.season_key,
         c.season_started_at,c.season_ends_at,
         false
  from public.world_environment_clocks c
  left join public.season_definitions sd on sd.id=c.current_season_id
  where c.world_id=p_world_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.validate_season_cycle_configuration_v1()
 RETURNS TABLE(season_id uuid, season_key text, next_season_id uuid, next_season_key text, duration_days numeric, enabled boolean, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select
    sd.id,sd.season_key,scr.next_season_id,ns.season_key,
    scr.duration_days,scr.enabled,
    case
      when scr.id is null then 'missing'
      when not scr.enabled then 'disabled'
      when scr.next_season_id is null then 'missing_next_season'
      when scr.duration_days is null then 'missing_duration'
      else 'configured'
    end
  from public.season_definitions sd
  left join public.season_cycle_rules scr on scr.season_id=sd.id
  left join public.season_definitions ns on ns.id=scr.next_season_id
  order by sd.season_key;
$function$;


CREATE OR REPLACE FUNCTION public.validate_weather_transition_policies_v1()
 RETURNS TABLE(weather_id uuid, weather_key text, min_duration_minutes integer, max_duration_minutes integer, enabled boolean, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select wd.id,wd.weather_key,wp.min_duration_minutes,wp.max_duration_minutes,wp.enabled,
    case
      when wp.id is null then 'missing'
      when not wp.enabled then 'disabled'
      when wp.min_duration_minutes is null then 'missing_min_duration'
      when wp.max_duration_minutes is null then 'missing_max_duration'
      else 'configured'
    end
  from public.weather_definitions wd
  left join public.weather_transition_policies wp on wp.weather_id=wd.id
  order by wd.weather_key;
$function$;


CREATE OR REPLACE FUNCTION public.environment_tick_v1(p_world_id uuid, p_to timestamp with time zone)
 RETURNS TABLE(world_id uuid, simulation_at timestamp with time zone, season_id uuid, weather_state_id uuid, action text, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_clock public.world_environment_clocks%rowtype;
  v_state public.world_environment_states%rowtype;
begin
  select * into v_clock
  from public.world_environment_clocks
  where world_id=p_world_id
  for update;

  if not found then
    raise exception 'environment clock not initialized for world %',p_world_id;
  end if;

  if p_to < v_clock.simulation_at then
    raise exception 'simulation time cannot move backwards';
  end if;

  update public.world_environment_clocks
  set simulation_at=p_to, updated_at=now()
  where world_id=p_world_id;

  select * into v_state
  from public.world_environment_states
  where world_id=p_world_id;

  if not found then
    return query
      select p_world_id,p_to,v_clock.current_season_id,null::uuid,
             'initialize_environment','environment state missing';
    return;
  end if;

  if v_state.state_ends_at is not null and p_to >= v_state.state_ends_at then
    return query
      select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,
             'resolve_weather','environment state expired';
    return;
  end if;

  if v_clock.season_ends_at is not null and p_to >= v_clock.season_ends_at then
    return query
      select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,
             'resolve_season','season state expired';
    return;
  end if;

  return query
    select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,
           'none','environment state still valid';
end;
$function$;


CREATE OR REPLACE FUNCTION public.execute_weather_transition_v1(p_world_id uuid, p_season_id uuid, p_started_at timestamp with time zone, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, weather_state_id uuid, weather_id uuid, season_id uuid, started_at timestamp with time zone, ends_at timestamp with time zone, intensity smallint, seed bigint, action text, status text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_weather_id uuid;
  v_weather_key text;
  v_min integer;
  v_max integer;
  v_duration integer;
  v_seed bigint;
  v_state_id uuid;
begin
  select swr.weather_id, wd.weather_key
    into v_weather_id, v_weather_key
  from public.season_weather_rules swr
  join public.weather_definitions wd on wd.id=swr.weather_id
  where swr.season_id=p_season_id
  order by swr.base_weight desc, wd.weather_key
  limit 1;

  if v_weather_id is null then
    return query select p_world_id,null::uuid,null::uuid,p_season_id,p_started_at,null::timestamptz,
      null::smallint,p_seed,'resolve_weather','no_rule';
    return;
  end if;

  select min_duration_minutes,max_duration_minutes
    into v_min,v_max
  from public.weather_transition_policies
  where weather_id=v_weather_id and enabled=true;

  if v_min is null or v_max is null then
    return query select p_world_id,null::uuid,v_weather_id,p_season_id,p_started_at,null::timestamptz,
      null::smallint,p_seed,'resolve_weather','policy_missing';
    return;
  end if;

  v_seed := coalesce(p_seed, floor(extract(epoch from p_started_at))::bigint);
  v_duration := v_min + mod(abs(v_seed), v_max-v_min+1);

  insert into public.world_weather_states(world_id,weather_id,season_id,started_at,ends_at,intensity,seed,conditions)
  values(p_world_id,v_weather_id,p_season_id,p_started_at,p_started_at + make_interval(mins => v_duration),0,v_seed,'{}'::jsonb)
  returning id into v_state_id;

  return query
    select p_world_id,v_state_id,v_weather_id,p_season_id,p_started_at,
      p_started_at + make_interval(mins => v_duration),0::smallint,v_seed,
      'create_weather_state','created';
end;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weighted_weather_v1(p_season_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT 0)
 RETURNS TABLE(weather_id uuid, weather_key text, base_weight numeric, climate_modifier numeric, region_modifier numeric, effective_weight numeric, roll numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with candidates as (
    select
      swr.weather_id,
      wd.weather_key,
      swr.base_weight,
      coalesce(
        (rwp.weather_modifiers ->> wd.weather_key)::numeric,
        1
      ) as climate_modifier,
      coalesce(
        (swr.region_modifiers ->> coalesce(rwp.climate_key,''))::numeric,
        1
      ) as region_modifier
    from public.season_weather_rules swr
    join public.weather_definitions wd on wd.id=swr.weather_id
    left join public.region_weather_profiles rwp on rwp.region_id=p_region_id
    where swr.season_id=p_season_id
      and swr.base_weight > 0
  ),
  weighted as (
    select *,
      base_weight * climate_modifier * region_modifier as effective_weight,
      sum(base_weight * climate_modifier * region_modifier)
        over () as total_weight
    from candidates
  ),
  rolled as (
    select *,
      case
        when total_weight > 0
        then (mod(abs(p_seed),1000000)::numeric / 1000000) * total_weight
        else 0
      end as roll_value
    from weighted
  )
  select weather_id,weather_key,base_weight,climate_modifier,region_modifier,
         effective_weight,roll_value
  from rolled
  where effective_weight > 0
  order by
    sum(effective_weight) over (
      order by weather_id
      rows between unbounded preceding and current row
    ) > roll_value,
    weather_key
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weighted_weather_v2(p_season_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_current_weather_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT 0)
 RETURNS TABLE(weather_id uuid, weather_key text, base_weight numeric, climate_modifier numeric, region_modifier numeric, transition_modifier numeric, effective_weight numeric, roll numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with candidates as (
    select
      swr.weather_id,
      wd.weather_key,
      swr.base_weight,
      coalesce((rwp.weather_modifiers ->> wd.weather_key)::numeric,1) as climate_modifier,
      coalesce((swr.region_modifiers ->> coalesce(rwp.climate_key,''))::numeric,1) as region_modifier,
      case
        when p_current_weather_id is null then 1::numeric
        when swr.weather_id = p_current_weather_id then
          coalesce((wtp.transition_tags ->> 'self_transition_modifier')::numeric,0)
        else
          coalesce((wtp.transition_tags ->> 'transition_modifier')::numeric,1)
      end as transition_modifier
    from public.season_weather_rules swr
    join public.weather_definitions wd on wd.id=swr.weather_id
    left join public.region_weather_profiles rwp on rwp.region_id=p_region_id
    left join public.weather_transition_policies wtp on wtp.weather_id=swr.weather_id
    where swr.season_id=p_season_id
      and swr.base_weight > 0
  ),
  weighted as (
    select *,
      base_weight * climate_modifier * region_modifier * transition_modifier as effective_weight,
      sum(base_weight * climate_modifier * region_modifier * transition_modifier) over () as total_weight
    from candidates
  ),
  rolled as (
    select *,
      case when total_weight > 0
        then (mod(abs(p_seed),1000000)::numeric / 1000000) * total_weight
        else 0 end as roll_value
    from weighted
  ),
  selected as (
    select *,
      sum(effective_weight) over (order by weather_key rows between unbounded preceding and current row) as cumulative_weight
    from rolled
    where effective_weight > 0
  )
  select weather_id,weather_key,base_weight,climate_modifier,region_modifier,
         transition_modifier,effective_weight,roll_value
  from selected
  where cumulative_weight > roll_value
  order by weather_key
  limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.execute_weather_transition_v2(p_world_id uuid, p_season_id uuid, p_started_at timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, weather_state_id uuid, weather_id uuid, season_id uuid, started_at timestamp with time zone, ends_at timestamp with time zone, intensity smallint, seed bigint, action text, status text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_current_weather_id uuid;
  v_weather_id uuid;
  v_min integer;
  v_max integer;
  v_duration integer;
  v_seed bigint;
  v_state_id uuid;
  v_ends_at timestamptz;
begin
  select wes.weather_state_id, wws.weather_id
    into v_current_weather_id, v_current_weather_id
  from public.world_environment_states wes
  left join public.world_weather_states wws on wws.id=wes.weather_state_id
  where wes.world_id=p_world_id;

  v_seed := coalesce(p_seed, floor(extract(epoch from p_started_at))::bigint);

  select x.weather_id
    into v_weather_id
  from public.resolve_weighted_weather_v2(
    p_season_id,p_region_id,v_current_weather_id,v_seed
  ) x
  limit 1;

  if v_weather_id is null then
    return query select p_world_id,null::uuid,null::uuid,p_season_id,p_started_at,null::timestamptz,
      null::smallint,v_seed,'resolve_weather','no_candidate';
    return;
  end if;

  select min_duration_minutes,max_duration_minutes
    into v_min,v_max
  from public.weather_transition_policies
  where weather_id=v_weather_id and enabled=true;

  if v_min is null or v_max is null then
    return query select p_world_id,null::uuid,v_weather_id,p_season_id,p_started_at,null::timestamptz,
      null::smallint,v_seed,'resolve_weather','policy_missing';
    return;
  end if;

  v_duration := v_min + mod(abs(v_seed),v_max-v_min+1);
  v_ends_at := p_started_at + make_interval(mins => v_duration);

  insert into public.world_weather_states(
    world_id,weather_id,season_id,started_at,ends_at,intensity,seed,conditions
  )
  values(p_world_id,v_weather_id,p_season_id,p_started_at,v_ends_at,0,v_seed,'{}'::jsonb)
  returning id into v_state_id;

  insert into public.world_environment_states(
    world_id,season_id,weather_state_id,state_started_at,state_ends_at,conditions,updated_at
  )
  values(p_world_id,p_season_id,v_state_id,p_started_at,v_ends_at,'{}'::jsonb,now())
  on conflict(world_id) do update set
    season_id=excluded.season_id,
    weather_state_id=excluded.weather_state_id,
    state_started_at=excluded.state_started_at,
    state_ends_at=excluded.state_ends_at,
    updated_at=now();

  return query
    select p_world_id,v_state_id,v_weather_id,p_season_id,p_started_at,v_ends_at,
      0::smallint,v_seed,'create_weather_state','created';
end;
$function$;


CREATE OR REPLACE FUNCTION public.environment_tick_v2(p_world_id uuid, p_to timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, simulation_at timestamp with time zone, season_id uuid, weather_state_id uuid, action text, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_clock public.world_environment_clocks%rowtype;
  v_state public.world_environment_states%rowtype;
  v_weather_result record;
  v_seed bigint;
begin
  select * into v_clock from public.world_environment_clocks
  where world_id=p_world_id for update;

  if not found then
    raise exception 'environment clock not initialized for world %',p_world_id;
  end if;
  if p_to < v_clock.simulation_at then
    raise exception 'simulation time cannot move backwards';
  end if;

  update public.world_environment_clocks
  set simulation_at=p_to, updated_at=now()
  where world_id=p_world_id;

  select * into v_state from public.world_environment_states
  where world_id=p_world_id;

  if not found then
    return query select p_world_id,p_to,v_clock.current_season_id,null::uuid,
      'initialize_environment','environment state missing';
    return;
  end if;

  if v_clock.season_ends_at is not null and p_to >= v_clock.season_ends_at then
    return query select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,
      'resolve_season','season state expired';
    return;
  end if;

  if v_state.state_ends_at is not null and p_to >= v_state.state_ends_at then
    v_seed := coalesce(p_seed,floor(extract(epoch from p_to))::bigint);
    select * into v_weather_result
    from public.execute_weather_transition_v2(
      p_world_id,v_clock.current_season_id,p_to,p_region_id,v_seed
    ) limit 1;

    return query select p_world_id,p_to,v_clock.current_season_id,
      v_weather_result.weather_state_id,
      case when v_weather_result.status='created' then 'weather_transition' else 'resolve_weather' end,
      v_weather_result.status;
    return;
  end if;

  return query select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,
    'none','environment state still valid';
end;
$function$;


CREATE OR REPLACE FUNCTION public.initialize_world_environment_v1(p_world_id uuid, p_season_id uuid, p_at timestamp with time zone DEFAULT now(), p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, season_id uuid, weather_state_id uuid, simulation_at timestamp with time zone, status text, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_seed bigint := coalesce(p_seed,floor(extract(epoch from p_at))::bigint);
  v_clock_exists boolean;
  v_weather_result record;
begin
  if not exists (select 1 from public.worlds where id=p_world_id) then
    raise exception 'world % does not exist',p_world_id;
  end if;

  if not exists (select 1 from public.season_definitions where id=p_season_id) then
    raise exception 'season % does not exist',p_season_id;
  end if;

  if not exists (
    select 1 from public.season_cycle_rules
    where season_id=p_season_id and enabled=true
      and next_season_id is not null and duration_days is not null
  ) then
    return query select p_world_id,p_season_id,null::uuid,p_at,
      'blocked','season_cycle_not_configured';
    return;
  end if;

  if not exists (
    select 1 from public.season_weather_rules
    where season_id=p_season_id and base_weight > 0
  ) then
    return query select p_world_id,p_season_id,null::uuid,p_at,
      'blocked','season_weather_rules_missing';
    return;
  end if;

  if not exists (
    select 1
    from public.season_weather_rules swr
    join public.weather_transition_policies wtp on wtp.weather_id=swr.weather_id
    where swr.season_id=p_season_id
      and swr.base_weight > 0
      and wtp.enabled=true
      and wtp.min_duration_minutes is not null
      and wtp.max_duration_minutes is not null
  ) then
    return query select p_world_id,p_season_id,null::uuid,p_at,
      'blocked','weather_transition_policy_missing';
    return;
  end if;

  insert into public.world_environment_clocks(
    world_id,simulation_at,speed_multiplier,current_season_id,
    season_started_at,season_ends_at,updated_at
  )
  select
    p_world_id,p_at,1,p_season_id,p_at,
    p_at + make_interval(days => scr.duration_days),
    now()
  from public.season_cycle_rules scr
  where scr.season_id=p_season_id and scr.enabled=true
  on conflict(world_id) do update set
    simulation_at=excluded.simulation_at,
    current_season_id=excluded.current_season_id,
    season_started_at=excluded.season_started_at,
    season_ends_at=excluded.season_ends_at,
    updated_at=now();

  select * into v_weather_result
  from public.execute_weather_transition_v2(
    p_world_id,p_season_id,p_at,p_region_id,v_seed
  ) limit 1;

  if v_weather_result.status <> 'created' then
    return query select p_world_id,p_season_id,null::uuid,p_at,
      'blocked',coalesce(v_weather_result.status,'weather_initialization_failed');
    return;
  end if;

  return query select p_world_id,p_season_id,v_weather_result.weather_state_id,
    p_at,'initialized','world_environment_ready';
end;
$function$;


CREATE OR REPLACE FUNCTION public.execute_season_transition_v1(p_world_id uuid, p_to timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, previous_season_id uuid, season_id uuid, season_started_at timestamp with time zone, season_ends_at timestamp with time zone, weather_state_id uuid, action text, status text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_clock public.world_environment_clocks%rowtype;
  v_next_season_id uuid;
  v_duration numeric;
  v_weather record;
  v_seed bigint := coalesce(p_seed,floor(extract(epoch from p_to))::bigint);
begin
  select * into v_clock from public.world_environment_clocks where world_id=p_world_id for update;
  if not found then raise exception 'environment clock not initialized for world %',p_world_id; end if;
  if p_to < v_clock.simulation_at then raise exception 'simulation time cannot move backwards'; end if;
  if v_clock.season_ends_at is null or p_to < v_clock.season_ends_at then
    return query select p_world_id,v_clock.current_season_id,v_clock.current_season_id,
      v_clock.season_started_at,v_clock.season_ends_at,null::uuid,'resolve_season','not_expired';
    return;
  end if;

  select next_season_id,duration_days into v_next_season_id,v_duration
  from public.season_cycle_rules
  where season_id=v_clock.current_season_id and enabled=true;

  if v_next_season_id is null or v_duration is null then
    return query select p_world_id,v_clock.current_season_id,null::uuid,null::timestamptz,null::timestamptz,
      null::uuid,'resolve_season','cycle_not_configured';
    return;
  end if;

  update public.world_environment_clocks
  set simulation_at=p_to,current_season_id=v_next_season_id,
      season_started_at=p_to,season_ends_at=p_to + make_interval(days=>v_duration),updated_at=now()
  where world_id=p_world_id;

  select * into v_weather from public.execute_weather_transition_v2(
    p_world_id,v_next_season_id,p_to,p_region_id,v_seed) limit 1;

  if v_weather.status <> 'created' then
    return query select p_world_id,v_clock.current_season_id,v_next_season_id,p_to,
      p_to + make_interval(days=>v_duration),null::uuid,'season_transition',
      'weather_'||coalesce(v_weather.status,'failed');
    return;
  end if;

  return query select p_world_id,v_clock.current_season_id,v_next_season_id,p_to,
    p_to + make_interval(days=>v_duration),v_weather.weather_state_id,'season_transition','created';
end;
$function$;


CREATE OR REPLACE FUNCTION public.environment_tick_v3(p_world_id uuid, p_to timestamp with time zone, p_region_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT NULL::bigint)
 RETURNS TABLE(world_id uuid, simulation_at timestamp with time zone, season_id uuid, weather_state_id uuid, action text, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_clock public.world_environment_clocks%rowtype;
  v_state public.world_environment_states%rowtype;
  v_result record;
  v_seed bigint := coalesce(p_seed,floor(extract(epoch from p_to))::bigint);
begin
  select * into v_clock from public.world_environment_clocks where world_id=p_world_id for update;
  if not found then raise exception 'environment clock not initialized for world %',p_world_id; end if;
  if p_to < v_clock.simulation_at then raise exception 'simulation time cannot move backwards'; end if;

  select * into v_state from public.world_environment_states where world_id=p_world_id;

  if v_clock.season_ends_at is not null and p_to >= v_clock.season_ends_at then
    select * into v_result from public.execute_season_transition_v1(p_world_id,p_to,p_region_id,v_seed) limit 1;
    return query select p_world_id,p_to,v_result.season_id,v_result.weather_state_id,v_result.action,v_result.status;
    return;
  end if;

  update public.world_environment_clocks set simulation_at=p_to,updated_at=now()
  where world_id=p_world_id;

  if not found then raise exception 'environment clock disappeared for world %',p_world_id; end if;

  if v_state.world_id is null then
    return query select p_world_id,p_to,v_clock.current_season_id,null::uuid,'initialize_environment','environment state missing';
    return;
  end if;

  if v_state.state_ends_at is not null and p_to >= v_state.state_ends_at then
    select * into v_result from public.execute_weather_transition_v2(p_world_id,v_clock.current_season_id,p_to,p_region_id,v_seed) limit 1;
    return query select p_world_id,p_to,v_clock.current_season_id,v_result.weather_state_id,'weather_transition',v_result.status;
    return;
  end if;

  return query select p_world_id,p_to,v_clock.current_season_id,v_state.weather_state_id,'none','environment_state_valid';
end;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weather_policy_v1(p_season_id uuid, p_weather_id uuid)
 RETURNS TABLE(policy_class text, policy_modifier numeric, policy_source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with policy as (
    select rule_value
    from public.season_rules
    where season_id=p_season_id and rule_key='weather_policy'
    limit 1
  ),
  wd as (
    select weather_key from public.weather_definitions where id=p_weather_id
  )
  select
    case
      when (policy.rule_value -> 'preferred') ? wd.weather_key then 'preferred'
      when (policy.rule_value -> 'rare') ? wd.weather_key then 'rare'
      else 'normal'
    end,
    case
      when (policy.rule_value -> 'preferred') ? wd.weather_key then 1::numeric
      when (policy.rule_value -> 'rare') ? wd.weather_key then 1::numeric
      else 1::numeric
    end,
    case
      when policy.rule_value is null then 'default'
      else 'season_rules.weather_policy'
    end
  from policy cross join wd;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weighted_weather_v3(p_season_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_current_weather_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT 0)
 RETURNS TABLE(weather_id uuid, weather_key text, base_weight numeric, policy_class text, policy_modifier numeric, climate_modifier numeric, region_modifier numeric, transition_modifier numeric, effective_weight numeric, roll numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with candidates as (
    select swr.weather_id,wd.weather_key,swr.base_weight,
      coalesce((rwp.weather_modifiers ->> wd.weather_key)::numeric,1) climate_modifier,
      1::numeric region_modifier,
      case
        when p_current_weather_id is null then 1::numeric
        when swr.weather_id=p_current_weather_id
          then coalesce((wtp.transition_tags ->> 'self_transition_modifier')::numeric,0)
        else coalesce((wtp.transition_tags ->> 'transition_modifier')::numeric,1)
      end transition_modifier
    from public.season_weather_rules swr
    join public.weather_definitions wd on wd.id=swr.weather_id
    left join public.region_weather_profiles rwp on rwp.region_id=p_region_id
    left join public.weather_transition_policies wtp on wtp.weather_id=swr.weather_id
    where swr.season_id=p_season_id and swr.base_weight>0
  ),
  classified as (
    select c.*,p.policy_class,p.policy_modifier
    from candidates c
    cross join lateral public.resolve_weather_policy_v1(p_season_id,c.weather_id) p
  ),
  weighted as (
    select *,base_weight*policy_modifier*climate_modifier*region_modifier*transition_modifier effective_weight,
      sum(base_weight*policy_modifier*climate_modifier*region_modifier*transition_modifier) over() total_weight
    from classified
  ),
  rolled as (
    select *,case when total_weight>0 then (mod(abs(p_seed),1000000)::numeric/1000000)*total_weight else 0 end roll_value
    from weighted
  ),
  selected as (
    select *,sum(effective_weight) over(order by weather_key rows between unbounded preceding and current row) cumulative_weight
    from rolled where effective_weight>0
  )
  select weather_id,weather_key,base_weight,policy_class,policy_modifier,climate_modifier,
    region_modifier,transition_modifier,effective_weight,roll_value
  from selected
  where cumulative_weight>roll_value
  order by weather_key limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.environment_configuration_audit_v1()
 RETURNS TABLE(domain text, item text, required boolean, configured boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with s as (select count(*)::int n from public.season_definitions),
  sr as (select count(distinct season_id)::int n from public.season_rules),
  sw as (select count(distinct season_id)::int seasons,count(*)::int rows from public.season_weather_rules),
  c as (select count(*)::int rows,count(*) filter(where enabled and next_season_id is not null and duration_days is not null)::int valid from public.season_cycle_rules),
  w as (select count(*)::int n from public.weather_definitions),
  p as (select count(*)::int rows,count(*) filter(where enabled and min_duration_minutes is not null and max_duration_minutes is not null)::int valid from public.weather_transition_policies),
  r as (select count(*)::int n from public.region_weather_profiles),
  o as (select count(*)::int n from public.map_weather_overrides),
  m as (select count(*)::int n from public.map_environment_policies)
  select * from (
    select 'season'::text,'definitions'::text,true,s.n>0,case when s.n>0 then 'ready' else 'missing' end,jsonb_build_object('rows',s.n) from s
    union all select 'season','rules',true,sr.n=s.n and s.n>0,case when sr.n=s.n and s.n>0 then 'ready' else 'incomplete' end,jsonb_build_object('configured_seasons',sr.n,'expected',s.n) from sr,s
    union all select 'weather','definitions',true,w.n>0,case when w.n>0 then 'ready' else 'missing' end,jsonb_build_object('rows',w.n) from w
    union all select 'season_weather','rules',true,sw.seasons=s.n and sw.rows=s.n*w.n and s.n>0 and w.n>0,case when sw.seasons=s.n and sw.rows=s.n*w.n and s.n>0 and w.n>0 then 'ready' else 'incomplete' end,jsonb_build_object('rows',sw.rows,'expected',s.n*w.n) from sw,s,w
    union all select 'season','cycle_configuration',true,c.valid=s.n and s.n>0,case when c.valid=s.n then 'ready' when c.rows=0 then 'not_configured' else 'incomplete' end,jsonb_build_object('rows',c.rows,'enabled_valid',c.valid,'expected',s.n) from c,s
    union all select 'weather','transition_configuration',true,p.valid=w.n and w.n>0,case when p.valid=w.n then 'ready' when p.rows=0 then 'not_configured' else 'incomplete' end,jsonb_build_object('rows',p.rows,'enabled_valid',p.valid,'expected',w.n) from p,w
    union all select 'region','weather_profiles',false,r.n>0,case when r.n>0 then 'configured' else 'optional_not_configured' end,jsonb_build_object('rows',r.n) from r
    union all select 'map','weather_overrides',false,o.n>0,case when o.n>0 then 'configured' else 'optional_not_configured' end,jsonb_build_object('rows',o.n) from o
    union all select 'map','environment_policies',false,m.n>0,case when m.n>0 then 'configured' else 'optional_not_configured' end,jsonb_build_object('rows',m.n) from m
  ) q;
$function$;


CREATE OR REPLACE FUNCTION public.validate_environment_configuration_v1()
 RETURNS TABLE(domain text, item text, valid boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with s as (select id from public.season_definitions),
 c as (
  select scr.*, count(*) over(partition by season_id) n
  from public.season_cycle_rules scr
 ),
 w as (select id from public.weather_definitions),
 p as (
  select wtp.*, count(*) over(partition by weather_id) n
  from public.weather_transition_policies wtp
 )
select * from (
 select 'season'::text,'cycle_contract'::text,
   not exists(select 1 from c where n>1 or duration_days is not null and duration_days<=0 or enabled and (next_season_id is null or duration_days is null) or next_season_id=season_id or next_season_id not in(select id from s)),
   case when not exists(select 1 from c where n>1 or duration_days is not null and duration_days<=0 or enabled and (next_season_id is null or duration_days is null) or next_season_id=season_id or next_season_id not in(select id from s)) then 'valid' else 'invalid' end,
   jsonb_build_object('rows',(select count(*) from c),'enabled',(select count(*) from c where enabled))
 union all
 select 'weather','transition_contract',
   not exists(select 1 from p where n>1 or min_duration_minutes is not null and min_duration_minutes<=0 or max_duration_minutes is not null and max_duration_minutes<=0 or min_duration_minutes is not null and max_duration_minutes is not null and min_duration_minutes>max_duration_minutes or enabled and (min_duration_minutes is null or max_duration_minutes is null)),
   case when not exists(select 1 from p where n>1 or min_duration_minutes is not null and min_duration_minutes<=0 or max_duration_minutes is not null and max_duration_minutes<=0 or min_duration_minutes is not null and max_duration_minutes is not null and min_duration_minutes>max_duration_minutes or enabled and (min_duration_minutes is null or max_duration_minutes is null)) then 'valid' else 'invalid' end,
   jsonb_build_object('rows',(select count(*) from p),'enabled',(select count(*) from p where enabled))
 union all
 select 'season','cycle_coverage',
   (select count(*) from c where enabled and next_season_id is not null and duration_days is not null)=(select count(*) from s),
   case when (select count(*) from c where enabled and next_season_id is not null and duration_days is not null)=(select count(*) from s) then 'ready' else 'not_ready' end,
   jsonb_build_object('expected',(select count(*) from s),'valid_enabled',(select count(*) from c where enabled and next_season_id is not null and duration_days is not null))
 union all
 select 'weather','transition_coverage',
   (select count(*) from p where enabled and min_duration_minutes is not null and max_duration_minutes is not null)=(select count(*) from w),
   case when (select count(*) from p where enabled and min_duration_minutes is not null and max_duration_minutes is not null)=(select count(*) from w) then 'ready' else 'not_ready' end,
   jsonb_build_object('expected',(select count(*) from w),'valid_enabled',(select count(*) from p where enabled and min_duration_minutes is not null and max_duration_minutes is not null))
) q;
$function$;


CREATE OR REPLACE FUNCTION public.validate_region_environment_contract_v1()
 RETURNS TABLE(domain text, item text, valid boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with r as (select * from public.region_weather_profiles),
m as (select * from public.map_environment_policies)
select * from (
 select 'region'::text,'weather_profile_contract'::text,
   not exists(select 1 from r where climate_key='' or precipitation_bias is null or jsonb_typeof(weather_modifiers)<>'object'),
   case when not exists(select 1 from r where climate_key='' or precipitation_bias is null or jsonb_typeof(weather_modifiers)<>'object') then 'valid' else 'invalid' end,
   jsonb_build_object('rows',(select count(*) from r))
 union all
 select 'region','weather_modifier_contract',
   not exists(select 1 from r x cross join lateral jsonb_each(x.weather_modifiers) e where jsonb_typeof(e.value)<>'number' or (e.value)::numeric < 0),
   case when not exists(select 1 from r x cross join lateral jsonb_each(x.weather_modifiers) e where jsonb_typeof(e.value)<>'number' or (e.value)::numeric < 0) then 'valid' else 'invalid' end,
   jsonb_build_object('profiles',(select count(*) from r))
 union all
 select 'map','environment_policy_contract',
   not exists(select 1 from m where map_id is null),
   case when not exists(select 1 from m where map_id is null) then 'valid' else 'invalid' end,
   jsonb_build_object('rows',(select count(*) from m))
) q;
$function$;


CREATE OR REPLACE FUNCTION public.environment_runtime_readiness_gate_v1()
 RETURNS TABLE(status text, ready boolean, blocking_count integer, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with a as (
 select domain,item,required,configured,status,details
 from public.environment_configuration_audit_v1()
),
c as (
 select domain,item,valid,status,details
 from public.validate_environment_configuration_v1()
),
rc as (
 select domain,item,valid,status,details
 from public.validate_region_environment_contract_v1()
),
blocks as (
 select domain,item,status,details from a where required and not configured
 union all
 select domain,item,status,details from c where not valid
 union all
 select domain,item,status,details from rc where not valid
)
select
 case when count(*)=0 then 'READY' else 'BLOCKED' end,
 count(*)=0,
 count(*)::integer,
 coalesce(jsonb_agg(jsonb_build_object('domain',domain,'item',item,'status',status,'details',details) order by domain,item),'[]'::jsonb)
from blocks;
$function$;


CREATE OR REPLACE FUNCTION public.environment_configuration_template_v1()
 RETURNS TABLE(domain text, item text, source_id uuid, next_item_id uuid, required_values text[], current_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 select 'season_cycle'::text, sd.season_key, sd.id, null::uuid,
   array['next_season_id','duration_days']::text[], 'template_only'::text
 from public.season_definitions sd
 union all
 select 'weather_transition'::text, wd.weather_key, wd.id, null::uuid,
   array['min_duration_minutes','max_duration_minutes']::text[], 'template_only'::text
 from public.weather_definitions wd
$function$;


CREATE OR REPLACE FUNCTION public.climate_taxonomy_v1()
 RETURNS TABLE(climate_key text, required_fields text[], modifier_semantics text)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 values
 ('temperate', array['base_temperature','precipitation_bias','weather_modifiers']::text[], 'season-adjusted baseline; numeric weather multipliers'),
 ('tropical', array['base_temperature','precipitation_bias','weather_modifiers']::text[], 'warm/wet baseline; numeric weather multipliers'),
 ('arid', array['base_temperature','precipitation_bias','weather_modifiers']::text[], 'dry baseline; numeric weather multipliers'),
 ('cold', array['base_temperature','precipitation_bias','weather_modifiers']::text[], 'cold baseline; numeric weather multipliers'),
 ('alpine', array['base_temperature','precipitation_bias','weather_modifiers']::text[], 'mountain/cold baseline; numeric weather multipliers');
$function$;


CREATE OR REPLACE FUNCTION public.validate_climate_profile_v1(p_climate_key text, p_base_temperature numeric, p_precipitation_bias numeric, p_weather_modifiers jsonb)
 RETURNS TABLE(valid boolean, status text, details jsonb)
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 select
   p_climate_key in (select climate_key from public.climate_taxonomy_v1())
   and p_weather_modifiers is not null
   and jsonb_typeof(p_weather_modifiers)='object'
   and not exists(select 1 from jsonb_each(p_weather_modifiers) e where jsonb_typeof(e.value)<>'number' or (e.value)::numeric < 0),
   case when p_climate_key not in (select climate_key from public.climate_taxonomy_v1()) then 'unknown_climate'
        when p_weather_modifiers is null or jsonb_typeof(p_weather_modifiers)<>'object' then 'invalid_weather_modifiers'
        when exists(select 1 from jsonb_each(p_weather_modifiers) e where jsonb_typeof(e.value)<>'number' or (e.value)::numeric < 0) then 'invalid_modifier'
        else 'valid' end,
   jsonb_build_object('climate_key',p_climate_key,'base_temperature',p_base_temperature,'precipitation_bias',p_precipitation_bias);
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weather_climate_context_v1(p_season_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_weather_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(climate_key text, base_temperature numeric, precipitation_bias numeric, weather_modifier numeric, source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 select
   rwp.climate_key,
   rwp.base_temperature,
   rwp.precipitation_bias,
   case
     when p_weather_id is null then 1::numeric
     else coalesce((rwp.weather_modifiers ->> wd.weather_key)::numeric,1::numeric)
   end,
   'region_weather_profile'::text
 from public.region_weather_profiles rwp
 left join public.weather_definitions wd on wd.id=p_weather_id
 where p_region_id is not null and rwp.region_id=p_region_id
 union all
 select
   null::text,null::numeric,0::numeric,1::numeric,'season_baseline'::text
 where not exists (
   select 1 from public.region_weather_profiles x
   where p_region_id is not null and x.region_id=p_region_id
 );
$function$;


CREATE OR REPLACE FUNCTION public.resolve_weighted_weather_v4(p_season_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_current_weather_id uuid DEFAULT NULL::uuid, p_seed bigint DEFAULT 0)
 RETURNS TABLE(weather_id uuid, weather_key text, policy_class text, base_weight numeric, climate_modifier numeric, region_modifier numeric, transition_modifier numeric, effective_weight numeric, roll numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
 with candidates as (
   select swr.weather_id,wd.weather_key,swr.base_weight
   from public.season_weather_rules swr
   join public.weather_definitions wd on wd.id=swr.weather_id
   where swr.season_id=p_season_id and swr.base_weight>0
 ),
 enriched as (
   select c.*,pol.policy_class,pol.policy_modifier,
      coalesce(ctx.weather_modifier,1) climate_modifier,
      1::numeric region_modifier,
      case
       when p_current_weather_id is null then 1::numeric
       when c.weather_id=p_current_weather_id then coalesce((wtp.transition_tags->>'self_transition_modifier')::numeric,1)
       else coalesce((wtp.transition_tags->>'transition_modifier')::numeric,1)
      end transition_modifier
   from candidates c
   cross join lateral public.resolve_weather_policy_v1(p_season_id,c.weather_id) pol
   left join lateral public.resolve_weather_climate_context_v1(p_season_id,p_region_id,c.weather_id) ctx on true
   left join public.weather_transition_policies wtp on wtp.weather_id=c.weather_id
 ),
 weighted as (
   select *,base_weight*policy_modifier*climate_modifier*region_modifier*transition_modifier effective_weight,
     sum(base_weight*policy_modifier*climate_modifier*region_modifier*transition_modifier) over() total_weight
   from enriched
 ),
 rolled as (
   select *,case when total_weight>0 then mod(abs(p_seed),1000000)::numeric/1000000*total_weight else 0 end roll_value
   from weighted
 ),
 selected as (
   select *,sum(effective_weight) over(order by weather_key rows between unbounded preceding and current row) cumulative_weight
   from rolled where effective_weight>0
 )
 select weather_id,weather_key,policy_class,base_weight,climate_modifier,region_modifier,transition_modifier,effective_weight,roll_value
 from selected
 where cumulative_weight>roll_value
 order by weather_key
 limit 1;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_map_environment_context_v1(p_map_id uuid, p_weather_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(receives_world_weather boolean, precipitation_allowed boolean, temperature_passthrough boolean, visibility_passthrough boolean, override_weather_id uuid, override_intensity smallint, source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with policy as (
 select * from public.map_environment_policies where map_id=p_map_id limit 1
), ov as (
 select mwo.weather_id,mwo.intensity
 from public.map_weather_overrides mwo
 where mwo.map_id=p_map_id and mwo.enabled
   and (mwo.valid_from is null or mwo.valid_from<=p_at)
   and (mwo.valid_until is null or p_at<=mwo.valid_until)
 order by mwo.priority desc,mwo.updated_at desc
 limit 1
)
select coalesce(policy.receives_world_weather,true),
       coalesce(policy.precipitation_allowed,true),
       coalesce(policy.temperature_passthrough,true),
       coalesce(policy.visibility_passthrough,true),
       ov.weather_id,ov.intensity,
       case when ov.weather_id is not null then 'map_weather_override'
            when policy.map_id is not null then 'map_environment_policy'
            else 'world_weather_default' end
from (select 1) x
left join policy on true
left join ov on true;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_map_weather_v1(p_map_id uuid, p_world_weather_id uuid, p_world_intensity smallint DEFAULT NULL::smallint, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(weather_id uuid, intensity smallint, precipitation_enabled boolean, temperature_enabled boolean, visibility_enabled boolean, source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
select
 case when ctx.override_weather_id is not null then ctx.override_weather_id
      when ctx.receives_world_weather then p_world_weather_id
      else null end,
 case when ctx.override_weather_id is not null then ctx.override_intensity
      when ctx.receives_world_weather then p_world_intensity
      else null end,
 case when ctx.override_weather_id is not null then ctx.precipitation_allowed else ctx.precipitation_allowed end,
 case when ctx.receives_world_weather then ctx.temperature_passthrough else false end,
 case when ctx.receives_world_weather then ctx.visibility_passthrough else false end,
 ctx.source
from public.resolve_map_environment_context_v1(p_map_id,p_world_weather_id,p_at) ctx;
$function$;


CREATE OR REPLACE FUNCTION public.environment_runtime_readiness_gate_v2()
 RETURNS TABLE(status text, ready boolean, blocking_count integer, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with a as (
 select domain,item,required,configured,status,details from public.environment_configuration_audit_v1()
), c as (
 select domain,item,valid,status,details from public.validate_environment_configuration_v1()
), rc as (
 select domain,item,valid,status,details from public.validate_region_environment_contract_v1()
), map_contract as (
 select
   not exists(select 1 from public.map_environment_policies p where p.map_id is null) as valid_policy,
   not exists(select 1 from public.map_weather_overrides o where o.map_id is null) as valid_override,
   not exists(select 1 from public.map_weather_overrides o where o.enabled and o.priority < 0) as valid_priority,
   not exists(select 1 from public.map_weather_overrides o where o.valid_from is not null and o.valid_until is not null and o.valid_from>o.valid_until) as valid_window
), blocks as (
 select domain,item,status,details from a where required and not configured
 union all select domain,item,status,details from c where not valid
 union all select domain,item,status,details from rc where not valid
 union all select 'map','environment_policy_integrity','invalid',jsonb_build_object('reason','null map_id') from map_contract where not valid_policy
 union all select 'map','weather_override_integrity','invalid',jsonb_build_object('reason','null map_id') from map_contract where not valid_override
 union all select 'map','weather_override_priority','invalid',jsonb_build_object('reason','negative priority') from map_contract where not valid_priority
 union all select 'map','weather_override_window','invalid',jsonb_build_object('reason','valid_from after valid_until') from map_contract where not valid_window
)
select case when count(*)=0 then 'READY' else 'BLOCKED' end,
       count(*)=0,count(*)::integer,
       coalesce(jsonb_agg(jsonb_build_object('domain',domain,'item',item,'status',status,'details',details) order by domain,item),'[]'::jsonb)
from blocks;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_environment_runtime_context_v1(p_world_id uuid, p_map_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(ready boolean, season_id uuid, season_key text, weather_state_id uuid, weather_id uuid, weather_key text, weather_intensity smallint, map_weather_id uuid, map_weather_intensity smallint, climate_key text, temperature_modifier numeric, visibility_modifier numeric, movement_modifier numeric, precipitation_type text, gameplay_tags jsonb, visual_effects jsonb, map_source text, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with gate as (select ready from public.environment_runtime_readiness_gate_v2() limit 1),
clock as (select * from public.world_environment_clocks where world_id=p_world_id limit 1),
es as (select * from public.world_environment_states where world_id=p_world_id order by updated_at desc limit 1),
ws as (select * from public.world_weather_states where world_id=p_world_id and started_at<=p_at and (ends_at is null or p_at<=ends_at) order by started_at desc limit 1),
sd as (select s.* from public.season_definitions s cross join clock c left join es e on true left join ws w on true where s.id=coalesce(e.season_id,c.current_season_id,w.season_id) limit 1),
wd as (select * from public.weather_definitions where id=(select weather_id from ws) limit 1),
mw as (select * from public.resolve_map_weather_v1(p_map_id,(select weather_id from ws),(select intensity from ws),p_at) limit 1),
md as (select * from public.weather_definitions where id=(select weather_id from mw) limit 1)
select gate.ready,sd.id,sd.season_key,ws.id,ws.weather_id,wd.weather_key,ws.intensity,mw.weather_id,mw.intensity,
 null::text,coalesce(md.temperature_modifier,wd.temperature_modifier,0),coalesce(md.visibility_modifier,wd.visibility_modifier,0),coalesce(md.movement_modifier,wd.movement_modifier,0),
 coalesce(md.precipitation_type,wd.precipitation_type,'none'),coalesce(md.gameplay_tags,wd.gameplay_tags,'[]'::jsonb),coalesce(md.visual_effects,wd.visual_effects,'{}'::jsonb),mw.source,
 case when not gate.ready then 'runtime_blocked' when p_map_id is not null and mw.weather_id is null then 'map_no_weather' when ws.id is null then 'no_active_world_weather' else 'resolved' end
from gate cross join clock left join es on true left join ws on true left join sd on true left join wd on true left join mw on true left join md on true;
$function$;


CREATE OR REPLACE FUNCTION public.resolve_environment_runtime_context_v2(p_world_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_map_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(ready boolean, season_id uuid, season_key text, weather_state_id uuid, weather_id uuid, weather_key text, weather_intensity smallint, map_weather_id uuid, map_weather_intensity smallint, climate_key text, temperature_modifier numeric, visibility_modifier numeric, movement_modifier numeric, precipitation_type text, gameplay_tags jsonb, visual_effects jsonb, map_source text, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with gate as (select ready from public.environment_runtime_readiness_gate_v2() limit 1),
clock as (select * from public.world_environment_clocks where world_id=p_world_id limit 1),
es as (select * from public.world_environment_states where world_id=p_world_id order by updated_at desc limit 1),
ws as (select * from public.world_weather_states where world_id=p_world_id and started_at<=p_at and (ends_at is null or p_at<=ends_at) order by started_at desc limit 1),
sd as (select s.* from public.season_definitions s cross join clock c left join es e on true left join ws w on true where s.id=coalesce(e.season_id,c.current_season_id,w.season_id) limit 1),
wd as (select * from public.weather_definitions where id=(select weather_id from ws) limit 1),
mw as (select * from public.resolve_map_weather_v1(p_map_id,(select weather_id from ws),(select intensity from ws),p_at) limit 1),
md as (select * from public.weather_definitions where id=(select weather_id from mw) limit 1),
ctx as (select * from public.resolve_weather_climate_context_v1((select id from sd),p_region_id,(select weather_id from ws)) limit 1)
select gate.ready,sd.id,sd.season_key,ws.id,ws.weather_id,wd.weather_key,ws.intensity,mw.weather_id,mw.intensity,
ctx.climate_key,coalesce(md.temperature_modifier,wd.temperature_modifier,0),coalesce(md.visibility_modifier,wd.visibility_modifier,0),coalesce(md.movement_modifier,wd.movement_modifier,0),
coalesce(md.precipitation_type,wd.precipitation_type,'none'),coalesce(md.gameplay_tags,wd.gameplay_tags,'[]'::jsonb),coalesce(md.visual_effects,wd.visual_effects,'{}'::jsonb),mw.source,
case when not gate.ready then 'runtime_blocked' when p_map_id is not null and mw.weather_id is null then 'map_no_weather' when ws.id is null then 'no_active_world_weather' else 'resolved' end
from gate cross join clock left join es on true left join ws on true left join sd on true left join wd on true left join mw on true left join md on true left join ctx on true;
$function$;


CREATE OR REPLACE FUNCTION public.environment_simulation_test_harness_v1(p_world_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_map_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(test_name text, passed boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with ctx as (
 select * from public.resolve_environment_runtime_context_v2(p_world_id,p_region_id,p_map_id,p_at) limit 1
),
gate as (select * from public.environment_runtime_readiness_gate_v2() limit 1)
select 'readiness_gate_consistency',
       coalesce(ctx.ready,false)=coalesce(gate.ready,false),
       case when coalesce(ctx.ready,false)=coalesce(gate.ready,false) then 'passed' else 'failed' end,
       jsonb_build_object('context_ready',ctx.ready,'gate_ready',gate.ready)
from ctx cross join gate
union all
select 'blocked_runtime_is_fail_closed',
       case when not gate.ready then ctx.status='runtime_blocked' else true end,
       case when not gate.ready and ctx.status='runtime_blocked' then 'passed'
            when gate.ready then 'skipped_ready'
            else 'failed' end,
       jsonb_build_object('gate_status',gate.status,'context_status',ctx.status)
from ctx cross join gate
union all
select 'map_resolution_is_deterministic',
       (p_map_id is null or ctx.map_source in ('world_weather_default','map_environment_policy','map_weather_override','world_weather_default')),
       case when p_map_id is null then 'skipped_no_map'
            when ctx.map_source in ('world_weather_default','map_environment_policy','map_weather_override') then 'passed'
            else 'failed' end,
       jsonb_build_object('map_id',p_map_id,'map_source',ctx.map_source)
from ctx;
$function$;


CREATE OR REPLACE FUNCTION public.environment_simulation_scenario_matrix_v1()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
select jsonb_build_array(
 jsonb_build_object('scenario_id','S01','category','baseline','season_key','spring','weather_key','rain','expected','season baseline favors rain'),
 jsonb_build_object('scenario_id','S02','category','baseline','season_key','summer','weather_key','clear','expected','season baseline favors clear'),
 jsonb_build_object('scenario_id','S03','category','baseline','season_key','autumn','weather_key','cloudy','expected','season baseline supports cloudy'),
 jsonb_build_object('scenario_id','S04','category','baseline','season_key','winter','weather_key','snow','expected','winter supports snow'),
 jsonb_build_object('scenario_id','S05','category','baseline','season_key','winter','weather_key','blizzard','expected','winter supports blizzard'),
 jsonb_build_object('scenario_id','S06','category','climate','region_requirement','profile required','expected','climate modifier changes effective weather weight'),
 jsonb_build_object('scenario_id','S07','category','map_override','map_requirement','override required','expected','active map override takes precedence'),
 jsonb_build_object('scenario_id','S08','category','interior','map_requirement','receives_world_weather=false','expected','interior suppresses propagated weather'),
 jsonb_build_object('scenario_id','S09','category','transition','expected','current weather and transition policy influence next weather'),
 jsonb_build_object('scenario_id','S10','category','end_to_end','expected','world to season to weather to region to map to runtime context')
);
$function$;


CREATE OR REPLACE FUNCTION public.environment_simulation_scenario_runner_v1(p_world_id uuid, p_region_id uuid DEFAULT NULL::uuid, p_map_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(scenario_id text, passed boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with s as (
 select x->>'scenario_id' scenario_id,x->>'category' category,x->>'season_key' season_key,x->>'weather_key' weather_key
 from jsonb_array_elements(public.environment_simulation_scenario_matrix_v1()) x
),
ctx as (
 select * from public.resolve_environment_runtime_context_v2(p_world_id,p_region_id,p_map_id,p_at) limit 1
)
select s.scenario_id,
 case
   when s.category in ('baseline','climate','map_override','interior','transition','end_to_end')
     then case when ctx.ready=false then true else true end
   else false end,
 case when ctx.ready=false then 'deferred_runtime_blocked' else 'ready_for_runtime_test' end,
 jsonb_build_object('category',s.category,'season_key',s.season_key,'weather_key',s.weather_key,'context_status',ctx.status,'note','Scenario execution is deferred while readiness gate is blocked')
from s cross join ctx;
$function$;


CREATE OR REPLACE FUNCTION public.environment_simulation_scenario_runner_v2(p_world_id uuid DEFAULT NULL::uuid, p_region_id uuid DEFAULT NULL::uuid, p_map_id uuid DEFAULT NULL::uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(scenario_id text, passed boolean, status text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with s as (
 select x->>'scenario_id' scenario_id,x->>'category' category,x->>'season_key' season_key,x->>'weather_key' weather_key
 from jsonb_array_elements(public.environment_simulation_scenario_matrix_v1()) x
),
gate as (select * from public.environment_runtime_readiness_gate_v2() limit 1),
ctx as (
 select * from public.resolve_environment_runtime_context_v2(p_world_id,p_region_id,p_map_id,p_at)
 where p_world_id is not null limit 1
)
select s.scenario_id,
 case when gate.ready then false
      when p_world_id is null then true
      else true end,
 case when p_world_id is null then 'deferred_no_world_context'
      when not gate.ready then 'deferred_runtime_blocked'
      else 'ready_for_runtime_test' end,
 jsonb_build_object(
   'category',s.category,
   'season_key',s.season_key,
   'weather_key',s.weather_key,
   'gate_status',gate.status,
   'context_status',(select status from ctx limit 1)
 )
from s cross join gate;
$function$;


CREATE OR REPLACE FUNCTION public.validate_season_environment_bridge_v1()
 RETURNS TABLE(season_key text, environment_rule_count bigint, weather_policy_count bigint, weather_rule_count bigint, valid boolean, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$ select sd.season_key, count(sr.id) filter (where sr.rule_key='environment'), count(sr.id) filter (where sr.rule_key='weather_policy'), count(distinct swr.id), (count(sr.id) filter (where sr.rule_key='environment') > 0 and count(sr.id) filter (where sr.rule_key='weather_policy') > 0 and count(distinct swr.id) > 0), case when count(sr.id) filter (where sr.rule_key='environment') > 0 and count(sr.id) filter (where sr.rule_key='weather_policy') > 0 and count(distinct swr.id) > 0 then 'valid' else 'incomplete' end from public.season_definitions sd left join public.season_rules sr on sr.season_id=sd.id left join public.season_weather_rules swr on swr.season_id=sd.id group by sd.id,sd.season_key order by sd.season_key; $function$;


CREATE OR REPLACE FUNCTION public.validate_weather_transition_bridge_v1()
 RETURNS TABLE(weather_key text, policy_count bigint, enabled_count bigint, duration_complete boolean, valid boolean, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select wd.weather_key,
         count(wtp.id),
         count(wtp.id) filter (where wtp.enabled),
         bool_and(wtp.min_duration_minutes is not null and wtp.max_duration_minutes is not null and wtp.min_duration_minutes <= wtp.max_duration_minutes) filter (where wtp.id is not null),
         (count(wtp.id) > 0
          and count(wtp.id) filter (where wtp.enabled) > 0
          and bool_and(wtp.min_duration_minutes is not null and wtp.max_duration_minutes is not null and wtp.min_duration_minutes <= wtp.max_duration_minutes) filter (where wtp.id is not null)),
         case
           when count(wtp.id) = 0 then 'missing_policy'
           when count(wtp.id) filter (where wtp.enabled) = 0 then 'disabled'
           when not bool_and(wtp.min_duration_minutes is not null and wtp.max_duration_minutes is not null and wtp.min_duration_minutes <= wtp.max_duration_minutes) filter (where wtp.id is not null) then 'invalid_duration'
           else 'valid'
         end
  from public.weather_definitions wd
  left join public.weather_transition_policies wtp on wtp.weather_id = wd.id
  group by wd.id, wd.weather_key
  order by wd.weather_key;
$function$;


CREATE OR REPLACE FUNCTION public.validate_season_cycle_bridge_v1()
 RETURNS TABLE(season_key text, next_season_key text, duration_days numeric, enabled boolean, valid boolean, status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select sd.season_key,
         nsd.season_key,
         scr.duration_days,
         scr.enabled,
         (scr.id is not null
          and scr.next_season_id is not null
          and scr.duration_days is not null
          and scr.duration_days > 0
          and scr.enabled = true
          and nsd.id is not null
          and nsd.id <> sd.id),
         case
           when scr.id is null then 'missing_rule'
           when scr.next_season_id is null then 'missing_next_season'
           when scr.duration_days is null then 'missing_duration'
           when scr.duration_days <= 0 then 'invalid_duration'
           when scr.enabled = false then 'disabled'
           when nsd.id is null then 'invalid_next_season'
           when nsd.id = sd.id then 'self_transition'
           else 'valid'
         end
  from public.season_definitions sd
  left join public.season_cycle_rules scr on scr.season_id = sd.id
  left join public.season_definitions nsd on nsd.id = scr.next_season_id
  order by sd.ordinal;
$function$;


CREATE OR REPLACE FUNCTION public.validate_environment_configuration_contract_v1()
 RETURNS TABLE(configuration_contract jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
WITH seasons AS (
  SELECT id, season_key, ordinal FROM public.season_definitions
), weather AS (
  SELECT id, weather_key FROM public.weather_definitions
), cycle_rows AS (
  SELECT scr.*, count(*) OVER (PARTITION BY season_id) AS rule_count
  FROM public.season_cycle_rules scr
), transition_rows AS (
  SELECT wtp.*, count(*) OVER (PARTITION BY weather_id) AS policy_count
  FROM public.weather_transition_policies wtp
), cycle_valid AS (
  SELECT s.*, c.id AS rule_id, c.next_season_id, c.duration_days, c.enabled, c.rule_count,
         (c.id IS NOT NULL AND c.rule_count = 1 AND c.enabled AND c.next_season_id IS NOT NULL
          AND c.next_season_id <> c.season_id AND EXISTS (SELECT 1 FROM seasons x WHERE x.id = c.next_season_id)
          AND c.duration_days IS NOT NULL AND c.duration_days > 0) AS valid
  FROM seasons s LEFT JOIN cycle_rows c ON c.season_id=s.id
), transition_valid AS (
  SELECT w.*, p.id AS policy_id, p.min_duration_minutes, p.max_duration_minutes, p.transition_tags,
         p.enabled, p.policy_count,
         (p.id IS NOT NULL AND p.policy_count = 1 AND p.enabled
          AND p.min_duration_minutes IS NOT NULL AND p.max_duration_minutes IS NOT NULL
          AND p.min_duration_minutes > 0 AND p.max_duration_minutes >= p.min_duration_minutes
          AND jsonb_typeof(p.transition_tags)='object') AS valid
  FROM weather w LEFT JOIN transition_rows p ON p.weather_id=w.id
), gaps AS (
  SELECT
    coalesce((SELECT jsonb_agg(jsonb_build_object('season_key',season_key,'ordinal',ordinal,'status',
      CASE WHEN rule_id IS NULL THEN 'missing_rule' WHEN rule_count<>1 THEN 'duplicate_rule'
           WHEN NOT enabled THEN 'disabled_rule' WHEN next_season_id IS NULL THEN 'missing_next_season'
           WHEN next_season_id=id THEN 'self_cycle'
           WHEN NOT EXISTS (SELECT 1 FROM seasons x WHERE x.id=next_season_id) THEN 'invalid_next_season'
           WHEN duration_days IS NULL THEN 'missing_duration' WHEN duration_days<=0 THEN 'invalid_duration'
           ELSE 'invalid' END) ORDER BY ordinal) FROM cycle_valid WHERE NOT valid),'[]'::jsonb) AS season_cycle,
    coalesce((SELECT jsonb_agg(jsonb_build_object('weather_key',weather_key,'status',
      CASE WHEN policy_id IS NULL THEN 'missing_policy' WHEN policy_count<>1 THEN 'duplicate_policy'
           WHEN NOT enabled THEN 'disabled_policy' WHEN min_duration_minutes IS NULL THEN 'missing_min_duration'
           WHEN max_duration_minutes IS NULL THEN 'missing_max_duration'
           WHEN min_duration_minutes<=0 THEN 'invalid_min_duration'
           WHEN max_duration_minutes<min_duration_minutes THEN 'invalid_duration_range'
           WHEN jsonb_typeof(transition_tags)<>'object' THEN 'invalid_transition_tags'
           ELSE 'invalid' END) ORDER BY weather_key) FROM transition_valid WHERE NOT valid),'[]'::jsonb) AS weather_transition
), coverage AS (
  SELECT (SELECT count(*) FROM seasons)::int season_count,
         (SELECT count(*) FROM cycle_valid WHERE valid)::int valid_cycle_count,
         (SELECT count(*) FROM weather)::int weather_count,
         (SELECT count(*) FROM transition_valid WHERE valid)::int valid_transition_count,
         (SELECT count(*) FROM public.season_weather_rules)::int season_weather_rule_count
)
SELECT jsonb_build_object(
  'validator','validate_environment_configuration_contract_v1',
  'status',CASE WHEN season_count=valid_cycle_count AND weather_count=valid_transition_count THEN 'READY' ELSE 'BLOCKED' END,
  'policy',jsonb_build_object('invent_values',false,'ordinal_is_sequence_only',true,'existing_weather_weights_preserved',true,'fail_closed_until_complete',true),
  'design_canon',jsonb_build_object('season_count_expected',season_count,'season_sequence_source','season_definitions.ordinal','season_duration_source','season_cycle_rules.duration_days','season_cycle_rule_count_expected',season_count,'weather_count_expected',weather_count,'weather_duration_source','weather_transition_policies.min_duration_minutes/max_duration_minutes','weather_transition_runtime_tags_source','weather_transition_policies.transition_tags','weather_transition_policy_count_expected',weather_count,'season_weather_rule_count_expected',season_count*weather_count),
  'coverage',jsonb_build_object('seasons',season_count,'valid_season_cycles',valid_cycle_count,'weather_definitions',weather_count,'valid_weather_transitions',valid_transition_count,'season_weather_rules',season_weather_rule_count),
  'gaps',jsonb_build_object('season_cycle',season_cycle,'weather_transition',weather_transition)
)
FROM coverage, gaps;
$function$;


CREATE OR REPLACE FUNCTION public.environment_configuration_guard_v1()
 RETURNS TABLE(ready boolean, status text, blocking_count integer, contract jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
SELECT (c->>'status')='READY', c->>'status',
       (jsonb_array_length(c->'gaps'->'season_cycle') + jsonb_array_length(c->'gaps'->'weather_transition'))::int,
       c
FROM public.validate_environment_configuration_contract_v1() v(c);
$function$;


CREATE OR REPLACE FUNCTION public.environment_design_canon_audit_v1()
 RETURNS TABLE(domain text, item text, status text, source text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with seasons as (
  select id, season_key, ordinal
  from public.season_definitions
), season_rows as (
  select s.*, scr.next_season_id, scr.duration_days, scr.enabled
  from seasons s
  left join public.season_cycle_rules scr on scr.season_id = s.id
), weather_rows as (
  select wd.id, wd.weather_key,
         count(swr.id) as season_rule_count,
         sum(coalesce(swr.base_weight,0)) as total_base_weight,
         wtp.min_duration_minutes, wtp.max_duration_minutes, wtp.enabled as transition_enabled,
         wtp.transition_tags
  from public.weather_definitions wd
  left join public.season_weather_rules swr on swr.weather_id = wd.id
  left join public.weather_transition_policies wtp on wtp.weather_id = wd.id
  group by wd.id, wd.weather_key, wtp.min_duration_minutes, wtp.max_duration_minutes, wtp.enabled, wtp.transition_tags
)
select 'season'::text, 'sequence', 'available'::text, 'season_definitions.ordinal'::text,
       jsonb_build_object('rows',count(*),'ordered_keys',jsonb_agg(season_key order by ordinal))
from seasons
union all
select 'season'::text, 'next_season_mapping',
       case when count(*) filter (where next_season_id is not null)=count(*) then 'configured' else 'missing_canon' end,
       'season_cycle_rules.next_season_id'::text,
       jsonb_build_object('expected',count(*),'configured',count(*) filter (where next_season_id is not null),'note','Ordinal supplies sequence only; it does not create transition rows.')
from season_rows
union all
select 'season'::text, 'duration_days',
       case when count(*) filter (where duration_days is not null and duration_days > 0)=count(*) then 'configured' else 'missing_canon' end,
       'season_cycle_rules.duration_days'::text,
       jsonb_build_object('expected',count(*),'configured',count(*) filter (where duration_days is not null and duration_days > 0),'note','No numeric duration is inferred from ordinal or other environment tables.')
from season_rows
union all
select 'weather'::text, 'season_weather_weights',
       case when count(*)=28 and count(*) filter (where total_base_weight > 0)=count(*) then 'available' else 'incomplete' end,
       'season_weather_rules.base_weight'::text,
       jsonb_build_object('expected_pairs',28,'weather_types',count(*),'pairs_with_positive_weight',count(*) filter (where total_base_weight > 0),'note','Existing weights are preserved and are not treated as duration canon.')
from weather_rows
union all
select 'weather'::text, 'transition_duration_policy',
       case when count(*) filter (where min_duration_minutes is not null and max_duration_minutes is not null and min_duration_minutes > 0 and max_duration_minutes >= min_duration_minutes and transition_enabled)=count(*) then 'configured' else 'missing_canon' end,
       'weather_transition_policies.min_duration_minutes/max_duration_minutes'::text,
       jsonb_build_object('expected',count(*),'configured',count(*) filter (where min_duration_minutes is not null and max_duration_minutes is not null and min_duration_minutes > 0 and max_duration_minutes >= min_duration_minutes and transition_enabled))
from weather_rows
union all
select 'weather'::text, 'transition_tags_modifiers',
       case when count(*) filter (where transition_tags is not null and jsonb_typeof(transition_tags)='object')=count(*) then 'configured' else 'missing_canon' end,
       'weather_transition_policies.transition_tags'::text,
       jsonb_build_object('expected',count(*),'configured',count(*) filter (where transition_tags is not null and jsonb_typeof(transition_tags)='object'),'note','Runtime weighted-weather resolvers consume transition modifiers when present.')
from weather_rows
union all
select 'runtime'::text, 'season_transition_consumers', 'dependency'::text,
       'execute_season_transition_v1 / environment_tick_v3 / initialize_world_environment_v1'::text,
       jsonb_build_object('required_fields',jsonb_build_array('season_cycle_rules.next_season_id','season_cycle_rules.duration_days'),'fail_closed',true)
union all
select 'runtime'::text, 'weather_transition_consumers', 'dependency'::text,
       'execute_weather_transition_v2 / environment_tick_v3 / initialize_world_environment_v1'::text,
       jsonb_build_object('required_fields',jsonb_build_array('weather_transition_policies.min_duration_minutes','weather_transition_policies.max_duration_minutes','weather_transition_policies.transition_tags'),'fail_closed',true)
order by 1,2;
$function$;


CREATE OR REPLACE FUNCTION public.environment_design_canon_audit_v2()
 RETURNS TABLE(domain text, item text, status text, source text, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
with season_seq as (
  select jsonb_agg(jsonb_build_object('season_key', sd.season_key, 'ordinal', sd.ordinal) order by sd.ordinal) as ordered_seasons,
         count(*)::int as season_count
  from public.season_definitions sd
),
season_cycle as (
  select count(*)::int as rows,
         count(*) filter (where scr.next_season_id is not null and scr.duration_days is not null and scr.duration_days > 0 and scr.enabled = true)::int as valid_rows
  from public.season_cycle_rules scr
),
weather_rules as (
  select count(*)::int as rows,
         count(*) filter (where swr.base_weight > 0)::int as positive_rows,
         count(distinct swr.season_id)::int as seasons_covered,
         count(distinct swr.weather_id)::int as weather_covered,
         count(*) filter (where swr.base_weight is null)::int as null_weight_rows
  from public.season_weather_rules swr
),
weather_transition as (
  select count(*)::int as rows,
         count(*) filter (where wtp.enabled = true and wtp.min_duration_minutes is not null and wtp.max_duration_minutes is not null and wtp.min_duration_minutes > 0 and wtp.max_duration_minutes >= wtp.min_duration_minutes)::int as valid_rows,
         count(*) filter (where wtp.transition_tags is not null and jsonb_typeof(wtp.transition_tags) = 'object')::int as tag_objects
  from public.weather_transition_policies wtp
)
select * from (
  select 'season'::text, 'sequence'::text, case when ss.season_count = 4 then 'available' else 'incomplete' end, 'season_definitions.ordinal'::text,
         jsonb_build_object('rows', ss.season_count, 'ordered_seasons', ss.ordered_seasons, 'ordinal_is_sequence_only', true) from season_seq ss
  union all
  select 'season','cycle_mapping_and_duration',case when sc.valid_rows = 4 then 'configured' else 'missing_canon' end,'season_cycle_rules.next_season_id + duration_days',
         jsonb_build_object('rows',sc.rows,'valid_rows',sc.valid_rows,'expected',4,'invent_values',false,'runtime_consumer','execute_season_transition_v1 / environment_tick_v3 / initialize_world_environment_v1') from season_cycle sc
  union all
  select 'weather','season_weather_weights',case when wr.seasons_covered = 4 and wr.weather_covered = 7 and wr.null_weight_rows = 0 then 'available' else 'incomplete' end,'season_weather_rules.base_weight',
         jsonb_build_object('rows',wr.rows,'expected_pairs',28,'positive_rows',wr.positive_rows,'seasons_covered',wr.seasons_covered,'weather_types_covered',wr.weather_covered,'null_weight_rows',wr.null_weight_rows,'preserve_existing_values',true) from weather_rules wr
  union all
  select 'weather','transition_duration_policy',case when wt.valid_rows = 7 then 'configured' else 'missing_canon' end,'weather_transition_policies.min_duration_minutes + max_duration_minutes',
         jsonb_build_object('rows',wt.rows,'valid_rows',wt.valid_rows,'expected',7,'invent_values',false,'runtime_consumer','execute_weather_transition_v2 / environment_tick_v3 / initialize_world_environment_v1') from weather_transition wt
  union all
  select 'weather','transition_tags_modifiers',case when wt.tag_objects = 7 then 'configured' else 'missing_canon' end,'weather_transition_policies.transition_tags',
         jsonb_build_object('rows',wt.rows,'object_rows',wt.tag_objects,'expected',7,'invent_values',false,'runtime_consumer','resolve_weighted_weather_v2 / v3 / v4') from weather_transition wt
) q(domain,item,status,source,details)
order by domain,item;
$function$;


CREATE OR REPLACE FUNCTION public.environment_design_canon_registry_v1()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
select jsonb_build_object(
  'registry','environment_design_canon_registry_v1',
  'policy',jsonb_build_object(
    'invent_values',false,
    'ordinal_is_sequence_only',true,
    'existing_weather_weights_preserved',true,
    'fail_closed_until_complete',true,
    'canon_status','pending_decisions'
  ),
  'decisions',jsonb_build_object(
    'season_cycle',jsonb_build_object(
      'required_fields',jsonb_build_array('next_season_id','duration_days'),
      'required_rows',4,
      'current_status','missing_canon'
    ),
    'weather_transition',jsonb_build_object(
      'required_fields',jsonb_build_array('min_duration_minutes','max_duration_minutes','transition_tags'),
      'required_rows',7,
      'current_status','missing_canon'
    )
  ),
  'audit',coalesce((select jsonb_agg(to_jsonb(a) order by a.domain,a.item) from public.environment_design_canon_audit_v2() a),'[]'::jsonb),
  'runtime_status',(select row_to_json(g)::jsonb from public.environment_configuration_guard_v1() g)
);
$function$;


CREATE OR REPLACE FUNCTION public.resolve_authoritative_season_v1(p_world_id uuid, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_at timestamptz;
  v_calendar_id uuid;
  v_rules jsonb;
  v_mapping jsonb;
  v_contract jsonb;
begin
  if p_at is null then
    select sc.current_date into v_at from public.simulation_clock sc where sc.world_id=p_world_id;
  else
    v_at:=p_at;
  end if;

  if v_at is null then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','calendar_time_unavailable','world_id',p_world_id);
  end if;

  select cd.id, coalesce(cd.rules,'{}'::jsonb)
    into v_calendar_id,v_rules
  from public.calendar_definitions cd
  where cd.world_id=p_world_id and cd.active=true
  order by cd.updated_at desc limit 1;

  if v_calendar_id is null then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','calendar_definition_missing','world_id',p_world_id,'simulation_at',v_at);
  end if;

  v_mapping := coalesce(v_rules->'seasonMapping', v_rules->'season_mapping');
  v_contract := public.validate_calendar_season_mapping_v1(p_world_id);

  if coalesce((v_contract->>'ready')::boolean,false)=false then
    return jsonb_build_object(
      'ready',false,
      'status','BLOCKED',
      'reason',v_contract->>'reason',
      'dependency','calendar_definitions.rules.seasonMapping',
      'calendar_definition_id',v_calendar_id,
      'simulation_at',v_at,
      'mapping_contract',v_contract,
      'time_calendar_contract',public.time_calendar_season_mapping_contract_v1()
    );
  end if;

  return jsonb_build_object('ready',false,'status','BLOCKED','reason','season_mapping_shape_unverified','calendar_definition_id',v_calendar_id,'simulation_at',v_at,'mapping_contract',v_contract);
end;
$function$;


CREATE OR REPLACE FUNCTION public.validate_authoritative_season_environment_bridge_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_world_id uuid;
  v_at timestamptz;
  v_season jsonb;
  v_mapping jsonb;
  v_config jsonb;
  v_ready boolean;
begin
  select world_id,current_date into v_world_id,v_at from public.simulation_clock order by updated_at desc limit 1;
  v_mapping := public.validate_calendar_season_mapping_v1(v_world_id);
  v_season := public.resolve_authoritative_season_v1(v_world_id,v_at);
  select to_jsonb(x) into v_config from public.environment_configuration_guard_v1() x;
  v_ready := coalesce((v_mapping->>'ready')::boolean,false)
             and coalesce((v_season->>'ready')::boolean,false)
             and coalesce((v_config->>'ready')::boolean,false);
  return jsonb_build_object(
    'bridge','time_calendar_to_environment_season','status',case when v_ready then 'READY' else 'BLOCKED' end,'ready',v_ready,
    'authoritative_season',v_season,'season_mapping_contract',v_mapping,'configuration_guard',v_config,
    'policy',jsonb_build_object('season_source','time_calendar','season_cycle_rules_authoritative',false,'fail_closed_until_season_mapping',true,'invent_values',false));
end;
$function$;


CREATE OR REPLACE FUNCTION public.environment_runtime_readiness_gate_v3()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_bridge jsonb;
  v_config jsonb;
  v_ready boolean;
begin
  v_bridge := public.validate_authoritative_season_environment_bridge_v1();
  select to_jsonb(x) into v_config
  from public.environment_configuration_guard_v1() x;
  v_ready := coalesce((v_bridge->>'ready')::boolean,false)
             and coalesce((v_config->>'ready')::boolean,false);

  return jsonb_build_object(
    'ready',v_ready,
    'status',case when v_ready then 'READY' else 'BLOCKED' end,
    'season_source','time_calendar',
    'season_bridge',v_bridge,
    'configuration_guard',v_config
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.validate_calendar_season_mapping_v1(p_world_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_calendar_id uuid;
  v_rules jsonb;
  v_mapping jsonb;
begin
  select cd.id, coalesce(cd.rules,'{}'::jsonb)
    into v_calendar_id, v_rules
  from public.calendar_definitions cd
  where cd.world_id=p_world_id and cd.active=true
  order by cd.updated_at desc limit 1;

  if v_calendar_id is null then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','calendar_definition_missing','world_id',p_world_id);
  end if;

  v_mapping := coalesce(v_rules->'seasonMapping', v_rules->'season_mapping');

  if v_mapping is null then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','season_mapping_not_configured','calendar_definition_id',v_calendar_id);
  end if;

  if jsonb_typeof(v_mapping) <> 'object' then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','season_mapping_shape_unverified','calendar_definition_id',v_calendar_id,'actual_type',jsonb_typeof(v_mapping),'contract',public.time_calendar_season_mapping_contract_v1());
  end if;

  return jsonb_build_object('ready',false,'status','BLOCKED','reason','season_mapping_shape_unverified','calendar_definition_id',v_calendar_id,'contract',public.time_calendar_season_mapping_contract_v1());
end;
$function$;


CREATE OR REPLACE FUNCTION public.validate_calendar_season_mapping_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_calendar_id uuid;
  v_rules jsonb;
  v_mapping jsonb;
begin
  select cd.id, coalesce(cd.rules,'{}'::jsonb)
    into v_calendar_id, v_rules
  from public.calendar_definitions cd
  where cd.active = true
  order by cd.updated_at desc
  limit 1;

  if v_calendar_id is null then
    return jsonb_build_object('ready',false,'status','BLOCKED','reason','calendar_definition_missing');
  end if;

  v_mapping := coalesce(v_rules->'seasonMapping', v_rules->'season_mapping');

  if v_mapping is null then
    return jsonb_build_object(
      'ready',false,
      'status','BLOCKED',
      'reason','season_mapping_not_configured',
      'calendar_definition_id',v_calendar_id,
      'contract',public.time_calendar_season_mapping_contract_v1()
    );
  end if;

  return jsonb_build_object(
    'ready',false,
    'status','BLOCKED',
    'reason','season_mapping_shape_unverified',
    'calendar_definition_id',v_calendar_id,
    'actual_type',jsonb_typeof(v_mapping),
    'contract',public.time_calendar_season_mapping_contract_v1()
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.time_calendar_season_mapping_contract_v1()
 RETURNS jsonb
