CREATE OR REPLACE FUNCTION public.validate_inventory_item_lifecycle_contract_v1()
 RETURNS TABLE(ready boolean, status text, item_instance_count bigint, invalid_lifecycle_status_count bigint, broken_active_count bigint, invalid_durability_count bigint, issue_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with checks as (
    select
      count(*) as total,
      count(*) filter (where lifecycle_status not in ('active','consumed','destroyed')) as invalid_lifecycle,
      count(*) filter (where is_broken = true and lifecycle_status <> 'active') as broken_non_active,
      count(*) filter (where max_durability is not null and max_durability < 0) as invalid_max_durability,
      count(*) filter (where condition is not null and condition < 0) as invalid_condition,
      count(*) filter (where max_durability is not null and condition is not null and condition > max_durability) as condition_over_max
    from public.item_instances
  )
  select
    (invalid_lifecycle + broken_non_active + invalid_max_durability + invalid_condition + condition_over_max = 0) as ready,
    case when (invalid_lifecycle + broken_non_active + invalid_max_durability + invalid_condition + condition_over_max = 0)
         then 'PASS' else 'BLOCKED' end as status,
    total,
    invalid_lifecycle,
    broken_non_active,
    (invalid_max_durability + invalid_condition + condition_over_max),
    (invalid_lifecycle + broken_non_active + invalid_max_durability + invalid_condition + condition_over_max)
  from checks;
$function$;


CREATE OR REPLACE FUNCTION public.validate_equipment_inventory_bridge_v1()
 RETURNS TABLE(ready boolean, status text, equipment_loadout_count bigint, missing_item_instance_count bigint, missing_inventory_entry_count bigint, item_mismatch_count bigint, life_ownership_mismatch_count bigint, broken_equipped_count bigint, inactive_equipped_count bigint, issue_count bigint, canon_status text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with audit as (
    select
      count(e.id) as loadouts,
      count(*) filter (where ii.id is null) as missing_instance,
      count(*) filter (where ie.id is null) as missing_inventory,
      count(*) filter (where ii.id is not null and ii.item_id is distinct from ie.item_id) as item_mismatch,
      count(*) filter (
        where ie.id is not null
          and c.owner_type = 'life'
          and c.owner_life_id is distinct from e.life_id
      ) as life_mismatch,
      count(*) filter (where ii.is_broken = true) as broken_equipped,
      count(*) filter (where ii.lifecycle_status is distinct from 'active') as inactive_equipped
    from public.equipment_loadouts e
    left join public.item_instances ii on ii.id = e.item_instance_id
    left join lateral (
      select ie.*
      from public.inventory_entries ie
      where ie.item_instance_id = e.item_instance_id
      order by ie.updated_at desc, ie.id desc
      limit 1
    ) ie on true
    left join public.containers c on c.id = ie.container_id
  )
  select
    false as ready,
    'BLOCKED'::text as status,
    loadouts,
    missing_instance,
    missing_inventory,
    item_mismatch,
    life_mismatch,
    broken_equipped,
    inactive_equipped,
    (missing_instance + missing_inventory + item_mismatch + life_mismatch + broken_equipped + inactive_equipped) as issue_count,
    'PENDING_CANON'::text as canon_status
  from audit;
$function$;


CREATE OR REPLACE FUNCTION public.time_engine_season_mapping_bridge_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  calendar_row record;
  mapping jsonb;
  missing_months int[] := ARRAY[]::int[];
  month_no int;
  season_key text;
BEGIN
  SELECT id, rules
    INTO calendar_row
  FROM public.calendar_definitions
  WHERE active = true
    AND name = 'Vandrith Standard Calendar'
  ORDER BY created_at DESC
  LIMIT 1;

  IF calendar_row.id IS NULL THEN
    RETURN jsonb_build_object('status','blocked','reason','active_calendar_missing');
  END IF;

  mapping := COALESCE(calendar_row.rules -> 'seasonMapping', '{}'::jsonb);

  FOR month_no IN 1..12 LOOP
    season_key := mapping ->> month_no::text;
    IF season_key IS NULL OR season_key NOT IN ('spring','summer','autumn','winter') THEN
      missing_months := array_append(missing_months, month_no);
    END IF;
  END LOOP;

  IF cardinality(missing_months) > 0 THEN
    RETURN jsonb_build_object('status','pending_canon','calendar_id',calendar_row.id,'missing_months',to_jsonb(missing_months),'invent_values',false,'source','calendar_definitions.rules.seasonMapping');
  END IF;

  RETURN jsonb_build_object('status','ready','calendar_id',calendar_row.id,'seasonMapping',mapping,'source','calendar_definitions.rules.seasonMapping');
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_environment_resolver_v1(p_map_id uuid, p_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
  season_result jsonb;
BEGIN
  season_result := public.time_engine_season_mapping_bridge_v1();

  IF COALESCE(season_result->>'status','') <> 'ready' THEN
    RETURN jsonb_build_object(
      'status','blocked',
      'reason','season_mapping_not_ready',
      'season',season_result,
      'map_id',p_map_id,
      'at',p_at
    );
  END IF;

  result := jsonb_build_object(
    'status','ready',
    'map_id',p_map_id,
    'at',p_at,
    'season',season_result,
    'weather','unresolved',
    'terrain','deferred_to_terrain_resolver'
  );

  RETURN result;
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_terrain_resolver_v1(p_map_id uuid, p_grid_x integer, p_grid_y integer, p_season_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  cell_row record;
  variant_result jsonb;
BEGIN
  SELECT * INTO cell_row
  FROM public.map_cells
  WHERE map_id = p_map_id AND grid_x = p_grid_x AND grid_y = p_grid_y
  LIMIT 1;

  IF cell_row.map_id IS NULL THEN
    RETURN jsonb_build_object('status','not_found','map_id',p_map_id,'grid_x',p_grid_x,'grid_y',p_grid_y);
  END IF;

  variant_result := NULL;
  IF p_season_id IS NOT NULL THEN
    IF cell_row.terrain_asset_id IS NOT NULL THEN
      BEGIN
        SELECT public.resolve_seasonal_asset_variant_v1(cell_row.terrain_asset_id, p_season_id) INTO variant_result;
      EXCEPTION WHEN undefined_function OR invalid_parameter_value THEN
        variant_result := NULL;
      END;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'status','ready',
    'map_id',p_map_id,
    'grid_x',p_grid_x,
    'grid_y',p_grid_y,
    'terrain_asset_id',cell_row.terrain_asset_id,
    'structural_asset_id',cell_row.structural_asset_id,
    'decoration_asset_id',cell_row.decoration_asset_id,
    'elevation',cell_row.elevation,
    'biome',cell_row.biome,
    'season_variant',cell_row.season_variant,
    'collision',cell_row.collision,
    'walkable',cell_row.walkable,
    'seasonal_variant',variant_result
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_refresh_navigation_projection_v1(p_map_id uuid, p_grid_x integer, p_grid_y integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  cell_row record;
  nav_result jsonb;
BEGIN
  SELECT * INTO cell_row
  FROM public.map_cells
  WHERE map_id = p_map_id AND grid_x = p_grid_x AND grid_y = p_grid_y
  LIMIT 1;

  IF cell_row.map_id IS NULL THEN
    RETURN jsonb_build_object('status','not_found','map_id',p_map_id,'grid_x',p_grid_x,'grid_y',p_grid_y);
  END IF;

  nav_result := public.refresh_map_navigation_cell_v1(p_map_id, p_grid_x, p_grid_y);

  RETURN jsonb_build_object(
    'status','ready',
    'map_id',p_map_id,
    'grid_x',p_grid_x,
    'grid_y',p_grid_y,
    'walkable',cell_row.walkable,
    'collision',cell_row.collision,
    'terrain_variant',cell_row.terrain_variant,
    'season_variant',cell_row.season_variant,
    'navigation',nav_result
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_set_cell_v1(p_map_id uuid, p_grid_x integer, p_grid_y integer, p_terrain_asset_id uuid DEFAULT NULL::uuid, p_structural_asset_id uuid DEFAULT NULL::uuid, p_decoration_asset_id uuid DEFAULT NULL::uuid, p_elevation integer DEFAULT 0, p_biome text DEFAULT NULL::text, p_season_variant text DEFAULT NULL::text, p_collision boolean DEFAULT false, p_walkable boolean DEFAULT true, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
  nav jsonb;
BEGIN
  PERFORM public.set_map_cell(
    p_map_id, p_grid_x, p_grid_y, p_terrain_asset_id, p_structural_asset_id,
    p_decoration_asset_id, p_elevation, p_biome, p_season_variant,
    p_collision, p_walkable, p_metadata
  );

  nav := public.map_editor_refresh_navigation_projection_v1(p_map_id, p_grid_x, p_grid_y);

  result := jsonb_build_object(
    'status','ready',
    'operation','set_cell',
    'map_id',p_map_id,
    'grid_x',p_grid_x,
    'grid_y',p_grid_y,
    'navigation',nav
  );
  RETURN result;
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_save_document_snapshot_v1(p_map_id uuid, p_document jsonb, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  uid uuid := auth.uid();
  next_version integer;
  version_id uuid;
BEGIN
  IF uid IS NULL THEN RETURN jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.maps WHERE id=p_map_id AND created_by=uid) THEN
    RETURN jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED');
  END IF;
  IF p_document IS NULL OR jsonb_typeof(p_document) <> 'object' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_DOCUMENT');
  END IF;
  IF p_document->>'schema' <> 'vandrith.map-document' OR (p_document->>'version')::int <> 1 THEN
    RETURN jsonb_build_object('ok',false,'code','UNSUPPORTED_DOCUMENT_VERSION');
  END IF;
  SELECT COALESCE(MAX(version_number),0)+1 INTO next_version FROM public.map_versions WHERE map_id=p_map_id;
  INSERT INTO public.map_versions(map_id,version_number,label,snapshot,created_by)
  VALUES(p_map_id,next_version,COALESCE(p_label,'Editor Save'),p_document,uid)
  RETURNING id INTO version_id;
  RETURN jsonb_build_object('ok',true,'map_id',p_map_id,'version_id',version_id,'version_number',next_version);
END;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_load_document_snapshot_v1(p_map_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  uid uuid := auth.uid();
  v_snapshot jsonb;
  v_version_number integer;
begin
  if uid is null then
    return jsonb_build_object('ok',false,'code','AUTH_REQUIRED');
  end if;
  if not public.map_editor_can_access_v1(p_map_id) then
    return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED');
  end if;

  select mv.snapshot, mv.version_number
    into v_snapshot, v_version_number
  from public.map_versions mv
  where mv.map_id = p_map_id
  order by mv.version_number desc
  limit 1;

  if v_snapshot is null then
    return jsonb_build_object('ok',false,'code','SNAPSHOT_NOT_FOUND');
  end if;

  return jsonb_build_object(
    'ok',true,
    'map_id',p_map_id,
    'version_number',v_version_number,
    'snapshot',v_snapshot
  );
end
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_upsert_runtime_snapshot_v1(p_map_id uuid, p_snapshot jsonb, p_version_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare r public.map_editor_runtime_snapshots%rowtype;
  begin
    if auth.uid() is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if;
    if not public.map_editor_can_access_v1(p_map_id) then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if;
    if jsonb_typeof(p_snapshot)<>'object' then return jsonb_build_object('ok',false,'code','INVALID_SNAPSHOT'); end if;
    if p_version_id is not null and not exists(select 1 from public.map_versions mv where mv.id=p_version_id and mv.map_id=p_map_id) then return jsonb_build_object('ok',false,'code','VERSION_ACCESS_DENIED'); end if;
    insert into public.map_editor_runtime_snapshots(map_id,version_id,snapshot,created_by) values(p_map_id,p_version_id,p_snapshot,auth.uid()) on conflict(map_id) do update set version_id=excluded.version_id,snapshot=excluded.snapshot,updated_at=now() returning * into r;
    return jsonb_build_object('ok',true,'id',r.id,'map_id',r.map_id,'version_id',r.version_id,'updated_at',r.updated_at);
  end; $function$;


CREATE OR REPLACE FUNCTION public.map_editor_get_runtime_snapshot_v1(p_map_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare r public.map_editor_runtime_snapshots%rowtype; v_latest public.map_versions%rowtype; v_runtime_version integer;
  begin
    if auth.uid() is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if;
    if not public.map_editor_can_access_v1(p_map_id) then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if;
    select * into v_latest from public.map_versions mv where mv.map_id=p_map_id order by mv.version_number desc limit 1;
    select * into r from public.map_editor_runtime_snapshots where map_id=p_map_id;
    if found then
      if r.version_id is not null then select mv.version_number into v_runtime_version from public.map_versions mv where mv.id=r.version_id and mv.map_id=p_map_id; end if;
      if v_latest.id is not null and r.version_id=v_latest.id then return jsonb_build_object('ok',true,'found',true,'id',r.id,'map_id',r.map_id,'version_id',r.version_id,'version_number',v_latest.version_number,'snapshot',r.snapshot,'updated_at',r.updated_at); end if;
      if v_latest.id is not null then return jsonb_build_object('ok',true,'found',true,'id',v_latest.id,'map_id',p_map_id,'version_id',v_latest.id,'version_number',v_latest.version_number,'snapshot',v_latest.snapshot,'updated_at',v_latest.created_at,'code','durable-version-fallback'); end if;
      return jsonb_build_object('ok',true,'found',true,'id',r.id,'map_id',r.map_id,'version_id',r.version_id,'version_number',coalesce(v_runtime_version,0),'snapshot',r.snapshot,'updated_at',r.updated_at,'code','runtime-only');
    end if;
    if v_latest.id is null then return jsonb_build_object('ok',true,'found',false,'map_id',p_map_id,'version_number',0,'code','NO_SNAPSHOT'); end if;
    return jsonb_build_object('ok',true,'found',true,'id',v_latest.id,'map_id',p_map_id,'version_id',v_latest.id,'version_number',v_latest.version_number,'snapshot',v_latest.snapshot,'updated_at',v_latest.created_at,'code','durable-version-fallback');
  end; $function$;


CREATE OR REPLACE FUNCTION public.map_editor_reconcile_after_merge_v1(p_map_id uuid, p_version_id uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare uid uuid:=auth.uid(); v_object_id uuid; nav_result jsonb; geometry_count integer; stale_geometry_count integer; v_width integer; v_height integer; v_ground_cells jsonb; v_projected_cells integer:=0; v_tile jsonb; v_idx integer; v_x integer; v_y integer; v_tile_id text;
  begin
    if uid is null then raise exception 'authentication required'; end if;
    if not public.map_editor_can_access_v1(p_map_id) then raise exception 'map not found or not accessible'; end if;
    if p_version_id is null then raise exception 'version_id required'; end if;
    if p_snapshot is null or jsonb_typeof(p_snapshot)<>'object' then raise exception 'snapshot must be a JSON object'; end if;
    if not exists(select 1 from public.map_versions where id=p_version_id and map_id=p_map_id) then raise exception 'version not found for map'; end if;
    select width,height into v_width,v_height from public.maps where id=p_map_id;
    select coalesce((select l->'cells' from jsonb_array_elements(coalesce(p_snapshot->'document'->'layers','[]'::jsonb)) l where l->>'kind'='ground' limit 1),'[]'::jsonb) into v_ground_cells;
    delete from public.map_cells where map_id=p_map_id;
    if jsonb_typeof(v_ground_cells)='array' then
      for v_idx in 0 .. greatest(jsonb_array_length(v_ground_cells)-1,-1) loop
        v_tile:=v_ground_cells->v_idx; v_tile_id:=nullif(v_tile->>'tileId','');
        if v_tile_id is not null then v_x:=v_idx%greatest(v_width,1); v_y:=floor(v_idx::numeric/greatest(v_width,1))::integer;
        if v_x>=0 and v_y>=0 and v_x<v_width and v_y<v_height then insert into public.map_cells(map_id,grid_x,grid_y,biome,terrain_variant,collision,walkable,metadata) values(p_map_id,v_x,v_y,v_tile_id,v_tile_id,false,true,jsonb_build_object('source','map_editor_snapshot','version_id',p_version_id)); v_projected_cells:=v_projected_cells+1; end if; end if;
      end loop;
    end if;
    select count(*)::integer into stale_geometry_count from public.map_object_geometry g where not exists(select 1 from public.map_objects o where o.id=g.object_id); delete from public.map_object_geometry g where not exists(select 1 from public.map_objects o where o.id=g.object_id);
    for v_object_id in select o.id from public.map_objects o where o.map_id=p_map_id loop perform public.sync_map_object_obb_v1(v_object_id); end loop;
    select count(*)::integer into geometry_count from public.map_object_geometry g join public.map_objects o on o.id=g.object_id where o.map_id=p_map_id;
    nav_result:=public.rebuild_map_navigation_projection_v1(p_map_id); perform public.map_editor_upsert_runtime_snapshot_v1(p_map_id,p_snapshot,p_version_id);
    return jsonb_build_object('ok',true,'map_id',p_map_id,'version_id',p_version_id,'projected_map_cells',v_projected_cells,'geometry_rows',geometry_count,'orphan_geometry_rows_removed',stale_geometry_count,'navigation',nav_result,'runtime_snapshot_version_id',p_version_id);
  end; $function$;


CREATE OR REPLACE FUNCTION public.set_map_created_by_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.created_by is null then
    new.created_by := auth.uid();
  end if;
  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_save_slot_v1(p_map_id uuid, p_slot_number smallint, p_label text, p_version_id uuid, p_version_number integer, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare v_uid uuid:=auth.uid(); v_slot public.map_editor_save_slots%rowtype;
  begin
    if v_uid is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if;
    if p_slot_number<1 or p_slot_number>12 then return jsonb_build_object('ok',false,'code','INVALID_SLOT'); end if;
    if not public.map_editor_can_access_v1(p_map_id) then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if;
    if p_snapshot is null or jsonb_typeof(p_snapshot)<>'object' then return jsonb_build_object('ok',false,'code','INVALID_SNAPSHOT'); end if;
    if p_version_number is null or p_version_number<1 then return jsonb_build_object('ok',false,'code','INVALID_VERSION'); end if;
    if not exists(select 1 from public.map_versions where id=p_version_id and map_id=p_map_id and version_number=p_version_number) then return jsonb_build_object('ok',false,'code','VERSION_ACCESS_DENIED'); end if;
    insert into public.map_editor_save_slots(map_id,slot_number,label,version_id,version_number,snapshot,created_by) values(p_map_id,p_slot_number,coalesce(nullif(btrim(p_label),''),format('Save Slot %s',p_slot_number)),p_version_id,p_version_number,p_snapshot,v_uid) on conflict(map_id,slot_number) do update set label=excluded.label,version_id=excluded.version_id,version_number=excluded.version_number,snapshot=excluded.snapshot,updated_at=now() returning * into v_slot;
    return jsonb_build_object('ok',true,'map_id',v_slot.map_id,'slot_number',v_slot.slot_number,'label',v_slot.label,'version_id',v_slot.version_id,'version_number',v_slot.version_number,'updated_at',v_slot.updated_at);
  end; $function$;


CREATE OR REPLACE FUNCTION public.map_editor_load_save_slot_v1(p_map_id uuid, p_slot_number smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare v_slot public.map_editor_save_slots%rowtype;
  begin
    if auth.uid() is null then return jsonb_build_object('ok',false,'code','AUTH_REQUIRED'); end if;
    if not public.map_editor_can_access_v1(p_map_id) or not exists(select 1 from public.maps where id=p_map_id and map_type='world') then return jsonb_build_object('ok',false,'code','MAP_ACCESS_DENIED'); end if;
    select * into v_slot from public.map_editor_save_slots where map_id=p_map_id and slot_number=p_slot_number;
    if not found then return jsonb_build_object('ok',false,'code','SLOT_EMPTY','slot_number',p_slot_number); end if;
    return jsonb_build_object('ok',true,'map_id',v_slot.map_id,'slot_number',v_slot.slot_number,'label',v_slot.label,'version_id',v_slot.version_id,'version_number',v_slot.version_number,'snapshot',v_slot.snapshot,'updated_at',v_slot.updated_at);
  end; $function$;


CREATE OR REPLACE FUNCTION public.map_editor_commit_merge_v1(p_map_id uuid, p_expected_version integer, p_snapshot jsonb, p_label text DEFAULT 'merge'::text)
 RETURNS TABLE(status text, version_id uuid, version_number integer, current_version integer, projection_status text, projection_error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  declare v_map public.maps%rowtype; v_current integer; v_version_id uuid; v_next integer; v_document jsonb; v_width integer; v_height integer; v_layer jsonb; v_projection_status text := 'not_run'; v_projection_error text := null;
  begin
    if auth.uid() is null then raise exception 'authentication required'; end if;
    if jsonb_typeof(p_snapshot) <> 'object' then raise exception 'DOCUMENT_VALIDATION_ERROR: snapshot must be a JSON object'; end if;
    if p_snapshot->>'schema' <> 'vandrith.map-document' then raise exception 'DOCUMENT_VALIDATION_ERROR: unsupported map document schema'; end if;
    if coalesce(p_snapshot->>'version','') !~ '^[0-9]+$' or (p_snapshot->>'version')::integer <> 1 then raise exception 'DOCUMENT_VALIDATION_ERROR: unsupported map document version'; end if;
    v_document := p_snapshot->'document';
    if jsonb_typeof(v_document) <> 'object' then raise exception 'DOCUMENT_VALIDATION_ERROR: missing map document'; end if;
    select * into v_map from public.maps where id=p_map_id and public.map_editor_can_access_v1(p_map_id) for update;
    if not found then raise exception 'map not found or not accessible'; end if;
    if v_document->>'id' <> p_map_id::text then raise exception 'IDENTITY_ERROR: snapshot map identity does not match requested map'; end if;
    if coalesce(v_document->>'mapType','') = '' or v_document->>'mapType' <> v_map.map_type::text then raise exception 'IDENTITY_ERROR: snapshot map type does not match map metadata'; end if;
    if coalesce(v_document->>'version','') !~ '^[0-9]+$' or (v_document->>'version')::integer <> 1 then raise exception 'DOCUMENT_VALIDATION_ERROR: unsupported document version'; end if;
    if coalesce(v_document->>'name','') = '' then raise exception 'DOCUMENT_VALIDATION_ERROR: map name is required'; end if;
    if v_document->>'width' !~ '^[0-9]+$' or (v_document->>'width')::integer <= 0 then raise exception 'DOCUMENT_VALIDATION_ERROR: map width must be a positive integer'; end if;
    if v_document->>'height' !~ '^[0-9]+$' or (v_document->>'height')::integer <= 0 then raise exception 'DOCUMENT_VALIDATION_ERROR: map height must be a positive integer'; end if;
    if v_document->>'tileSize' !~ '^[0-9]+$' or (v_document->>'tileSize')::integer <= 0 then raise exception 'DOCUMENT_VALIDATION_ERROR: tile size must be a positive integer'; end if;
    v_width := (v_document->>'width')::integer; v_height := (v_document->>'height')::integer;
    if jsonb_typeof(v_document->'layers') <> 'array' or jsonb_array_length(v_document->'layers')=0 then raise exception 'DOCUMENT_VALIDATION_ERROR: map must contain at least one layer'; end if;
    for v_layer in select value from jsonb_array_elements(v_document->'layers') loop
      if jsonb_typeof(v_layer) <> 'object' or jsonb_typeof(v_layer->'cells') <> 'array' then raise exception 'DOCUMENT_VALIDATION_ERROR: map layer cells are invalid'; end if;
      if jsonb_array_length(v_layer->'cells') <> v_width*v_height then raise exception 'DOCUMENT_VALIDATION_ERROR: layer cell count must equal width × height'; end if;
    end loop;
    select coalesce(max(mv.version_number),0) into v_current from public.map_versions mv where mv.map_id=p_map_id;
    if p_expected_version <> v_current then return query select 'conflict'::text,null::uuid,null::integer,v_current,'not_run'::text,null::text; return; end if;
    v_next := v_current+1;
    insert into public.map_versions(map_id,version_number,label,snapshot,created_by) values(p_map_id,v_next,coalesce(nullif(btrim(p_label),''),'merge'),p_snapshot,auth.uid()) returning id into v_version_id;
    update public.maps set updated_at=now() where id=p_map_id;
    begin perform public.map_editor_reconcile_after_merge_v1(p_map_id,v_version_id,p_snapshot); v_projection_status := 'committed'; exception when others then v_projection_status := 'failed'; v_projection_error := sqlerrm; end;
    return query select 'committed'::text,v_version_id,v_next,v_next,v_projection_status,v_projection_error;
  exception when unique_violation then return query select 'conflict'::text,null::uuid,null::integer,(select coalesce(max(mv.version_number),0) from public.map_versions mv where mv.map_id=p_map_id),'not_run'::text,null::text;
  end; $function$;


CREATE OR REPLACE FUNCTION public.map_editor_can_access_v1(p_map_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1
    from public.maps m
    where m.id = p_map_id
      and (
        m.created_by = auth.uid()
        or (m.map_type = 'world' and m.world_id = '3695d0b0-788e-42fa-9345-cc3197d0c94d'::uuid)
      )
  );
$function$;


CREATE OR REPLACE FUNCTION public.editor_map_identity_validate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare parent public.editor_map_identity%rowtype; legacy public.maps%rowtype;
begin
 if new.created_by is distinct from auth.uid() then raise exception using errcode='42501',message='EDITOR_MAP_OWNER_MISMATCH'; end if;
 if new.map_type='world' and new.parent_editor_map_id is not null then raise exception using errcode='23514',message='EDITOR_WORLD_PARENT_INVALID'; end if;
 if new.map_type<>'world' and new.parent_editor_map_id is null then raise exception using errcode='23514',message='EDITOR_PARENT_REQUIRED'; end if;
 if new.parent_editor_map_id is not null then
   select * into parent from public.editor_map_identity where editor_map_id=new.parent_editor_map_id;
   if not found then raise exception using errcode='23503',message='EDITOR_PARENT_NOT_FOUND'; end if;
   if parent.created_by is distinct from new.created_by and parent.map_type<>'world' then
     raise exception using errcode='42501',message='EDITOR_PARENT_OWNER_MISMATCH';
   end if;
   if parent.world_id is distinct from new.world_id then raise exception using errcode='23514',message='EDITOR_WORLD_SCOPE_MISMATCH'; end if;
   if new.map_type='region' and parent.map_type<>'world' then raise exception using errcode='23514',message='EDITOR_REGION_PARENT_INVALID'; end if;
   if new.map_type='playable' and parent.map_type<>'region' then raise exception using errcode='23514',message='EDITOR_PLAYABLE_PARENT_INVALID'; end if;
 end if;
 if new.legacy_map_id is not null then
   select * into legacy from public.maps where id=new.legacy_map_id;
   if not found then raise exception using errcode='23503',message='EDITOR_LEGACY_MAP_NOT_FOUND'; end if;
   if legacy.world_id is distinct from new.world_id then raise exception using errcode='23514',message='EDITOR_LEGACY_WORLD_SCOPE_MISMATCH'; end if;
   if new.map_type='world' and legacy.map_type<>'world' then raise exception using errcode='23514',message='EDITOR_WORLD_LEGACY_TYPE_INVALID'; end if;
   if new.map_type='playable' and legacy.map_type<>'exterior' then raise exception using errcode='23514',message='EDITOR_PLAYABLE_LEGACY_TYPE_INVALID'; end if;
   if new.map_type='region' then raise exception using errcode='23514',message='EDITOR_REGION_LEGACY_MAP_INVALID'; end if;
 end if;
 if tg_op='UPDATE' and new.parent_editor_map_id is not distinct from old.parent_editor_map_id and new.world_id is not distinct from old.world_id then return new; end if;
 if new.parent_editor_map_id is not null then
   if exists(with recursive ancestors(id) as (
      select new.parent_editor_map_id union all
      select e.parent_editor_map_id from public.editor_map_identity e join ancestors a on e.editor_map_id=a.id where e.parent_editor_map_id is not null)
      select 1 from ancestors where id=new.editor_map_id) then
     raise exception using errcode='23514',message='EDITOR_HIERARCHY_CYCLE';
   end if;
 end if;
 return new;
end $function$;


CREATE OR REPLACE FUNCTION public.editor_map_interior_validate_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  child public.editor_map_identity%rowtype;
  parent public.editor_map_identity%rowtype;
  legacy public.maps%rowtype;
begin
  select * into child from public.editor_map_identity where editor_map_id=new.editor_map_id;
  select * into parent from public.editor_map_identity where editor_map_id=new.playable_editor_map_id;

  if not found then raise exception using errcode='23503', message='EDITOR_INTERIOR_MAP_NOT_FOUND'; end if;
  if child.map_type <> 'playable' then raise exception using errcode='23514', message='EDITOR_INTERIOR_IDENTITY_TYPE_INVALID'; end if;
  if parent.map_type <> 'playable' then raise exception using errcode='23514', message='EDITOR_INTERIOR_PARENT_INVALID'; end if;
  if child.created_by is distinct from new.created_by or parent.created_by is distinct from new.created_by then
    raise exception using errcode='42501', message='EDITOR_INTERIOR_OWNER_MISMATCH';
  end if;
  if child.world_id is distinct from parent.world_id then
    raise exception using errcode='23514', message='EDITOR_INTERIOR_WORLD_SCOPE_MISMATCH';
  end if;

  if new.legacy_map_id is not null then
    select * into legacy from public.maps where id=new.legacy_map_id;
    if not found then raise exception using errcode='23503', message='EDITOR_INTERIOR_LEGACY_MAP_NOT_FOUND'; end if;
    if legacy.map_type <> 'interior' then raise exception using errcode='23514', message='EDITOR_INTERIOR_LEGACY_TYPE_INVALID'; end if;
    if legacy.world_id is distinct from child.world_id then raise exception using errcode='23514', message='EDITOR_INTERIOR_LEGACY_WORLD_SCOPE_MISMATCH'; end if;
    if legacy.building_id is null then raise exception using errcode='23514', message='EDITOR_INTERIOR_BUILDING_REQUIRED'; end if;
    if new.building_id is not null and new.building_id is distinct from legacy.building_id then
      raise exception using errcode='23514', message='EDITOR_INTERIOR_BUILDING_MISMATCH';
    end if;
  end if;

  if new.building_id is not null and new.legacy_map_id is null then
    perform 1 from public.buildings where id=new.building_id;
    if not found then raise exception using errcode='23503', message='EDITOR_BUILDING_NOT_FOUND'; end if;
  end if;

  return new;
end;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_bootstrap_world_identity_v1(p_legacy_map_id uuid)
 RETURNS TABLE(editor_map_id uuid, legacy_map_id uuid, world_id uuid, map_type text, parent_editor_map_id uuid, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m public.maps%rowtype; existing public.editor_map_identity%rowtype;
begin
 if auth.uid() is null then raise exception using errcode='42501',message='EDITOR_AUTH_REQUIRED'; end if;
 if not public.map_editor_can_access_v1(p_legacy_map_id) then raise exception using errcode='42501',message='EDITOR_MAP_NOT_ACCESSIBLE'; end if;
 select m0.* into m from public.maps m0 where m0.id=p_legacy_map_id;
 if not found then raise exception using errcode='P0002',message='EDITOR_MAP_NOT_FOUND'; end if;
 if m.map_type<>'world' then raise exception using errcode='23514',message='EDITOR_WORLD_LEGACY_TYPE_INVALID'; end if;
 select e.* into existing from public.editor_map_identity e where e.legacy_map_id=m.id;
 if found then
   if existing.map_type<>'world' or existing.parent_editor_map_id is not null or existing.world_id is distinct from m.world_id then
     raise exception using errcode='23514',message='EDITOR_WORLD_IDENTITY_INVALID';
   end if;
   return query select existing.editor_map_id,existing.legacy_map_id,existing.world_id,existing.map_type,existing.parent_editor_map_id,existing.created_by;
   return;
 end if;
 insert into public.editor_map_identity(editor_map_id,legacy_map_id,world_id,map_type,parent_editor_map_id,created_by)
 values(m.id,m.id,m.world_id,'world',null,auth.uid());
 return query select e.editor_map_id,e.legacy_map_id,e.world_id,e.map_type,e.parent_editor_map_id,e.created_by
 from public.editor_map_identity e where e.editor_map_id=m.id;
end $function$;


CREATE OR REPLACE FUNCTION public.map_editor_resolve_identity_v1(p_editor_map_id uuid)
 RETURNS TABLE(editor_map_id uuid, legacy_map_id uuid, world_id uuid, map_type text, parent_editor_map_id uuid, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception using errcode='42501', message='EDITOR_AUTH_REQUIRED';
  end if;

  return query
    select e.editor_map_id, e.legacy_map_id, e.world_id, e.map_type,
           e.parent_editor_map_id, e.created_by
    from public.editor_map_identity e
    where e.editor_map_id = p_editor_map_id
      and e.created_by = auth.uid();

  if not found then
    raise exception using errcode='42501', message='EDITOR_IDENTITY_NOT_ACCESSIBLE';
  end if;
end;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_create_child_v1(p_parent_editor_map_id uuid, p_map_type text, p_legacy_map_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(editor_map_id uuid, legacy_map_id uuid, world_id uuid, map_type text, parent_editor_map_id uuid, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_parent public.editor_map_identity%rowtype; v_legacy public.maps%rowtype; v_id uuid;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if p_map_type not in ('region','playable') then raise exception 'EDITOR_CHILD_TYPE_INVALID' using errcode='22023'; end if;
 if p_parent_editor_map_id is null then raise exception 'EDITOR_PARENT_REQUIRED' using errcode='22023'; end if;
 select e.* into v_parent from public.editor_map_identity e
 where e.editor_map_id=p_parent_editor_map_id
   and (e.map_type='world' or e.created_by=auth.uid())
 for update;
 if not found then raise exception 'EDITOR_PARENT_NOT_ACCESSIBLE' using errcode='42501'; end if;
 if (p_map_type='region' and v_parent.map_type<>'world') or (p_map_type='playable' and v_parent.map_type<>'region') then
   raise exception 'EDITOR_PARENT_TYPE_INVALID' using errcode='22023';
 end if;
 if p_legacy_map_id is not null then
   select m.* into v_legacy from public.maps m where m.id=p_legacy_map_id;
   if not found then raise exception 'LEGACY_MAP_NOT_FOUND' using errcode='P0002'; end if;
   if v_legacy.created_by<>auth.uid() then raise exception 'LEGACY_MAP_NOT_ACCESSIBLE' using errcode='42501'; end if;
   if v_legacy.world_id<>v_parent.world_id then raise exception 'LEGACY_MAP_WORLD_MISMATCH' using errcode='22023'; end if;
   if p_map_type='region' then raise exception 'REGION_CANNOT_MAP_LEGACY_MAP' using errcode='22023'; end if;
   if v_legacy.map_type<>'exterior' then raise exception 'PLAYABLE_LEGACY_MAP_TYPE_INVALID' using errcode='22023'; end if;
   if exists(select 1 from public.editor_map_identity e where e.legacy_map_id=p_legacy_map_id)
      or exists(select 1 from public.editor_map_interior i where i.legacy_map_id=p_legacy_map_id) then
      raise exception 'LEGACY_MAP_ALREADY_MAPPED' using errcode='23505';
   end if;
 end if;
 insert into public.editor_map_identity(editor_map_id,legacy_map_id,world_id,map_type,parent_editor_map_id,created_by)
 values(gen_random_uuid(),p_legacy_map_id,v_parent.world_id,p_map_type,p_parent_editor_map_id,auth.uid())
 returning public.editor_map_identity.editor_map_id into v_id;
 return query select e.editor_map_id,e.legacy_map_id,e.world_id,e.map_type,e.parent_editor_map_id,e.created_by
 from public.editor_map_identity e where e.editor_map_id=v_id;
end $function$;


CREATE OR REPLACE FUNCTION public.map_editor_create_interior_v1(p_playable_editor_map_id uuid, p_legacy_map_id uuid DEFAULT NULL::uuid, p_building_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(editor_map_id uuid, playable_editor_map_id uuid, legacy_map_id uuid, building_id uuid, world_id uuid, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_parent public.editor_map_identity%rowtype;
  v_legacy public.maps%rowtype;
  v_id uuid;
  v_building uuid;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select e.* into v_parent
  from public.editor_map_identity e
  where e.editor_map_id = p_playable_editor_map_id
    and e.created_by = auth.uid()
  for update;

  if not found then raise exception 'PLAYABLE_PARENT_NOT_ACCESSIBLE' using errcode='42501'; end if;
  if v_parent.map_type <> 'playable' then raise exception 'INTERIOR_PARENT_TYPE_INVALID' using errcode='22023'; end if;

  if p_legacy_map_id is not null then
    select m.* into v_legacy from public.maps m where m.id = p_legacy_map_id;
    if not found then raise exception 'LEGACY_INTERIOR_MAP_NOT_FOUND' using errcode='P0002'; end if;
    if v_legacy.created_by <> auth.uid() then raise exception 'LEGACY_INTERIOR_MAP_NOT_ACCESSIBLE' using errcode='42501'; end if;
    if v_legacy.world_id <> v_parent.world_id then raise exception 'LEGACY_INTERIOR_WORLD_MISMATCH' using errcode='22023'; end if;
    if v_legacy.map_type <> 'interior' or v_legacy.building_id is null then raise exception 'LEGACY_INTERIOR_CONTRACT_INVALID' using errcode='22023'; end if;
    if exists (
      select 1 from public.editor_map_identity e
      where e.legacy_map_id = p_legacy_map_id
    ) or exists (
      select 1 from public.editor_map_interior i
      where i.legacy_map_id = p_legacy_map_id
    ) then
      raise exception 'LEGACY_MAP_ALREADY_MAPPED' using errcode='23505';
    end if;
    v_building := v_legacy.building_id;
    if p_building_id is not null and p_building_id <> v_building then raise exception 'BUILDING_MISMATCH' using errcode='22023'; end if;
  else
    v_building := p_building_id;
    if v_building is not null then
      if not exists(select 1 from public.buildings b where b.id = v_building) then raise exception 'BUILDING_NOT_FOUND' using errcode='P0002'; end if;
    end if;
  end if;

  insert into public.editor_map_identity(
    editor_map_id, legacy_map_id, world_id, map_type, parent_editor_map_id, created_by
  )
  values (
    gen_random_uuid(), null, v_parent.world_id, 'playable',
    p_playable_editor_map_id, auth.uid()
  )
  returning public.editor_map_identity.editor_map_id into v_id;

  insert into public.editor_map_interior(
    editor_map_id, playable_editor_map_id, legacy_map_id, building_id, created_by
  )
  values (v_id, p_playable_editor_map_id, p_legacy_map_id, v_building, auth.uid());

  return query
    select i.editor_map_id, i.playable_editor_map_id, i.legacy_map_id,
           i.building_id, e.world_id, i.created_by
    from public.editor_map_interior i
    join public.editor_map_identity e on e.editor_map_id = i.editor_map_id
    where i.editor_map_id = v_id;
end;
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_load_identity_snapshot_v1(p_editor_map_id uuid)
 RETURNS TABLE(ok boolean, code text, editor_map_id uuid, version_id uuid, version_number integer, snapshot jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  identity_row public.editor_map_identity%rowtype;
  version_row public.editor_map_versions%rowtype;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;

  select e.*
    into identity_row
  from public.editor_map_identity e
  where e.editor_map_id = p_editor_map_id
    and e.created_by = auth.uid();

  if not found then raise exception 'EDITOR_IDENTITY_NOT_ACCESSIBLE'; end if;

  select ev.*
    into version_row
  from public.editor_map_versions ev
  where ev.editor_map_id = p_editor_map_id
  order by ev.version_number desc
  limit 1;

  if not found then
    return query
      select true, 'NO_SNAPSHOT'::text, identity_row.editor_map_id, null::uuid, 0, null::jsonb, null::timestamptz;
    return;
  end if;

  return query
    select true, 'OK'::text, version_row.editor_map_id, version_row.id, version_row.version_number, version_row.snapshot, version_row.created_at;
end
$function$;


CREATE OR REPLACE FUNCTION public.map_editor_commit_identity_v1(p_editor_map_id uuid, p_expected_version integer, p_snapshot jsonb, p_label text DEFAULT 'map-editor-save'::text)
 RETURNS TABLE(status text, version_id uuid, version_number integer, current_version integer, projection_status text, projection_error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.editor_map_identity%rowtype; cur integer; nextv integer; vid uuid;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if p_expected_version is null or p_expected_version < 0 then raise exception 'INVALID_EXPECTED_VERSION'; end if;
 if p_snapshot is null or jsonb_typeof(p_snapshot) <> 'object' then raise exception 'INVALID_SNAPSHOT'; end if;
 select e.* into r from public.editor_map_identity e where e.editor_map_id=p_editor_map_id and e.created_by=auth.uid() for update;
 if not found then raise exception 'EDITOR_IDENTITY_NOT_ACCESSIBLE'; end if;
 select coalesce(max(v.version_number),0) into cur from public.editor_map_versions v where v.editor_map_id=p_editor_map_id;
 if p_expected_version <> cur then return query select 'conflict',null::uuid,null::integer,cur,'not_run',null::text; return; end if;
 nextv:=cur+1;
 insert into public.editor_map_versions(editor_map_id,version_number,label,snapshot,created_by)
 values(p_editor_map_id,nextv,coalesce(nullif(trim(p_label),''),'map-editor-save'),p_snapshot,auth.uid())
 returning id into vid;
 return query select 'committed',vid,nextv,nextv,'not_run',null::text;
exception when unique_violation then
 select coalesce(max(v.version_number),0) into cur from public.editor_map_versions v where v.editor_map_id=p_editor_map_id;
 return query select 'conflict',null::uuid,null::integer,cur,'not_run',null::text;
end $function$;


CREATE OR REPLACE FUNCTION public.claim_vandrith_legacy_save_slots_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  uid uuid := auth.uid();
  map_ids uuid[];
  slot_count integer := 0;
  version_count integer := 0;
  identity_count integer := 0;
  username text;
begin
  if uid is null then
    return jsonb_build_object('ok',false,'code','AUTH_REQUIRED');
  end if;

  select coalesce(
    nullif(trim(u.raw_user_meta_data->>'username'),''),
    split_part(u.email,'@',1)
  )
  into username
  from auth.users u
  where u.id = uid;

  if lower(coalesce(username,'')) <> 'raka775' then
    return jsonb_build_object('ok',false,'code','NOT_LEGACY_OWNER');
  end if;

  select coalesce(array_agg(distinct s.map_id), '{}')
    into map_ids
  from public.map_editor_save_slots s
  where s.slot_number in (1,2,3);

  update public.maps m
  set created_by = uid, updated_at = now()
  where m.id = any(map_ids);

  update public.map_versions mv
  set created_by = uid
  where mv.map_id = any(map_ids);
  get diagnostics version_count = row_count;

  update public.map_editor_save_slots s
  set created_by = uid, updated_at = now()
  where s.map_id = any(map_ids);
  get diagnostics slot_count = row_count;

  update public.editor_map_identity e
  set created_by = uid, updated_at = now()
  where e.legacy_map_id = any(map_ids)
     or e.editor_map_id in (
       select emi.playable_editor_map_id
       from public.editor_map_interior emi
       where emi.legacy_map_id = any(map_ids)
     );
  get diagnostics identity_count = row_count;

  update public.editor_map_versions ev
  set created_by = uid
  where ev.editor_map_id in (
    select e.editor_map_id
    from public.editor_map_identity e
    where e.created_by = uid
  );

  return jsonb_build_object(
    'ok',true,
    'code','CLAIMED',
    'slot_count',slot_count,
    'map_version_count',version_count,
    'identity_count',identity_count
  );
end
$function$;
SET check_function_bodies = true;


CREATE OR REPLACE FUNCTION public.apply_runtime_environment_consequence_v1(p_world_id uuid, p_season_key text DEFAULT NULL::text, p_weather_key text DEFAULT NULL::text, p_weather_intensity smallint DEFAULT NULL::smallint, p_conditions jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare current_state public.world_environment_states%rowtype; current_clock public.world_environment_clocks%rowtype; season_id uuid; weather_id uuid; weather_state_id uuid; now_at timestamptz := now(); next_conditions jsonb;
begin
if p_season_key is null and p_weather_key is null and p_conditions is null then raise exception 'Environment consequence must specify season_key, weather_key, or conditions.'; end if;
if p_weather_intensity is not null and (p_weather_intensity < 0 or p_weather_intensity > 5) then raise exception 'Environment consequence weather_intensity must be between 0 and 5.'; end if;
select * into current_clock from public.world_environment_clocks where world_id=p_world_id for update;
select * into current_state from public.world_environment_states where world_id=p_world_id for update;
season_id:=current_state.season_id;
if p_season_key is not null then select id into season_id from public.season_definitions where season_key=p_season_key; if season_id is null then raise exception 'Unknown season_key: %',p_season_key; end if;
elsif season_id is null then season_id:=current_clock.current_season_id; end if;
if p_weather_key is not null then
select id into weather_id from public.weather_definitions where weather_key=p_weather_key;
if weather_id is null then raise exception 'Unknown weather_key: %',p_weather_key; end if;
if season_id is null then raise exception 'Weather consequence requires a resolved season.'; end if;
if current_state.weather_state_id is not null then update public.world_weather_states set ends_at=now_at,updated_at=now_at where id=current_state.weather_state_id and ends_at is null; end if;
insert into public.world_weather_states(world_id,weather_id,season_id,started_at,ends_at,intensity,conditions,updated_at) values(p_world_id,weather_id,season_id,now_at,null,coalesce(p_weather_intensity,0),'{}'::jsonb,now_at) returning id into weather_state_id;
else weather_state_id:=current_state.weather_state_id; end if;
next_conditions:=case when p_conditions is null then coalesce(current_state.conditions,'{}'::jsonb) else p_conditions end;
insert into public.world_environment_states(world_id,season_id,weather_state_id,state_started_at,state_ends_at,conditions,updated_at) values(p_world_id,season_id,weather_state_id,now_at,null,next_conditions,now_at)
on conflict(world_id) do update set season_id=excluded.season_id,weather_state_id=excluded.weather_state_id,state_started_at=excluded.state_started_at,state_ends_at=excluded.state_ends_at,conditions=excluded.conditions,updated_at=excluded.updated_at;
if current_clock.world_id is not null then update public.world_environment_clocks set current_season_id=coalesce(season_id,current_season_id),updated_at=now_at where world_id=p_world_id; end if;
return jsonb_build_object('seasonKey',p_season_key,'weatherKey',p_weather_key,'weatherIntensity',p_weather_intensity,'conditions',next_conditions);
end; $function$;


CREATE OR REPLACE VIEW "public"."asset_library_inventory_v1" AS
 SELECT a.id,
    a.external_key,
    a.name,
    a.slug,
    a.category,
    a.placement_category,
    a.role,
    a.asset_path,
    a.preview_path,
    a.grid_width,
    a.grid_height,
    a.tile_width,
    a.tile_height,
    a.perspective,
    a.palette_family,
    a.outline_style,
    a.lighting_direction,
    a.season_capable,
    a.autotile_capable,
    a.collision_capable,
    a.interactable,
    a.status AS asset_status,
    a.metadata AS asset_metadata,
    s.id AS source_id,
    s.name AS source_name,
    s.slug AS source_slug,
    s.source_url,
    s.repository_url,
    s.version AS source_version,
    s.audit_status AS source_audit_status,
    l.id AS license_registry_id,
    l.licenses,
    l.attribution_required,
    l.attribution_text,
    l.commercial_use_allowed,
    l.modification_allowed,
    l.redistribution_allowed,
    l.verification_status AS license_verification_status,
    l.usage_status AS license_usage_status
   FROM ((asset_registry a
     JOIN asset_sources s ON ((s.id = a.source_id)))
     LEFT JOIN asset_license_registry l ON ((l.id = a.license_registry_id)));;
CREATE OR REPLACE VIEW "public"."vandrith_asset_binding_workbench" AS
 SELECT c.id AS candidate_id,
    c.asset_id,
    c.terrain_type_id,
    t.terrain_key,
    c.transition_type,
    c.neighbor_mask,
    c.season,
    c.candidate_status,
    c.reviewer_note,
    a.status AS asset_status,
    a.asset_path,
    a.category,
    a.role,
    a.autotile_capable,
    a.season_capable,
    a.license_registry_id,
    (c.evidence -> 'tile_region'::text) AS tile_region,
    (c.evidence ->> 'tileset_id'::text) AS tileset_id
   FROM ((asset_binding_candidates c
     LEFT JOIN terrain_types t ON ((t.id = c.terrain_type_id)))
     JOIN asset_registry a ON ((a.id = c.asset_id)));;
CREATE OR REPLACE VIEW "public"."vandrith_autotile_rule_status" AS
 SELECT t.terrain_key,
    t.name,
    p.profile_key,
    p.topology,
    p.neighborhood,
    (count(r.id))::integer AS rule_count,
    (count(r.id) FILTER (WHERE (r.asset_id IS NOT NULL)))::integer AS bound_asset_rules,
    (count(r.id) FILTER (WHERE (r.season = 'spring'::text)))::integer AS spring_rules,
    (count(r.id) FILTER (WHERE (r.season = 'summer'::text)))::integer AS summer_rules,
    (count(r.id) FILTER (WHERE (r.season = 'autumn'::text)))::integer AS autumn_rules,
    (count(r.id) FILTER (WHERE (r.season = 'winter'::text)))::integer AS winter_rules
   FROM (((terrain_types t
     JOIN terrain_type_profiles tp ON ((tp.terrain_type_id = t.id)))
     JOIN terrain_autotile_profiles p ON ((p.id = tp.profile_id)))
     LEFT JOIN terrain_transition_rules r ON ((r.terrain_type_id = t.id)))
  GROUP BY t.id, t.terrain_key, t.name, p.id, p.profile_key, p.topology, p.neighborhood;;
CREATE OR REPLACE VIEW "public"."vandrith_building_assembly_status" AS
 SELECT id,
    spec_key,
    name,
    building_type,
    min_width,
    min_height,
    max_width,
    max_height,
    season_capable,
    (( SELECT count(*) AS count
           FROM building_assembly_rules r
          WHERE (r.spec_id = s.id)))::integer AS rule_count,
    (( SELECT count(*) AS count
           FROM building_assembly_constraints c
          WHERE (c.spec_id = s.id)))::integer AS constraint_count,
    (( SELECT count(*) AS count
           FROM (building_assembly_rules r
             JOIN building_kit_roles k ON ((k.id = r.role_id)))
          WHERE ((r.spec_id = s.id) AND (r.required = true))))::integer AS required_role_count
   FROM building_assembly_specs s
  WHERE (enabled = true);;
CREATE OR REPLACE VIEW "public"."vandrith_building_instance_status" AS
 SELECT b.id,
    b.name,
    s.spec_key,
    b.width,
    b.height,
    b.season,
    b.status,
    b.validation_status,
    jsonb_array_length(b.validation_errors) AS error_count,
    jsonb_array_length(b.validation_warnings) AS warning_count,
    (count(c.id))::integer AS component_count,
    (count(c.id) FILTER (WHERE (a.status = 'approved'::text)))::integer AS approved_component_count
   FROM (((building_instances b
     JOIN building_assembly_specs s ON ((s.id = b.spec_id)))
     LEFT JOIN building_instance_components c ON ((c.building_id = b.id)))
     LEFT JOIN asset_registry a ON ((a.id = c.asset_id)))
  GROUP BY b.id, s.spec_key;;
CREATE OR REPLACE VIEW "public"."vandrith_building_kit_status" AS
 SELECT r.role_key,
    r.category,
    r.required,
    r.socket_type,
    (count(b.id))::integer AS binding_count,
    (count(b.id) FILTER (WHERE (b.binding_status = 'approved'::text)))::integer AS approved_count,
    (count(b.id) FILTER (WHERE (b.binding_status = 'pending'::text)))::integer AS pending_count,
    (count(b.id) FILTER (WHERE (b.binding_status = 'blocked'::text)))::integer AS blocked_count
   FROM (building_kit_roles r
     LEFT JOIN building_kit_bindings b ON ((b.role_id = r.id)))
  WHERE (r.enabled = true)
  GROUP BY r.id
  ORDER BY r.category, r.role_key;;
CREATE OR REPLACE VIEW "public"."vandrith_dungeon_connection_validation" AS
 SELECT id AS connection_id,
    map_id,
    status,
    validate_dungeon_room_connection(id) AS validation
   FROM dungeon_connections c;;
CREATE OR REPLACE VIEW "public"."vandrith_dungeon_connections" AS
 SELECT c.id,
    c.map_id,
    c.from_room_id,
    c.to_room_id,
    c.from_side,
    c.to_side,
    c.from_x,
    c.from_y,
    c.to_x,
    c.to_y,
    c.opening_width,
    c.corridor_id,
    c.status,
    c.metadata,
    c.created_at,
    c.updated_at,
    fr.floor_type AS from_floor_type,
    fr.wall_type AS from_wall_type,
    tr.floor_type AS to_floor_type,
    tr.wall_type AS to_wall_type,
    co.status AS corridor_status
   FROM (((dungeon_connections c
     JOIN dungeon_rooms fr ON ((fr.id = c.from_room_id)))
     JOIN dungeon_rooms tr ON ((tr.id = c.to_room_id)))
     LEFT JOIN dungeon_corridors co ON ((co.id = c.corridor_id)));;
CREATE OR REPLACE VIEW "public"."vandrith_dungeon_openings" AS
 SELECT o.id,
    o.map_id,
    o.room_id,
    o.corridor_id,
    o.x,
    o.y,
    o.opening_type,
    o.direction,
    o.width,
    o.is_walkable,
    o.blocks_when_closed,
    o.state,
    o.asset_id,
    o.metadata,
    o.created_at,
    o.updated_at,
    r.floor_type AS room_floor_type,
    r.wall_type AS room_wall_type,
    c.status AS corridor_status
   FROM ((dungeon_openings o
     LEFT JOIN dungeon_rooms r ON ((r.id = o.room_id)))
     LEFT JOIN dungeon_corridors c ON ((c.id = o.corridor_id)));;
CREATE OR REPLACE VIEW "public"."vandrith_dungeon_pathfinding_runs" AS
 SELECT id,
    map_id,
    connection_id,
    algorithm,
    status,
    start_x,
    start_y,
    goal_x,
    goal_y,
    path,
    cost,
    nodes_expanded,
    blocked_cells,
    metadata,
    created_at,
    updated_at
   FROM dungeon_pathfinding_runs;;
CREATE OR REPLACE VIEW "public"."vandrith_dungeon_topology_status" AS
 SELECT p.profile_key,
    p.topology,
    p.neighborhood,
    (count(r.id))::integer AS rule_count,
    (count(r.id) FILTER (WHERE (r.confidence = 'verified'::text)))::integer AS verified_rules,
    (count(r.id) FILTER (WHERE (r.confidence = 'inferred'::text)))::integer AS inferred_rules,
    (count(r.id) FILTER (WHERE (r.asset_id IS NOT NULL)))::integer AS bound_assets
   FROM (dungeon_structural_profiles p
     LEFT JOIN dungeon_structural_rules r ON ((r.profile_id = p.id)))
  GROUP BY p.id, p.profile_key, p.topology, p.neighborhood;;
CREATE OR REPLACE VIEW "public"."vandrith_editor_batch_mutation_leaves" AS
 SELECT 'duplicate'::text AS operation,
    'editor_batch_duplicate_leaf_v1'::text AS leaf
UNION ALL
 SELECT 'transform'::text AS operation,
    'editor_batch_transform_leaf_v1'::text AS leaf
UNION ALL
 SELECT 'delete'::text AS operation,
    'editor_batch_delete_leaf_v1'::text AS leaf;;
CREATE OR REPLACE VIEW "public"."vandrith_editor_direct_write_audit_v3" AS
 SELECT p.proname AS function_name,
    pg_get_function_identity_arguments(p.oid) AS args,
        CASE
            WHEN (p.proname = ANY (ARRAY['editor_create_object_leaf_v1'::name, 'editor_place_object_leaf_v2'::name, 'editor_duplicate_object_leaf_v2'::name, 'editor_paste_leaf_v2'::name, 'execute_map_editor_command'::name, 'editor_delete_object_leaf_v1'::name, 'editor_batch_selection_duplicate_leaf_v2'::name, 'editor_batch_selection_transform_leaf_v2'::name, 'commit_map_object_geometry_pipeline_v1'::name, 'transform_map_object_gizmo_safe'::name, 'transform_selected_gizmo_atomic'::name])) THEN 'APPROVED_MUTATION_PATH'::text
            ELSE 'REVIEW'::text
        END AS classification
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = 'public'::name) AND (p.prosrc ~~* '%map_objects%'::text) AND ((p.prosrc ~~* '%insert into public.map_objects%'::text) OR (p.prosrc ~~* '%update public.map_objects%'::text) OR (p.prosrc ~~* '%delete from public.map_objects%'::text)))
  ORDER BY
        CASE
            WHEN (p.proname = ANY (ARRAY['editor_create_object_leaf_v1'::name, 'editor_place_object_leaf_v2'::name, 'editor_duplicate_object_leaf_v2'::name, 'editor_paste_leaf_v2'::name, 'execute_map_editor_command'::name, 'editor_delete_object_leaf_v1'::name, 'editor_batch_selection_duplicate_leaf_v2'::name, 'editor_batch_selection_transform_leaf_v2'::name, 'commit_map_object_geometry_pipeline_v1'::name, 'transform_map_object_gizmo_safe'::name, 'transform_selected_gizmo_atomic'::name])) THEN 'APPROVED_MUTATION_PATH'::text
            ELSE 'REVIEW'::text
        END, p.proname;;
CREATE OR REPLACE VIEW "public"."vandrith_editor_final_bypass_audit" AS
 WITH funcs AS (
         SELECT p.oid,
            n.nspname,
            p.proname,
            pg_get_function_identity_arguments(p.oid) AS args,
            p.prosrc
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE (n.nspname = 'public'::name)
        ), classified AS (
         SELECT funcs.proname AS function_name,
            funcs.args,
                CASE
                    WHEN (funcs.proname = ANY (ARRAY['editor_create_object_leaf_v1'::name, 'editor_delete_object_leaf_v1'::name, 'editor_transform_object_leaf_v1'::name, 'editor_batch_duplicate_leaf_v1'::name, 'editor_batch_transform_leaf_v1'::name, 'editor_batch_delete_leaf_v1'::name, 'execute_map_editor_command'::name])) THEN 'APPROVED_MUTATION_LEAF'::text
                    WHEN (funcs.proname = 'editor_mutation_gateway_v1'::name) THEN 'GATEWAY'::text
                    WHEN ((funcs.prosrc ~~* '%insert into public.map_objects%'::text) OR (funcs.prosrc ~~* '%insert into map_objects%'::text)) THEN 'DIRECT_INSERT_BYPASS'::text
                    WHEN ((funcs.prosrc ~~* '%update public.map_objects%'::text) OR (funcs.prosrc ~~* '%update map_objects%'::text)) THEN 'DIRECT_UPDATE_BYPASS'::text
                    WHEN ((funcs.prosrc ~~* '%delete from public.map_objects%'::text) OR (funcs.prosrc ~~* '%delete from map_objects%'::text)) THEN 'DIRECT_DELETE_BYPASS'::text
                    ELSE 'NO_DIRECT_MAP_OBJECT_MUTATION'::text
                END AS mutation_path
           FROM funcs
          WHERE (funcs.prosrc ~~* '%map_objects%'::text)
        )
 SELECT function_name,
    args,
    mutation_path
   FROM classified;;
CREATE OR REPLACE VIEW "public"."vandrith_editor_geometry_pipeline" AS
 SELECT o.id,
    o.map_id,
    o.layer_id,
    o.x,
    o.y,
    o.rotation,
    o.scale_x,
    o.scale_y,
    COALESCE(g.geometry_type, 'obb'::text) AS geometry_type,
    g.center_x,
    g.center_y,
    g.half_width,
    g.half_height
   FROM (map_objects o
     LEFT JOIN map_object_geometry g ON ((g.object_id = o.id)));;
CREATE OR REPLACE VIEW "public"."vandrith_editor_legacy_bridge_status" AS
 SELECT operation,
    bridge_function,
    target
   FROM ( VALUES ('place'::text,'editor_place_object_legacy_bridge_v1'::text,'gateway'::text), ('duplicate'::text,'editor_duplicate_legacy_bridge_v1'::text,'gateway'::text), ('duplicate_selection'::text,'editor_duplicate_selection_legacy_bridge_v1'::text,'gateway'::text), ('paste'::text,'editor_paste_legacy_bridge_v1'::text,'gateway'::text)) v(operation, bridge_function, target);;
CREATE OR REPLACE VIEW "public"."vandrith_editor_legacy_bypass_audit" AS
 SELECT p.proname AS function_name,
    pg_get_function_identity_arguments(p.oid) AS arguments,
        CASE
            WHEN (p.prosrc ~~* '%insert into public.map_objects%'::text) THEN 'DIRECT_INSERT'::text
            WHEN (p.prosrc ~~* '%update public.map_objects%'::text) THEN 'DIRECT_UPDATE'::text
            WHEN (p.prosrc ~~* '%delete from public.map_objects%'::text) THEN 'DIRECT_DELETE'::text
            ELSE 'INDIRECT'::text
        END AS write_mode,
        CASE
            WHEN (p.proname = ANY (ARRAY['create_map_object'::name, 'delete_map_object'::name, 'delete_map_object_safe'::name, 'duplicate_map_object_unified'::name, 'duplicate_selected_map_objects_atomic'::name, 'paste_map_editor_clipboard_atomic'::name, 'place_map_object_unified'::name, 'transform_selected_gizmo_atomic'::name, 'transform_map_object_gizmo_safe'::name, 'transform_selected_map_objects_atomic'::name, 'commit_map_object_geometry_pipeline_v1'::name, 'set_map_object_transform'::name, 'set_map_object_transform_safe'::name, 'rotate_map_object_safe'::name])) THEN 'EDITOR_PATH'::text
            ELSE 'REVIEW'::text
        END AS classification
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = 'public'::name) AND (p.prosrc ~~* '%map_objects%'::text));;
CREATE OR REPLACE VIEW "public"."vandrith_editor_mutation_contract_v2" AS
 SELECT operation,
    'editor_mutation_gateway_v1'::text AS gateway,
        CASE operation
            WHEN 'create'::text THEN 'editor_create_object_leaf_v1'::text
            WHEN 'delete'::text THEN 'editor_delete_object_leaf_v1'::text
            WHEN 'move'::text THEN 'editor_transform_object_leaf_v1'::text
            WHEN 'rotate'::text THEN 'editor_transform_object_leaf_v1'::text
            WHEN 'scale'::text THEN 'editor_transform_object_leaf_v1'::text
            WHEN 'duplicate'::text THEN 'editor_batch_duplicate_leaf_v1'::text
            WHEN 'transform_selection'::text THEN 'editor_batch_transform_leaf_v1'::text
            ELSE 'editor_mutation_gateway_v1'::text
        END AS mutation_leaf
   FROM ( VALUES ('create'::text), ('move'::text), ('rotate'::text), ('scale'::text), ('delete'::text), ('duplicate'::text), ('transform_selection'::text), ('paste'::text), ('gizmo_rotate'::text), ('gizmo_scale'::text)) v(operation);;
CREATE OR REPLACE VIEW "public"."vandrith_editor_mutation_gateway" AS
 SELECT operation,
    'editor_mutation_gateway_v1'::text AS gateway
   FROM ( VALUES ('create'::text), ('move'::text), ('rotate'::text), ('scale'::text), ('delete'::text), ('duplicate'::text), ('duplicate_selection'::text), ('paste'::text), ('transform_selection'::text), ('gizmo_selection_rotate'::text), ('gizmo_selection_scale'::text)) v(operation);;
CREATE OR REPLACE VIEW "public"."vandrith_editor_mutation_leaf_audit" AS
 SELECT p.proname AS function_name,
    pg_get_function_identity_arguments(p.oid) AS args,
        CASE
            WHEN ((p.prosrc ~~* '%insert into public.map_objects%'::text) OR (p.prosrc ~~* '%update public.map_objects%'::text) OR (p.prosrc ~~* '%delete from public.map_objects%'::text)) THEN 'DIRECT_LEAF_OR_LEGACY'::text
            ELSE 'NO_DIRECT_OBJECT_MUTATION'::text
        END AS mutation_class
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = 'public'::name) AND (p.proname ~~ 'editor_%'::text))
  ORDER BY p.proname;;
CREATE OR REPLACE VIEW "public"."vandrith_editor_selection_mutation_status" AS
 SELECT operation,
    leaf_function
   FROM ( VALUES ('duplicate_selection'::text,'editor_batch_selection_duplicate_leaf_v2'::text), ('transform_selection'::text,'editor_batch_selection_transform_leaf_v2'::text)) v(operation, leaf_function);;
CREATE OR REPLACE VIEW "public"."vandrith_environment_runtime_read_contract" AS
 SELECT c.world_id,
    c.simulation_at,
    c.speed_multiplier,
    s.season_key AS current_season_key,
    c.season_started_at,
    c.season_ends_at,
    w.weather_key,
    ws_season.season_key AS weather_season_key,
    ws.started_at AS weather_started_at,
    ws.ends_at AS weather_ends_at,
    ws.intensity AS weather_intensity,
    ws.seed AS weather_seed,
    ws.conditions AS weather_conditions,
    e.state_started_at,
    e.state_ends_at,
    e.conditions AS state_conditions
   FROM (((((world_environment_clocks c
     LEFT JOIN season_definitions s ON ((s.id = c.current_season_id)))
     LEFT JOIN world_environment_states e ON ((e.world_id = c.world_id)))
     LEFT JOIN world_weather_states ws ON ((ws.id = e.weather_state_id)))
     LEFT JOIN season_definitions ws_season ON ((ws_season.id = ws.season_id)))
     LEFT JOIN weather_definitions w ON ((w.id = ws.weather_id)));;
COMMENT ON VIEW "public"."vandrith_environment_runtime_read_contract" IS 'Trusted server-side read contract for Map Editor. Exposes normalized clock, season, weather, and environment state. Direct browser access is revoked.';
CREATE OR REPLACE VIEW "public"."vandrith_layer_aware_objects" AS
 SELECT o.id,
    o.map_id,
    o.layer_id,
    o.asset_id,
    o.entity_type,
    o.entity_id,
    o.x,
    o.y,
    o.rotation,
    o.scale_x,
    o.scale_y,
    o.z_index,
    o.collision_enabled,
    o.interactable,
    o.footprint,
    o.properties,
    o.created_at,
    o.updated_at,
    o.object_type,
    o.width,
    o.height,
    o.blocks_los,
    COALESCE(r.selectable, true) AS layer_selectable,
    COALESCE(r.editable, true) AS layer_editable,
    COALESCE(r.snap_enabled, true) AS layer_snap_enabled,
    COALESCE(r.collision_enabled, true) AS layer_collision_enabled,
    COALESCE(r.visible, true) AS layer_visible
   FROM (map_objects o
     LEFT JOIN map_editor_layer_rules r ON (((r.map_id = o.map_id) AND (r.layer_id = o.layer_id))));;
CREATE OR REPLACE VIEW "public"."vandrith_map_cell_status" AS
 SELECT m.id AS map_id,
    m.name,
    m.map_type,
    m.width,
    m.height,
    m.tile_size,
    (count(c.id))::integer AS cell_count,
    (count(c.id) FILTER (WHERE (c.terrain_asset_id IS NOT NULL)))::integer AS terrain_cells,
    (count(c.id) FILTER (WHERE (c.structural_asset_id IS NOT NULL)))::integer AS structural_cells,
    (count(c.id) FILTER (WHERE (c.decoration_asset_id IS NOT NULL)))::integer AS decoration_cells,
    (count(c.id) FILTER (WHERE c.collision))::integer AS collision_cells,
    (count(c.id) FILTER (WHERE (NOT c.walkable)))::integer AS blocked_cells
   FROM (maps m
     LEFT JOIN map_cells c ON ((c.map_id = m.id)))
  GROUP BY m.id, m.name, m.map_type, m.width, m.height, m.tile_size;;
CREATE OR REPLACE VIEW "public"."vandrith_map_coordinate_status" AS
 SELECT m.id AS map_id,
    m.name,
    m.map_type,
    m.coordinate_mode,
    m.width,
    m.height,
    m.tile_size,
    p.map_type AS profile_type,
    p.coordinate_mode AS profile_coordinate_mode,
    p.grid_unit,
    p.snap_mode,
    p.min_zoom,
    p.max_zoom,
    p.default_zoom,
    p.camera_mode,
    p.allow_rotation,
    (m.coordinate_profile_id IS NOT NULL) AS profile_bound
   FROM (maps m
     LEFT JOIN map_coordinate_profiles p ON ((p.id = m.coordinate_profile_id)));;
