    o.collision_enabled
   FROM (map_editor_selections s
     JOIN map_objects o ON ((o.id = s.entity_id)))
  WHERE (s.entity_type = 'map_object'::text);;
CREATE OR REPLACE VIEW "public"."vandrith_map_editor_selection" AS
 SELECT s.id,
