    o.z_index
   FROM (map_editor_selections s
     LEFT JOIN map_objects o ON (((s.entity_type = 'map_object'::text) AND (o.id = s.entity_id))));;
CREATE OR REPLACE VIEW "public"."vandrith_map_editor_snap_settings" AS
 SELECT map_id,
    grid_size,
    grid_enabled,
    object_snap_enabled,
    edge_snap_enabled,
