CREATE OR REPLACE VIEW "public"."vandrith_map_editor_structure" AS
 SELECT m.id AS map_id,
    m.name,
    m.map_type,
    m.coordinate_mode,
    m.width,
    m.height,
    m.tile_size,
    (count(DISTINCT l.id))::integer AS layer_count,
    (count(DISTINCT p.id))::integer AS building_count,
    (count(DISTINCT o.id))::integer AS occupied_cell_count
   FROM (((maps m
     LEFT JOIN map_layers l ON ((l.map_id = m.id)))
     LEFT JOIN map_building_placements p ON ((p.map_id = m.id)))
     LEFT JOIN map_occupancy_cells o ON ((o.map_id = m.id)))
  GROUP BY m.id, m.name, m.map_type, m.coordinate_mode, m.width, m.height, m.tile_size;;
CREATE OR REPLACE VIEW "public"."vandrith_map_editor_transform_groups" AS
 SELECT id,
