    (metadata -> 'commands'::text) AS transform_commands
   FROM map_editor_command_groups g
  WHERE (label = 'Multi-object transform'::text);;
CREATE OR REPLACE VIEW "public"."vandrith_map_navigation_grid" AS
 SELECT map_id,
    x,
    y,
    cell_type,
    walkable,
