   FROM map_navigation_cells;;
CREATE OR REPLACE VIEW "public"."vandrith_map_object_geometry" AS
 SELECT o.id,
    o.map_id,
    o.layer_id,
    o.x,
    o.y,
    o.rotation,
    o.scale_x,
    o.scale_y,
    o.width,
    o.height,
    g.geometry_type,
    g.center_x,
    g.center_y,
    g.half_width,
    g.half_height,
    g.rotation AS geometry_rotation,
    obb_aabb_v1(g.center_x, g.center_y, g.half_width, g.half_height, g.rotation) AS aabb
   FROM (map_objects o
     LEFT JOIN map_object_geometry g ON ((g.object_id = o.id)));;
CREATE OR REPLACE VIEW "public"."vandrith_map_object_geometry_v2" AS
 SELECT id AS object_id,
    map_id,
    x,
    y,
    rotation,
    scale_x,
    scale_y,
    width,
    height,
    x AS min_x,
    y AS min_y,
    (x + ((width)::numeric * scale_x)) AS max_x,
    (y + ((height)::numeric * scale_y)) AS max_y,
    (x + (((width)::numeric * scale_x) / (2)::numeric)) AS center_x,
    (y + (((height)::numeric * scale_y) / (2)::numeric)) AS center_y
   FROM map_objects o;;
CREATE OR REPLACE VIEW "public"."vandrith_map_object_obb_collisions" AS
 SELECT c.other_object_id,
    c.collision
   FROM (map_objects m
     CROSS JOIN LATERAL find_map_object_obb_collisions_v1(m.id) c(other_object_id, collision))
  WHERE c.collision;;
CREATE OR REPLACE VIEW "public"."vandrith_map_objects" AS
 SELECT o.id,
    o.map_id,
    o.layer_id,
