    o.entity_type,
    o.entity_id,
    o.x,
    o.y,
    o.rotation,
    o.scale_x,
    o.scale_y,
    o.z_index,
    o.collision_enabled,
    o.interactable,
    o.footprint,
    o.properties,
    o.created_at,
    o.updated_at,
    o.object_type,
    o.width,
    o.height,
    o.blocks_los,
    a.name AS asset_name,
    a.status AS asset_status
   FROM (map_objects o
     LEFT JOIN asset_registry a ON ((a.id = o.asset_id)));;
CREATE OR REPLACE VIEW "public"."vandrith_navigation_obstacles" AS
 SELECT id,
