   FROM map_navigation_obstacles;;
CREATE OR REPLACE VIEW "public"."vandrith_object_footprints" AS
 SELECT id AS object_id,
    map_id,
    asset_id,
    object_type,
    x,
    y,
    width,
    height,
    rotation,
    layer_id,
    collision_enabled,
    footprint,
    properties
   FROM map_objects o;;
CREATE OR REPLACE VIEW "public"."vandrith_security_definer_rpc_audit" AS
 SELECT p.proname AS function_name,
    pg_get_function_identity_arguments(p.oid) AS args,
    p.prosecdef AS security_definer,
    COALESCE(array_to_string(p.proconfig, ', '::text), ''::text) AS function_config,
    has_function_privilege('anon'::name, p.oid, 'EXECUTE'::text) AS anon_execute,
    has_function_privilege('authenticated'::name, p.oid, 'EXECUTE'::text) AS authenticated_execute,
        CASE
            WHEN (p.prosecdef AND has_function_privilege('authenticated'::name, p.oid, 'EXECUTE'::text)) THEN 'EXPOSED_AUTHENTICATED'::text
            WHEN p.prosecdef THEN 'INTERNAL_OR_SERVICE_ONLY'::text
            ELSE 'INVOKER'::text
        END AS exposure_class,
        CASE
            WHEN (p.prosecdef AND has_function_privilege('authenticated'::name, p.oid, 'EXECUTE'::text) AND (p.prosrc ~~* '%auth.uid()%'::text)) THEN 'AUTH_GUARD_PRESENT'::text
            WHEN (p.prosecdef AND has_function_privilege('authenticated'::name, p.oid, 'EXECUTE'::text)) THEN 'REVIEW_AUTH_GUARD'::text
            ELSE 'NOT_APPLICABLE'::text
        END AS auth_guard_status
   FROM (pg_proc p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
  WHERE ((n.nspname = 'public'::name) AND (p.prokind = 'f'::"char") AND (p.prosecdef = true));;
CREATE OR REPLACE VIEW "public"."vandrith_terrain_rule_status" AS
 SELECT r.rule_key,
    r.category,
    r.terrain_type,
    r.mode,
    r.tile_size,
    r.enabled,
    (count(t.id))::integer AS mask_count,
    (count(t.asset_id))::integer AS bound_asset_count,
    (count(t.id) FILTER (WHERE (t.asset_id IS NULL)))::integer AS unbound_mask_count
   FROM (map_terrain_rules r
     LEFT JOIN map_terrain_rule_tiles t ON ((t.rule_id = r.id)))
  GROUP BY r.id;;
CREATE OR REPLACE VIEW "public"."vandrith_unified_object_placement" AS
 SELECT o.id,
    o.map_id,
    o.layer_id,
    o.asset_id,
    o.entity_type,
    o.entity_id,
    o.x,
    o.y,
    o.rotation,
    o.scale_x,
    o.scale_y,
    o.z_index,
    o.collision_enabled,
    o.interactable,
    o.footprint,
    o.properties,
    o.created_at,
    o.updated_at,
    o.object_type,
    o.width,
    o.height,
    o.blocks_los,
    s.selection_key
   FROM (map_objects o
     LEFT JOIN map_editor_selections s ON (((s.entity_id = o.id) AND (s.entity_type = 'map_object'::text))));;
CREATE OR REPLACE VIEW "public"."world_asset_browser_inventory_v1" AS
 SELECT a.id,
    a.external_key,
    a.name,
    a.slug,
    a.category,
    a.placement_category,
    a.role,
    a.asset_path,
    a.preview_path,
    a.grid_width,
    a.grid_height,
    a.tile_width,
    a.tile_height,
    a.perspective,
    a.palette_family,
    a.outline_style,
    a.lighting_direction,
    a.season_capable,
    a.autotile_capable,
    a.collision_capable,
    a.interactable,
    a.status AS asset_status,
    a.metadata AS asset_metadata,
    s.id AS source_id,
    s.name AS source_name,
    s.slug AS source_slug,
    s.source_url,
    s.repository_url,
    s.version AS source_version,
    s.audit_status AS source_audit_status,
    l.id AS license_registry_id,
    l.licenses,
    l.attribution_required,
    l.attribution_text,
    l.commercial_use_allowed,
    l.modification_allowed,
    l.redistribution_allowed,
    l.verification_status AS license_verification_status,
    l.usage_status AS license_usage_status
   FROM ((asset_registry a
     JOIN asset_sources s ON ((s.id = a.source_id)))
     LEFT JOIN asset_license_registry l ON ((l.id = a.license_registry_id)))
  WHERE (a.asset_path ~~ 'ASSET_LIBRARY/02_TILES_AND_TERRAIN/%'::text);;
CREATE OR REPLACE VIEW "public"."world_asset_credits_v1" AS
 SELECT lr.id AS license_registry_id,
    lr.source_repository,
    lr.authors,
    lr.licenses,
    lr.source_urls,
    lr.attribution_required,
    lr.attribution_text,
    lr.commercial_use_allowed,
    lr.modification_allowed,
    lr.redistribution_allowed,
    lr.usage_status,
    (count(ar.id))::integer AS asset_count,
    array_agg(ar.name ORDER BY ar.name) AS asset_names,
    array_agg(ar.external_key ORDER BY ar.external_key) AS asset_external_keys,
    concat_ws('
'::text, NULLIF(btrim(lr.attribution_text), ''::text),
        CASE
            WHEN (cardinality(lr.licenses) > 0) THEN ('License: '::text || array_to_string(lr.licenses, ' / '::text))
            ELSE NULL::text
        END,
        CASE
            WHEN (cardinality(lr.source_urls) > 0) THEN ('Source: '::text || array_to_string(lr.source_urls, ', '::text))
            ELSE NULL::text
        END) AS credit_block
   FROM (asset_license_registry lr
     JOIN asset_registry ar ON ((ar.license_registry_id = lr.id)))
  WHERE ((ar.asset_path ~~ 'ASSET_LIBRARY/02_TILES_AND_TERRAIN/%'::text) AND (ar.status = 'approved'::text))
  GROUP BY lr.id, lr.source_repository, lr.authors, lr.licenses, lr.source_urls, lr.attribution_required, lr.attribution_text, lr.commercial_use_allowed, lr.modification_allowed, lr.redistribution_allowed, lr.usage_status;;
CREATE OR REPLACE VIEW "public"."world_asset_manifest_v1" AS
 SELECT m.asset_id,
    a.name,
    a.asset_path,
    a.preview_path,
    a.category,
    a.placement_category,
    a.source_id,
    m.world_role,
    m.selection_status,
    m.evidence_source,
    m.evidence_note,
    f.file_type,
    f.byte_size,
    f.width,
    f.height,
    f.sha256,
    f.verification_status
   FROM ((world_asset_manifest m
     JOIN asset_registry a ON ((a.id = m.asset_id)))
     LEFT JOIN asset_files f ON ((f.asset_id = m.asset_id)))
  WHERE (a.status = 'approved'::text);;

