CREATE INDEX idx_completion_transitions_schedule ON public.activity_completion_transitions USING btree (schedule_id, transition_time);
CREATE INDEX idx_activity_food_consumptions_item ON public.activity_food_consumptions USING btree (item_id);
CREATE INDEX idx_activity_interruptions_activity_id ON public.activity_interruptions USING btree (activity_id);
CREATE INDEX idx_activity_inventory_requirements_item_type ON public.activity_inventory_requirements USING btree (item_type);
