CREATE INDEX idx_ai_archetype_activity_policies_activity ON public.ai_archetype_activity_policies USING btree (activity_definition_id);
CREATE INDEX idx_ai_goal_activity_rules_goal ON public.ai_goal_activity_rules USING btree (goal_type);
CREATE INDEX ai_improvement_evaluations_owner_created_idx ON public.ai_improvement_evaluations USING btree (owner_id, created_at DESC);
CREATE INDEX ai_improvement_evaluations_task_idx ON public.ai_improvement_evaluations USING btree (task_id, created_at DESC);
CREATE INDEX ai_improvement_proposals_evaluation_idx ON public.ai_improvement_proposals USING btree (evaluation_id);
CREATE INDEX ai_improvement_proposals_owner_created_idx ON public.ai_improvement_proposals USING btree (owner_id, created_at DESC);
CREATE INDEX idx_asset_binary_verifications_status ON public.asset_binary_verifications USING btree (verification_status);
CREATE INDEX idx_asset_binding_candidates_asset ON public.asset_binding_candidates USING btree (asset_id);
CREATE INDEX idx_asset_binding_candidates_terrain ON public.asset_binding_candidates USING btree (terrain_type_id, candidate_status);
