ALTER TABLE "public"."activities" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "activities_select_own" ON "public"."activities" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM user_lives ul
  WHERE ((ul.user_id = ( SELECT auth.uid() AS uid)) AND (ul.life_id = activities.actor_life_id)))));
