   FROM (asset_registry a
     JOIN asset_license_registry l ON ((l.id = a.license_registry_id)))
  WHERE ((a.id = asset_manifest.asset_id) AND (a.status = 'approved'::text) AND (l.verification_status = 'verified'::text) AND (l.usage_status = ANY (ARRAY['allowed'::text, 'credit_required'::text]))))));
