   FROM user_lives ul
  WHERE ((ul.user_id = ( SELECT auth.uid() AS uid)) AND (ul.life_id = container_access.life_id)))) OR (EXISTS ( SELECT 1
   FROM (containers c
     JOIN user_lives ul ON (((ul.user_id = ( SELECT auth.uid() AS uid)) AND (ul.life_id = c.owner_life_id))))
  WHERE (c.id = container_access.container_id)))));
