   FROM user_lives ul
  WHERE ((ul.user_id = ( SELECT auth.uid() AS uid)) AND (ul.life_id = containers.owner_life_id)))) OR (EXISTS ( SELECT 1
   FROM (container_access ca
     JOIN user_lives ul ON ((ul.life_id = ca.life_id)))
  WHERE ((ul.user_id = ( SELECT auth.uid() AS uid)) AND (ca.container_id = containers.id) AND ((ca.expires_at IS NULL) OR (ca.expires_at > now())))))));
